# ---- [PACK118] importar los datos de otra instalacion (carpeta "widget_arena_data" o copia completa .zip) ---------------------
IMPORT_MEDIA = ("sticky", "images", "frames")                    # imagenes que usan las notas: no viajan en los .json
IMPORT_SKIP_DIRS = ("cache", "backups", "backups_programa", "config_backups", "web_data", "logs", "previews")
IMPORT_MAX_BYTES = 3 * 1024 ** 3
_IMP_EXT = re.compile(r'\.(png|jpe?g|gif|webp|bmp|svg|ico|tiff?|apng)$', re.I)
_IMP_SEG = re.compile(r'(?:^|/)(sticky|images|frames)/([^/].*)$')


def import_is_root(d):
    j = os.path.join
    return any(os.path.exists(j(d, *p)) for p in (("data", "widget_set.json"), ("profiles",), ("templates",), ("sticky",),
                                                    ("images",), ("frames",), ("sets_en_memoria",)))


def import_find_root(path):
    """Carpeta de datos que hay en 'path': la propia, 'widget_arena_data' dentro de ella o dentro de una subcarpeta cercana. None si no hay."""
    path = os.path.abspath(path)
    if os.path.basename(path) == "data" and import_is_root(os.path.dirname(path)):
        return os.path.dirname(path)
    level = [path]
    for _i in range(4):
        nxt = []
        for d in level:
            if import_is_root(d):
                return d
            try:
                subs = sorted(os.listdir(d), key=lambda n: (n != DATA_DIRNAME, n.lower()))
            except OSError:
                continue
            for n in subs:
                p = os.path.join(d, n)
                if n not in IMPORT_SKIP_DIRS and not n.startswith('.') and os.path.isdir(p) and not os.path.islink(p):
                    nxt.append(p)

        level = nxt[:300]
    return None


def import_extract_zip(zpath, dest):
    """Descomprime un .zip (copia completa o la carpeta de datos comprimida) en 'dest' sin salirse de el ni traer cache ni copias."""
    import zipfile
    total = 0
    with zipfile.ZipFile(zpath) as z:
        for info in z.infolist():
            name = info.filename.replace('\\', '/')
            parts = [p for p in name.split('/') if p]
            if info.is_dir() or not parts or name.startswith('/') or '..' in parts or re.match(r'^[A-Za-z]:', parts[0]):
                continue
            if parts[0] in IMPORT_SKIP_DIRS or (len(parts) > 1 and parts[0] == DATA_DIRNAME and parts[1] in IMPORT_SKIP_DIRS):
                continue
            total += info.file_size
            if total > IMPORT_MAX_BYTES:
                raise ValueError("el archivo descomprimido es demasiado grande")
            out = os.path.join(dest, *parts)
            os.makedirs(os.path.dirname(out), exist_ok=True)
            with z.open(info) as src, open(out, 'wb') as dst:
                shutil.copyfileobj(src, dst)

    return dest


def _imp_json(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            d = json.load(f)
        return d if isinstance(d, dict) else None
    except Exception:
        return None


def _imp_notes(d):
    return {k: v for k, v in (d or {}).items() if isinstance(v, dict) and isinstance(v.get('template_data'), dict)}


def _imp_names(root, sub, ext=".json"):
    d = os.path.join(root, *sub)
    try:
        return sorted(f for f in os.listdir(d) if f.lower().endswith(ext) and os.path.isfile(os.path.join(d, f)))
    except OSError:
        return []


def import_scan(root):
    """Que hay para traer en esa carpeta de datos (solo cuentas: no se lee nada secreto)."""
    j = os.path.join
    ws = _imp_json(j(root, "data", "widget_set.json")) or {}
    media = {}
    for sub in IMPORT_MEDIA:
        media[sub] = sum(len(fs) for _r, _d, fs in os.walk(j(root, sub)))
    return {"root": root, "notes": len(_imp_notes(ws)),
            "settings": len([k for k, v in ws.items() if not isinstance(v, dict) and not str(k).startswith('telegram') and k != 'current_profile']),
            "telegram": any(str(k).startswith('telegram') and v for k, v in ws.items() if not isinstance(v, dict)),
            "profiles": _imp_names(root, ("profiles",)), "resident": _imp_names(root, ("sets_en_memoria",)),
            "templates": _imp_names(root, ("templates",)), "hotkeys": os.path.isfile(j(root, "data", "hotkeys.json")),
            "hotkey_profiles": _imp_names(root, ("data", "hotkey_profiles")), "media": media}


def import_copy_media(root):
    """Copia sticky/, images/ y frames/ sin pisar nada: lo que ya esta igual se salta y lo que tiene el mismo nombre pero distinto
    contenido entra con otro nombre. Devuelve (copiados, ya_estaban, {ruta_vieja: ruta_nueva})."""
    new = same = 0
    renames = {}
    for sub in IMPORT_MEDIA:
        src_root, dst_root = os.path.join(root, sub), os.path.join(ROOT_DATA_DIR, sub)
        for r, dirs, fs in os.walk(src_root):
            dirs[:] = [d for d in dirs if not os.path.islink(os.path.join(r, d))]
            for f in fs:
                s = os.path.join(r, f)
                if os.path.islink(s):
                    continue
                rel = os.path.relpath(s, src_root).replace(os.sep, '/')
                d = os.path.join(dst_root, *rel.split('/'))
                if os.path.exists(d):
                    if os.path.getsize(d) == os.path.getsize(s) and _sha256_file(d) == _sha256_file(s):
                        same += 1
                        continue
                    stem, ext = os.path.splitext(d)
                    k = 1
                    while os.path.exists(d):
                        d = "%s (importado%s)%s" % (stem, "" if k == 1 else " %d" % k, ext)
                        k += 1
                    renames["%s/%s" % (sub, rel)] = "%s/%s" % (sub, os.path.relpath(d, dst_root).replace(os.sep, '/'))
                os.makedirs(os.path.dirname(d), exist_ok=True)
                shutil.copy2(s, d)
                new += 1

    return new, same, renames


def import_fix_paths(obj, renames=None):
    """Recorre un JSON (en el sitio) y deja las rutas de imagenes en la forma portable 'widget_arena_data/sticky/...', tambien las absolutas
    de otro equipo o de Windows, siempre que el archivo ya este aqui. Devuelve cuantas rutas cambio."""
    renames = renames or {}
    n = [0]

    def fix(s):
        if len(s) > 400 or '<' in s or '\n' in s or not _IMP_EXT.search(s):
            return s
        q = s.strip().replace('\\', '/')
        if q.lower().startswith(('http://', 'https://', 'data:')):
            return s
        m = _IMP_SEG.search(q)
        if not m:
            return s
        rel = "%s/%s" % (m.group(1), m.group(2))
        rel = renames.get(rel, rel)
        if not os.path.isfile(os.path.join(ROOT_DATA_DIR, *rel.split('/'))):
            return s
        out = DATA_DIRNAME + '/' + rel
        if os.path.normpath(out) == os.path.normpath(s):
            return s
        n[0] += 1
        return out

    def walk(o):
        if isinstance(o, dict):
            for k in list(o.keys()):
                v = o[k]
                o[k] = fix(v) if isinstance(v, str) else (walk(v) if isinstance(v, (dict, list)) else v)
        elif isinstance(o, list):
            for i, v in enumerate(o):
                o[i] = fix(v) if isinstance(v, str) else (walk(v) if isinstance(v, (dict, list)) else v)
        return o
    walk(obj)
    return n[0]


TREE_MAX_FILE = 25 * 1024 * 1024               # [PACK120] tope por imagen y en total al exportar un arbol
TREE_MAX_TOTAL = 100 * 1024 * 1024


def tree_collect_images(notes):
    """Imagenes de capa que usan estas notas (las notas base que el programa redibuja desde sus parametros no hacen falta). Reescribe sus
    rutas a la forma portable 'widget_arena_data/<carpeta>/<nombre>' y devuelve ({'images/x.png': bytes}, [las que no se encontraron o no caben])."""
    out, used, skipped, total = {}, {}, [], 0
    for st in notes.values():
        td = st.get('template_data') if isinstance(st, dict) else None
        if not isinstance(td, dict):
            continue
        for L in ('layer1', 'layer2'):
            ld = td.get(L)
            if not isinstance(ld, dict) or ld.get('type') in ('text', 'web'):
                continue
            c = ld.get('content')
            if not isinstance(c, str) or not c.strip() or '<' in c or not _IMP_EXT.search(c) or c.strip().lower().startswith(('http://', 'https://', 'data:')):
                continue
            if L == 'layer2' and _is_generated_layer(td):
                continue
            real = _find_stored_file(c)
            if not real:
                skipped.append(os.path.basename(c.replace('\\', '/')))
                continue
            if real not in used:
                try:
                    size = os.path.getsize(real)
                    if size > TREE_MAX_FILE or total + size > TREE_MAX_TOTAL:
                        skipped.append(os.path.basename(real))
                        continue
                    with open(real, 'rb') as f:
                        data = f.read()
                except OSError:
                    skipped.append(os.path.basename(real))
                    continue
                r = os.path.relpath(real, ROOT_DATA_DIR).replace(os.sep, '/')
                rel = r if r.split('/')[0] in IMPORT_MEDIA and not r.startswith('..') else 'images/' + os.path.basename(real)
                stem, ext = os.path.splitext(rel)
                k = 2
                while rel in out:
                    rel = "%s (%d)%s" % (stem, k, ext)
                    k += 1
                out[rel] = data
                used[real] = rel
                total += len(data)
            ld['content'] = DATA_DIRNAME + '/' + used[real]

    return out, sorted(set(skipped))


BACKUP_MAX_FILE = 120 * 1024 * 1024            # [PACK125] topes de las imagenes en una copia completa (una sola imagen / total)
BACKUP_MAX_TOTAL = 1500 * 1024 * 1024
_BACKUP_STORED = ('.png', '.jpg', '.jpeg', '.gif', '.webp', '.apng')          # ya vienen comprimidas: se guardan tal cual


def backup_media_from_texts(texts):
    """Imagenes que nombran estos textos JSON (set activo, sets, widgets guardados). Devuelve
    ({'sticky/x.png': ruta_real}, [las que estan fuera de la carpeta de datos], [las que no se encuentran])."""
    found, outside, missing = {}, set(), set()
    seen = set()

    def one(s):
        if len(s) > 400 or '<' in s or '\n' in s or s in seen or not _IMP_EXT.search(s.strip()):
            return
        seen.add(s)
        q = s.strip()
        if q.lower().startswith(('http://', 'https://', 'data:')):
            return
        real = _find_stored_file(q)
        if not real:
            if _IMP_SEG.search(q.replace('\\', '/')) or q.startswith(DATA_DIRNAME):
                missing.add(os.path.basename(q.replace('\\', '/')))
            return
        try:
            r = os.path.relpath(os.path.abspath(real), ROOT_DATA_DIR).replace(os.sep, '/')
        except ValueError:
            r = '..'
        if r.startswith('..') or r.split('/')[0] not in IMPORT_MEDIA:
            outside.add(os.path.basename(real))
        else:
            found[r] = real

    def walk(o):
        if isinstance(o, str):
            one(o)
        elif isinstance(o, dict):
            gen = isinstance(o.get('base_note'), dict) and _is_generated_layer(o)           # [PACK126] la imagen de una forma de papel se dibuja al cargar
            for k, v in o.items():
                if gen and k == 'layer2' and isinstance(v, dict):
                    walk({kk: vv for kk, vv in v.items() if kk not in ('content', 'base_hue_src')})
                else:
                    walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    for t in texts:
        try:
            walk(json.loads(t))
        except (ValueError, TypeError):
            pass
    return found, sorted(outside), sorted(missing)


def media_from_zip(zpath, names=None):
    """[PACK126] Deja en la carpeta de datos las imagenes (sticky/, images/, frames/) de un .zip sin pisar nada: lo igual se salta y lo distinto con
    el mismo nombre entra con otro. 'names' limita a esas entradas. Devuelve (copiadas, ya_estaban, {ruta_vieja: ruta_nueva})."""
    import zipfile
    import tempfile
    tmp = tempfile.mkdtemp(prefix="wa_copia_")
    try:
        with zipfile.ZipFile(zpath) as z:
            known = {}
            for n in z.namelist():
                parts = [p for p in n.replace('\\', '/').split('/') if p]
                if len(parts) >= 2 and parts[0] in IMPORT_MEDIA and '..' not in parts and not n.endswith('/') and _IMP_EXT.search(n):
                    known['/'.join(parts)] = n
            total = 0
            for nm in (list(known) if names is None else names):
                zn = known.get(nm)
                if not zn:
                    continue
                size = z.getinfo(zn).file_size
                total += size
                if size > BACKUP_MAX_FILE or total > BACKUP_MAX_TOTAL:
                    continue
                dst = os.path.join(tmp, *nm.split('/'))
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with z.open(zn) as src, open(dst, 'wb') as out:
                    shutil.copyfileobj(src, out)

        return import_copy_media(tmp)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def clip_zip_write(imgs):
    """[PACK126] Escribe en la carpeta temporal un .zip con las imagenes {'images/x.png': bytes} y devuelve su ruta (el nombre sale del
    contenido: copiar dos veces lo mismo no lo repite). Se conservan los mas recientes. None si no hay imagenes o no se pudo."""
    import zipfile
    import tempfile
    if not imgs:
        return None
    h = hashlib.sha1()
    for k in sorted(imgs):
        h.update(k.encode('utf-8', 'replace'))
        h.update(hashlib.sha1(imgs[k]).digest())
    try:
        d = os.path.join(tempfile.gettempdir(), 'widget_arena_portapapeles')
        os.makedirs(d, exist_ok=True)
        path = os.path.join(d, 'copia_%s.zip' % h.hexdigest()[:16])
        if os.path.isfile(path):
            os.utime(path)
        else:
            with zipfile.ZipFile(path + '.tmp', 'w', zipfile.ZIP_STORED) as z:
                for k in sorted(imgs):
                    z.writestr(k, imgs[k])
            os.replace(path + '.tmp', path)

        olds = sorted((f for f in os.listdir(d) if f.startswith('copia_') and f.endswith('.zip')), key=lambda f: os.path.getmtime(os.path.join(d, f)), reverse=True)
        for f in olds[12:]:
            try:
                os.remove(os.path.join(d, f))
            except OSError:
                pass
        return path
    except OSError as e:
        log_warn("Portapapeles", "No se pudo guardar el .zip temporal de las im\u00e1genes: %s" % e)
        return None


def clip_take_images(zpath, objs):
    """[PACK126] Trae las imagenes del .zip temporal que nombra un JSON copiado y reapunta las rutas de 'objs' (listas / dicts, en el sitio).
    Devuelve (copiadas, ya_estaban) o None si el .zip ya no existe."""
    if not isinstance(zpath, str) or not os.path.isfile(zpath):
        return None
    try:
        new, same, ren = media_from_zip(zpath)
    except Exception as e:
        log_warn("Portapapeles", "No se pudieron leer las im\u00e1genes copiadas: %s" % e)
        return None
    for o in objs:
        import_fix_paths(o, ren)
    return new, same


def embed_images_b64(td):
    """[PACK126] Mete en el dict de un widget guardado ('__imagenes__': {'images/x.png': base64}) las imagenes que usa y deja sus rutas portables
    (se llama sobre una copia). Devuelve (cuantas, [las que no se pudieron incluir])."""
    import base64
    imgs, skipped = tree_collect_images({'x': {'template_data': td}})
    if imgs:
        td['__imagenes__'] = {k: base64.b64encode(v).decode('ascii') for k, v in imgs.items()}
    return len(imgs), skipped


# [PACK130] Archivos propios de Widget Arena. Son un .zip con: wa.json (que es: tipo, version del programa), data.json (lo mismo que llevaba el .json de
# siempre, pero sin imagenes dentro) y las imagenes en images/, sticky/ y frames/. Se reconocen por el contenido, no por la extension.
WA_FILE_FORMAT = "widget-arena-file"
WA_FILE_EXT = {'set': '.waset', 'widget': '.wawidget', 'paper': '.wapaper', 'frame': '.waframe'}
WA_FILTER = {'set': "Widgets de Widget Arena (*.waset);;JSON antiguo (*.json)",
             'widget': "Widget guardado (*.wawidget);;JSON antiguo (*.json)",
             'paper': "Forma de papel (*.wapaper);;JSON antiguo (*.json)",
             'frame': "Marco (*.waframe);;JSON (*.json)"}
WA_OPEN_FILTER = "Archivos de Widget Arena (*.waset *.wawidget *.wapaper *.waframe);;JSON (*.json);;Todos (*)"
WA_MAX_JSON = 64 << 20


def wa_file_kind(path):
    """'set' | 'widget' | 'paper' si es un archivo .waset / .wawidget / .wapaper; None si no (un .json, una copia .zip, un pack...)."""
    import zipfile
    try:
        if not zipfile.is_zipfile(path):
            return None
        with zipfile.ZipFile(path) as z:
            if 'wa.json' not in z.namelist() or z.getinfo('wa.json').file_size > 100000:
                return None
            man = json.loads(z.read('wa.json').decode('utf-8'))
    except (OSError, ValueError, zipfile.BadZipFile, KeyError):
        return None
    if not isinstance(man, dict) or man.get('format') != WA_FILE_FORMAT or man.get('kind') not in WA_FILE_EXT:
        return None
    return man['kind']


def wa_out_path(path, kind, flt=''):
    """(ruta, es_json): respeta .json y las extensiones propias; si no hay extension pone la del filtro elegido (.json si eligio JSON) o la del tipo."""
    path = str(path)
    ext = os.path.splitext(path)[1].lower()
    if ext == '.json':
        return path, True
    if ext in WA_FILE_EXT.values():
        return path, False
    if '*.json' in str(flt) and '*.wa' not in str(flt):
        return path + '.json', True
    return path + WA_FILE_EXT[kind], False


def wa_stem(path):
    """Nombre del archivo sin la extension propia (ni .json)."""
    b = os.path.basename(str(path))
    root, ext = os.path.splitext(b)
    return root if ext.lower() in tuple(WA_FILE_EXT.values()) + ('.json',) else b


def wa_file_write(path, kind, data, imgs=None):
    """Escribe un archivo propio. data: lo que iria en el .json; imgs: {'images/x.png': bytes}."""
    import zipfile
    man = {'format': WA_FILE_FORMAT, 'format_version': 1, 'kind': kind, 'app_pack': APP_PACK,
           'created': datetime.datetime.now().isoformat(timespec='seconds'), 'images': len(imgs or {})}
    tmp = str(path) + '.tmp'
    with zipfile.ZipFile(tmp, 'w') as z:
        z.writestr('wa.json', json.dumps(man, indent=2).encode('utf-8'), zipfile.ZIP_DEFLATED)
        z.writestr('data.json', json.dumps(data, indent=2, ensure_ascii=False, default=str).encode('utf-8'), zipfile.ZIP_DEFLATED)
        for k in sorted(imgs or {}):
            z.writestr(k, imgs[k], zipfile.ZIP_STORED)
    os.replace(tmp, str(path))


def wa_file_read(path):
    """(tipo, datos) de un archivo propio. Los datos llevan, como si vinieran del portapapeles, el marcador de imagenes apuntando al propio archivo
    ('__config__.imagenes_zip' en un set, '__imagenes_zip__' en un widget guardado): al importar se traen sin pisar nada."""
    import zipfile
    kind = wa_file_kind(path)
    if kind is None:
        raise ValueError("no es un archivo de Widget Arena")
    with zipfile.ZipFile(path) as z:
        if z.getinfo('data.json').file_size > WA_MAX_JSON:
            raise ValueError("el archivo es demasiado grande")
        data = json.loads(z.read('data.json').decode('utf-8'))
    if not isinstance(data, dict):
        raise ValueError("el archivo no contiene datos validos")
    if kind == 'set':
        cfg = data.get('__config__')
        if not isinstance(cfg, dict):
            cfg = data['__config__'] = {}
        cfg['imagenes_zip'] = str(path)
    else:
        data['__imagenes_zip__'] = str(path)

    return kind, data


def read_file_any(path):
    """(tipo | None, dict) de un archivo para importar: un archivo propio (.waset / .wawidget / .wapaper) o un .json de los de siempre."""
    _k = wa_file_kind(path)
    if _k == 'frame':                                   # [PACK137] un marco no es un widget ni un set
        raise ValueError("es un marco (.waframe): se abre desde \u00abGenerar marco\u00bb (Mis marcos), el men\u00fa Marco del widget o \u00abCargar un archivo\u00bb")
    if _k:
        return wa_file_read(path)
    with open(path, 'r', encoding='utf-8') as f:
        return None, json.load(f)


def wa_export_template(path, td, kind='widget', flt=''):
    """Guarda un widget guardado o una forma de papel: .wawidget / .wapaper (comprimido, con las imagenes que use) o .json (con ellas en base64).
    Devuelve (ruta, cuantas imagenes, [las que no se pudieron incluir])."""
    path, as_json = wa_out_path(path, kind, flt)
    td = copy.deepcopy(td)
    if as_json:
        n, sk = embed_images_b64(td)
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(td, f, indent=4, ensure_ascii=False)
        return path, n, sk
    imgs, sk = tree_collect_images({'x': {'template_data': td}})
    wa_file_write(path, kind, td, imgs)
    return path, len(imgs), sk


def import_template_images(td):
    """[PACK126] Inversa: quita de un widget guardado '__imagenes__' / '__imagenes_zip__', deja las imagenes en la carpeta de datos (sin pisar) y reapunta
    las rutas. Devuelve cuantas imagenes se trajeron."""
    if not isinstance(td, dict):
        return 0
    emb = td.pop('__imagenes__', None)
    zp = td.pop('__imagenes_zip__', None)
    n = 0
    holder = {'x': {'template_data': td}}
    if isinstance(emb, dict) and emb:
        new, same = import_embedded_images({'imagenes': emb}, holder)
        n += new + same
    if zp:
        r = clip_take_images(zp, [td])
        if r:
            n += r[0] + r[1]
    return n


def import_embedded_images(cfg, notes):
    """Deja en la carpeta de datos las imagenes que viajan dentro de un archivo exportado (cfg['imagenes'] = {'images/x.png': base64}) sin pisar
    nada (si ya hay otra con ese nombre entra con otro) y reapunta las capas de 'notes'. Devuelve (nuevas, ya_estaban)."""
    zr = clip_take_images(cfg.get('imagenes_zip'), [notes]) if isinstance(cfg, dict) and cfg.get('imagenes_zip') else None      # [PACK130]
    z_new, z_same = zr if zr else (0, 0)
    imgs = cfg.get('imagenes') if isinstance(cfg, dict) else None
    if not isinstance(imgs, dict) or not imgs:
        return z_new, z_same
    import base64
    import binascii
    new = same = total = 0
    renames = {}
    for rel, b64 in imgs.items():
        parts = [p for p in str(rel).replace('\\', '/').split('/') if p]
        if len(parts) < 2 or parts[0] not in IMPORT_MEDIA or '..' in parts or not _IMP_EXT.search(parts[-1]) or not isinstance(b64, str):
            continue
        try:
            data = base64.b64decode(b64, validate=True)
        except (ValueError, binascii.Error):
            continue

        total += len(data)
        if len(data) > TREE_MAX_FILE or total > TREE_MAX_TOTAL * 2:
            continue
        d = os.path.join(ROOT_DATA_DIR, *parts)
        stem, ext = os.path.splitext(d)
        chosen = None
        for k in range(0, 40):          # el mismo nombre; si ya hay otra imagen distinta, "(importado)", "(importado 2)"... reutilizando la que sea identica
            cand = d if k == 0 else "%s (importado%s)%s" % (stem, "" if k == 1 else " %d" % k, ext)
            if not os.path.exists(cand):
                os.makedirs(os.path.dirname(cand), exist_ok=True)
                with open(cand, 'wb') as f:
                    f.write(data)
                new += 1
                chosen = cand
                break
            with open(cand, 'rb') as f:
                if f.read() == data:
                    same += 1
                    chosen = cand
                    break

        if chosen and chosen != d:
            renames['/'.join(parts)] = '/'.join(parts[:-1] + [os.path.basename(chosen)])
    import_fix_paths(notes, renames)
    return new + z_new, same + z_same


def import_missing_images(notes):
    """Imagenes de capa que usan estas notas y que no estan en esta instalacion {nombre: [ids]}. Las notas base que el programa dibuja
    de nuevo desde sus parametros no cuentan."""
    miss = {}
    for nid, st in (notes or {}).items():
        td = st.get('template_data') if isinstance(st, dict) else None
        if not isinstance(td, dict):
            continue
        for L in ('layer1', 'layer2'):
            ld = td.get(L)
            if not isinstance(ld, dict) or ld.get('type') in ('text', 'web'):
                continue
            c = ld.get('content')
            if not isinstance(c, str) or not c.strip() or '<' in c or not _IMP_EXT.search(c) or c.strip().lower().startswith(('http://', 'https://', 'data:')):
                continue
            if L == 'layer2' and _is_generated_layer(td):
                continue
            if not _find_stored_file(c):
                miss.setdefault(os.path.basename(c.replace('\\', '/')), []).append(nid)
    return miss


def import_recover_images(root, names):
    """Busca por nombre (sin distinguir mayusculas, como Windows) en sticky/, images/ y frames/ de 'root' las imagenes que faltan y copia las que
    encuentra (sin pisar nada) con el nombre con el que las usan las notas. Devuelve (copiadas, no_encontradas)."""
    want, got = {n.lower(): n for n in names}, set()
    for sub in IMPORT_MEDIA:
        base = os.path.join(root, sub)
        for r, dirs, fs in os.walk(base):
            dirs[:] = [d for d in dirs if not os.path.islink(os.path.join(r, d))]
            for f in fs:
                n = want.get(f.lower())
                if n and n not in got and not os.path.islink(os.path.join(r, f)):
                    s = os.path.join(r, f)
                    d = os.path.join(ROOT_DATA_DIR, sub, os.path.dirname(os.path.relpath(s, base)), n)
                    if not os.path.exists(d):
                        os.makedirs(os.path.dirname(d), exist_ok=True)
                        shutil.copy2(s, d)
                    got.add(n)
    return sorted(got), sorted(set(want.values()) - got)


class ImportDataDialog(QDialog):
    """[PACK118] Importar datos de otra instalaci\u00f3n: se elige la carpeta (o el .zip), se ve lo que hay y se marca lo que se quiere traer."""
    NOTE_MODES = (("replace", "Sustituir los widgets que tengo ahora"), ("add", "Agregarlos a los que tengo ahora"),
                  ("profile", "Guardarlos como un set nuevo (sin tocar lo actual)"))

    def __init__(self, manager):
        super().__init__(None)
        self.m = manager
        self.root = None
        self.info = None
        self.tmp = None
        self.setWindowTitle("Importar datos de otra instalaci\u00f3n")
        self.setAttribute(Qt.WA_QuitOnClose, False)
        self.setMinimumWidth(640)
        lay = QVBoxLayout(self)
        t1 = QLabel("Importar datos de otra instalaci\u00f3n")
        t1.setStyleSheet("font-size:18px;font-weight:bold;")
        t2 = QLabel("Trae tus widgets, sets, widgets guardados, im\u00e1genes y ajustes de una versi\u00f3n anterior o de otro equipo. Elige la carpeta "
                    "\u00abwidget_arena_data\u00bb que usaba esa versi\u00f3n (suele estar junto al programa), la carpeta que la contiene, o una copia completa .zip.\n"
                    "Antes de tocar nada se guarda una copia completa de lo que tienes, y nunca se pisa un archivo que ya exista con otro contenido: "
                    "entra con otro nombre.")
        t2.setWordWrap(True)
        t2.setStyleSheet("color:#9aa0aa;")

        lay.addWidget(t1)
        lay.addWidget(t2)
        row = QHBoxLayout()
        self.path = QLineEdit()
        self.path.setPlaceholderText("Carpeta o archivo .zip de la otra instalaci\u00f3n")
        self.path.returnPressed.connect(self._typed)
        b_dir = QPushButton("Carpeta...")
        b_dir.clicked.connect(self._pick_dir)
        b_zip = QPushButton("Archivo .zip...")
        b_zip.clicked.connect(self._pick_zip)
        row.addWidget(self.path, 1)
        row.addWidget(b_dir)
        row.addWidget(b_zip)
        lay.addLayout(row)
        self.status = QLabel("")
        self.status.setWordWrap(True)
        self.status.setStyleSheet("background:#2b2b2f;color:#e8e8ee;border-radius:6px;padding:8px;")
        lay.addWidget(self.status)

        self.chk = {}
        for key in ("notes", "profiles", "templates", "media", "settings", "hotkeys", "telegram"):
            c = QCheckBox("")
            c.setChecked(True)
            self.chk[key] = c
            lay.addWidget(c)
            if key == "notes":
                self.mode = QComboBox()
                for k, label in self.NOTE_MODES:
                    self.mode.addItem(label, k)
                mrow = QHBoxLayout()
                mrow.addSpacing(26)
                mrow.addWidget(self.mode, 1)
                lay.addLayout(mrow)
        btns = QHBoxLayout()
        btns.addStretch(1)
        cancel = QPushButton("Cancelar")
        cancel.clicked.connect(self.close)

        self.go = QPushButton("Importar")
        self.go.setStyleSheet("QPushButton{font-weight:bold;padding:8px 18px;}")
        self.go.setDefault(True)
        self.go.clicked.connect(self._run)
        btns.addWidget(cancel)
        btns.addWidget(self.go)
        lay.addLayout(btns)
        self._fill()

    def _cleanup(self):
        if self.tmp:
            shutil.rmtree(self.tmp, ignore_errors=True)
            self.tmp = None

    def closeEvent(self, e):
        self._cleanup()
        super().closeEvent(e)

    def _start_dir(self):
        p = self.path.text().strip()
        return p if p and os.path.isdir(p) else os.path.expanduser("~")

    def _pick_dir(self):
        d = QFileDialog.getExistingDirectory(self, "Carpeta de datos de la otra instalaci\u00f3n", self._start_dir())
        if d:
            self.load_source(d)

    def _pick_zip(self):
        f, _ = QFileDialog.getOpenFileName(self, "Copia completa (.zip)", self._start_dir(), "Copias (*.zip)")
        if f:
            self.load_source(f)

    def _typed(self):
        p = self.path.text().strip()
        if p:
            self.load_source(os.path.expanduser(p))

    def load_source(self, path):
        """Mira que hay en la carpeta o el .zip. Devuelve True si encontro datos."""
        import zipfile
        import tempfile
        self._cleanup()
        self.root = self.info = None
        self.path.setText(path)
        try:
            src = path
            if os.path.isfile(src):
                if not zipfile.is_zipfile(src):
                    raise ValueError("Elige una carpeta o un archivo .zip.")
                self.tmp = tempfile.mkdtemp(prefix="wa_importar_")
                import_extract_zip(src, self.tmp)
                src = self.tmp
            elif not os.path.isdir(src):
                raise ValueError("No existe esa carpeta.")
            root = import_find_root(src)
            if not root:
                raise ValueError("No encuentro datos de Widget Arena ah\u00ed (busco data/widget_set.json, profiles, widgets guardados, sticky...).")
            if os.path.abspath(root) == os.path.abspath(ROOT_DATA_DIR):
                raise ValueError("Esa es la carpeta de datos de esta misma instalaci\u00f3n.")
            self.root, self.info = root, import_scan(root)
        except Exception as e:
            self._cleanup()
            self.status.setText(str(e) or e.__class__.__name__)
            self._fill()
            return False

        self._fill()
        return True

    def _fill(self):
        i = self.info
        self.go.setEnabled(bool(i))
        if i:
            self.status.setText("Encontrado en: %s" % self.root)
        elif not self.status.text():
            self.status.setText("Elige la carpeta o el .zip para ver qu\u00e9 se puede importar.")
        nm = sum(i["media"].values()) if i else 0
        rows = {"notes": ("Mis widgets (%d)" % i["notes"] if i else "Mis widgets", bool(i and i["notes"])),
                "profiles": ("Sets (%d)" % (len(i["profiles"]) + len(i["resident"])) if i else "Sets", bool(i and (i["profiles"] or i["resident"]))),
                "templates": ("Widgets guardados (%d)" % len(i["templates"]) if i else "Widgets guardados", bool(i and i["templates"])),
                "media": ("Im\u00e1genes, marcos y formas de papel (%d archivos)" % nm if i else "Im\u00e1genes, marcos y formas de papel", nm > 0),
                "settings": ("Ajustes generales (%d)" % i["settings"] if i else "Ajustes generales", bool(i and i["settings"])),
                "hotkeys": ("Atajos de teclado", bool(i and i["hotkeys"])),
                "telegram": ("Conexi\u00f3n con Telegram (bot y chat)", bool(i and i["telegram"]))}
        for k, (text, has) in rows.items():
            c = self.chk[k]
            c.setText(text if (has or not i) else text + "  \u00b7  no hay")
            c.setEnabled(has)
            c.setChecked(has)

        self.mode.setEnabled(bool(i and i["notes"]))

    def options(self):
        o = {k: c.isEnabled() and c.isChecked() for k, c in self.chk.items()}
        o["notes"] = self.mode.currentData() if o["notes"] else None
        return o

    def _run(self):
        if not self.info or not self.root:
            return
        o = self.options()
        if not any(o.values()):
            self.status.setText("Marca algo para importar.")
            return
        if o["notes"] == "replace":
            have = len([1 for v in self.m.global_state.values() if isinstance(v, dict) and isinstance(v.get('template_data'), dict)])
            if have and QMessageBox.question(self, "Importar", "Se sustituir\u00e1n tus %d widgets actuales por los de la copia. Antes se guarda una copia "
                                             "completa, as\u00ed que se puede volver atr\u00e1s.\n\n\u00bfContinuar?" % have) != QMessageBox.Yes:
                return
        self.go.setEnabled(False)
        try:
            rep = self.m.import_data(self.root, o)
        except Exception as e:
            log_error("Importar", "%s" % e)
            self.go.setEnabled(True)
            QMessageBox.warning(self, "Importar", "No se pudo completar la importaci\u00f3n:\n%s" % e)
            return

        QMessageBox.information(self, "Importar", "Importaci\u00f3n terminada:\n\n" + "\n".join("\u2022 " + r for r in rep))
        self.close()


class FontChooserDialog(QDialog):
    """[PACK113] Fuente predeterminada, con muestras: cada opcion ense\u00f1a una nota escrita con esa fuente. Es la de las notas nuevas
    y la que sustituye a una fuente que falta (por ejemplo Segoe Print fuera de Windows). [PACK115] tarjetas con nota de muestra."""
    SAMPLE = "<b>Llamar a Marta</b><br>Comprar caf\u00e9 y filtros &middot; reuni\u00f3n a las 10:00"
    NOTE_CSS = "QLabel{background:#fff3a6;color:#1f2937;border:1px solid #d9b94a;border-radius:6px;padding:10px 14px;}"

    def __init__(self, manager, first_run=False):
        super().__init__(None)
        from PySide6.QtWidgets import QScrollArea, QButtonGroup
        self.m = manager
        self.first_run = first_run
        self.setWindowTitle("Elige la fuente de tus notas" if first_run else "Fuente predeterminada")
        self.setAttribute(Qt.WA_QuitOnClose, False)
        if first_run:
            self.setWindowFlag(Qt.WindowStaysOnTopHint, True)
        self.resize(640, 660)
        root = QVBoxLayout(self)
        t1 = QLabel("Elige la fuente de tus notas")
        t1.setStyleSheet("font-size:18px;font-weight:bold;")
        t2 = QLabel("As\u00ed se ver\u00e1n tus notas con cada fuente. Se usa en las notas nuevas y sustituye a la de un widget cuando esa no est\u00e1 instalada "
                    "(por ejemplo \u00abSegoe Print\u00bb fuera de Windows). Puedes cambiarla cuando quieras en Ajustes \u2192 Apariencia \u2192 Fuente predeterminada.")
        t2.setWordWrap(True)
        t2.setStyleSheet("color:#9aa0aa;")
        root.addWidget(t1)
        root.addWidget(t2)
        self.opts = []                      # (radio, familia, nota de muestra, aviso)
        self.cards = []
        self.group = QButtonGroup(self)
        host = QWidget()
        self.vl = QVBoxLayout(host)
        self.vl.setContentsMargins(0, 0, 6, 0)
        cur = font_cfg().get('default_font')
        names = list(dict.fromkeys(f[0] for f in FREE_FONTS))
        if font_installed("Segoe Print"):
            names.append("Segoe Print")
        for fam in names:
            self._add_option(fam, FREE_FONT_INFO.get(fam, "La de Windows que usan las notas de ejemplo." if fam == "Segoe Print" else ""))
        self._add_option("Inter", "La de siempre en Widget Arena (si no est\u00e1 instalada, la del sistema).")
        # otra fuente del equipo: con su muestra
        card = _FontCard()
        card.setObjectName("fcard")
        cl = QVBoxLayout(card)
        head = QHBoxLayout()
        self.rb_other = QRadioButton("Otra fuente de este equipo:")
        self.rb_other.setStyleSheet("font-weight:bold;")
        self.group.addButton(self.rb_other)
        self.other = QFontComboBox()
        self.other.currentFontChanged.connect(self._other_changed)
        head.addWidget(self.rb_other)
        head.addWidget(self.other, 1)
        cl.addLayout(head)
        self.other_sample = QLabel(self.SAMPLE)
        self.other_sample.setStyleSheet(self.NOTE_CSS)
        self.other_sample.setTextFormat(Qt.RichText)
        self.other_sample.setWordWrap(True)
        cl.addWidget(self.other_sample)
        card.clicked.connect(self.rb_other.click)
        self.vl.addWidget(card)
        self.cards.append((card, self.rb_other))
        self.vl.addStretch(1)
        sc = QScrollArea()
        sc.setWidgetResizable(True)
        sc.setFrameShape(QFrame.NoFrame)
        sc.setWidget(host)
        root.addWidget(sc, 1)
        sel = False
        for rb, fam, _lb, _w in self.opts:
            if cur == fam:
                rb.setChecked(True)
                sel = True
        if not sel and isinstance(cur, str) and cur.strip():
            self.rb_other.setChecked(True)
            self.other.setCurrentFont(QFont(cur))
        elif not sel:
            self.opts[0][0].setChecked(True)             # Kalam: la mas parecida a Segoe Print
        self.group.buttonToggled.connect(self._sync_cards)
        self.status = QLabel("")
        self.status.setStyleSheet("color:#9aa0aa;")
        root.addWidget(self.status)
        btns = QHBoxLayout()
        btns.addStretch(1)
        later = QPushButton("M\u00e1s tarde" if first_run else "Cancelar")
        later.clicked.connect(self._later)
        ok = QPushButton("Usar esta fuente")
        ok.setStyleSheet("QPushButton{font-weight:bold;padding:8px 18px;}")
        ok.setDefault(True)
        ok.clicked.connect(self._accept)
        btns.addWidget(later)
        btns.addWidget(ok)
        root.addLayout(btns)
        self._sync_cards()
        self.refresh_fonts()

    def _add_option(self, fam, info):
        card = _FontCard()
        card.setObjectName("fcard")
        row = QHBoxLayout(card)
        left = QVBoxLayout()
        rb = QRadioButton(fam)
        rb.setStyleSheet("font-weight:bold;")
        self.group.addButton(rb)
        wr = QLabel(info)
        wr.setWordWrap(True)
        wr.setStyleSheet("color:#9aa0aa;padding-left:22px;")
        left.addWidget(rb)
        left.addWidget(wr)
        left.addStretch(1)
        lb = QLabel(self.SAMPLE)
        lb.setTextFormat(Qt.RichText)
        lb.setWordWrap(True)
        lb.setStyleSheet(self.NOTE_CSS)
        lb.setMinimumWidth(300)
        row.addLayout(left, 2)
        row.addWidget(lb, 3)
        card.clicked.connect(rb.click)
        self.vl.addWidget(card)
        self.cards.append((card, rb))
        self.opts.append((rb, fam, lb, wr))

    def _other_changed(self, _f=None):
        self.rb_other.setChecked(True)
        self.other_sample.setFont(QFont(self.other.currentFont().family(), 15))

    def _sync_cards(self, *_a):
        for card, rb in self.cards:
            card.setStyleSheet("QFrame#fcard{border:2px solid %s;border-radius:8px;}" % ("#4f8cff" if rb.isChecked() else "transparent"))

    def refresh_fonts(self):
        """Pinta cada muestra con su fuente; las que aun no se han descargado se marcan."""
        wait = False
        for rb, fam, lb, wr in self.opts:
            ok = font_installed(fam) or fam == "Inter"
            lb.setFont(QFont(fam, 15) if ok else QFont("", 15))
            if not ok:
                wait = True
            base = FREE_FONT_INFO.get(fam, "La de Windows que usan las notas de ejemplo." if fam == "Segoe Print" else
                                      "La de siempre en Widget Arena (si no est\u00e1 instalada, la del sistema).")
            wr.setText(base if ok else base + "  \u00b7  Descarg\u00e1ndose...")
        self.other_sample.setFont(QFont(self.other.currentFont().family(), 15))
        self.status.setText("Descargando las fuentes libres... las muestras se actualizar\u00e1n solas." if wait else "")

    def chosen(self):
        if self.rb_other.isChecked():
            return self.other.currentFont().family()
        for rb, fam, _lb, _w in self.opts:
            if rb.isChecked():
                return fam
        return "Inter"

    def _later(self):
        if self.first_run:
            font_cfg()['asked'] = True
            font_cfg_save()
        self.close()

    def _accept(self):
        fam = self.chosen()
        font_set_default(fam)
        self.m.font_refresh_widgets()
        self.close()


class FontExportDialog(QDialog):
    """[PACK113] \u00bfExportar fuentes? Lista las que usa el pack, con lo que se puede hacer con cada una y d\u00f3nde funcionar\u00e1."""

    def __init__(self, parent, rows):
        super().__init__(parent)
        from PySide6.QtWidgets import QTreeWidget, QTreeWidgetItem
        self.rows = rows
        self.setWindowTitle("Exportar fuentes")
        self.resize(960, 440)
        root = QVBoxLayout(self)
        t1 = QLabel("\u00bfExportar fuentes?")
        t1.setStyleSheet("font-size:18px;font-weight:bold;")
        t2 = QLabel("Estas son las fuentes que usan los widgets guardados y sets elegidos. Las que se incluyen van dentro del pack y funcionan en "
                    "Windows, macOS y Linux. Las dem\u00e1s no se pueden o no hace falta incluirlas: si faltan, se ver\u00e1 una fuente parecida.")
        t2.setWordWrap(True)
        t2.setStyleSheet("color:#9aa0aa;")
        root.addWidget(t1)
        root.addWidget(t2)
        self.tree = QTreeWidget()
        self.tree.setColumnCount(3)
        self.tree.setHeaderLabels(["Fuente", "Estado", "D\u00f3nde funciona"])

        self.tree.setRootIsDecorated(False)
        self.tree.setWordWrap(True)
        self.tree.setColumnWidth(0, 150)
        self.tree.setColumnWidth(1, 430)
        for r in rows:
            it = QTreeWidgetItem([r['family'], r['status'], r['where']])
            fl = it.flags()
            if r['enabled']:
                it.setFlags(fl | Qt.ItemIsUserCheckable)
                it.setCheckState(0, Qt.Checked if r['checked'] else Qt.Unchecked)
            else:
                it.setFlags(fl & ~Qt.ItemIsUserCheckable)
            for c in (1, 2):
                it.setToolTip(c, it.text(c))
            self.tree.addTopLevelItem(it)
        self.tree.itemChanged.connect(self._sync)
        root.addWidget(self.tree, 1)
        self.rb_personal = QRadioButton("Copia personal: para usar en mis equipos")

        self.rb_share = QRadioButton("Para compartir o publicar el pack")
        self.rb_personal.setChecked(True)
        self.rb_personal.toggled.connect(self._sync)
        root.addWidget(self.rb_personal)
        root.addWidget(self.rb_share)
        self.chk = QCheckBox("")
        self.chk.toggled.connect(self._sync)
        root.addWidget(self.chk)
        self.note = QLabel("")
        self.note.setWordWrap(True)
        self.note.setStyleSheet("color:#9aa0aa;")
        root.addWidget(self.note)
        btns = QHBoxLayout()
        btns.addStretch(1)
        cancel = QPushButton("Cancelar")
        cancel.clicked.connect(self.reject)
        self.ok = QPushButton("Aceptar")
        self.ok.setStyleSheet("QPushButton{font-weight:bold;padding:8px 18px;}")

        self.ok.clicked.connect(self.accept)
        btns.addWidget(cancel)
        btns.addWidget(self.ok)
        root.addLayout(btns)
        self._sync()

    def _checked(self):
        out = []
        for i, r in enumerate(self.rows):
            it = self.tree.topLevelItem(i)
            if r['enabled'] and it.checkState(0) == Qt.Checked:
                out.append(r)
        return out

    def _sync(self, *_a):
        sel = self._checked()
        share = self.rb_share.isChecked()
        self.chk.setText("Confirmo que tengo derecho a redistribuir estas fuentes" if share else
                         "Confirmo que solo voy a exportar estas fuentes para uso personal")
        self.chk.setEnabled(bool(sel))
        self.rb_personal.setEnabled(bool(sel))
        self.rb_share.setEnabled(bool(sel))
        self.ok.setEnabled(not sel or self.chk.isChecked())
        self.note.setText(("\u2139 Se incluir\u00e1n %d fuente(s). El pack anota que son %s." % (len(sel), "para compartir" if share else "de uso personal"))
                          if sel else "\u2139 No se incluir\u00e1 ninguna fuente.")

    def paths(self):
        out = []
        for r in self._checked():
            for x in (r.get('paths') or ([r['path']] if r['path'] else [])):
                if x not in out:
                    out.append(x)
        return out

    def scope(self):
        return 'share' if self.rb_share.isChecked() else 'personal'


class UpdateDialog(QDialog):
    """[PACK114] Actualizaciones: version instalada y publicada, novedades, instalar, volver a la anterior y aviso al abrir el programa."""

    def __init__(self, manager):
        super().__init__(None)
        from PySide6.QtWidgets import QTextBrowser
        self.m = manager
        self.res = None
        self.busy = False
        self.setWindowTitle("Actualizaciones")
        self.setAttribute(Qt.WA_QuitOnClose, False)
        self.resize(640, 520)
        self.w = _UpdateWorker(self)
        self.w.checked.connect(self._on_checked)
        self.w.applied.connect(self._on_applied)
        root = QVBoxLayout(self)
        t1 = QLabel("Actualizaciones")
        t1.setStyleSheet("font-size:18px;font-weight:bold;")
        root.addWidget(t1)
        self.lb_local = QLabel("")
        self.lb_remote = QLabel("")

        root.addWidget(self.lb_local)
        root.addWidget(self.lb_remote)
        self.status = QLabel("")
        self.status.setWordWrap(True)
        self.status.setStyleSheet("background:#2b2b2f;border-radius:6px;padding:8px;")
        root.addWidget(self.status)
        root.addWidget(QLabel("Novedades"))
        self.notes = QTextBrowser()
        self.notes.setOpenExternalLinks(True)
        root.addWidget(self.notes, 1)
        self.chk_auto = QCheckBox("Avisarme al abrir el programa si hay una versi\u00f3n nueva")
        self.chk_auto.setChecked(update_state().get('auto', True) is not False)
        self.chk_auto.toggled.connect(self._auto_toggled)
        root.addWidget(self.chk_auto)
        row = QHBoxLayout()
        self.b_check = QPushButton("Buscar de nuevo")
        self.b_check.clicked.connect(self.start_check)
        self.b_back = QPushButton("Volver a la versi\u00f3n anterior")

        self.b_back.clicked.connect(self._rollback)
        self.b_go = QPushButton("Actualizar y reiniciar")
        self.b_go.setStyleSheet("QPushButton{font-weight:bold;padding:8px 18px;}")
        self.b_go.clicked.connect(self._apply)
        close = QPushButton("Cerrar")
        close.clicked.connect(self.close)
        row.addWidget(self.b_check)
        row.addWidget(self.b_back)
        row.addStretch(1)
        row.addWidget(close)
        row.addWidget(self.b_go)
        root.addLayout(row)
        self._fill_local()
        self._buttons()

    def _fill_local(self):
        loc = update_local_info()
        self.lb_local.setText("Tu versi\u00f3n:  pack %d%s  \u00b7  huella %s" % (loc['pack'], ("  \u00b7  " + loc['label']) if loc['label'] else "", loc['sha256'][:8] or "?"))
        self.lb_remote.setText("Publicada:  \u2014")

    def _buttons(self):
        r = self.res or {}
        frozen = bool(getattr(sys, 'frozen', False))
        can = bool(r.get('ok')) and r.get('state') in ('newer', 'diverged') and not frozen and not self.busy
        self.b_go.setEnabled(can)
        self.b_go.setText("Sustituir por la publicada" if r.get('state') == 'diverged' else "Actualizar y reiniciar")
        self.b_back.setEnabled(update_backup_available() and not frozen and not self.busy)
        self.b_check.setEnabled(not self.busy)

    def start_check(self):
        self.busy = True
        self.status.setText("Buscando la versi\u00f3n publicada...")
        self._buttons()
        self.w.check()

    def _auto_toggled(self, on):
        update_state()['auto'] = bool(on)
        update_state_save()

    def _on_checked(self, r):
        self.busy = False
        self.res = r
        self._fill_local()
        if not r.get('ok'):
            self.status.setText("No se pudo comprobar: %s\nRevisa tu conexi\u00f3n e int\u00e9ntalo de nuevo." % r.get('error', ''))
            self._buttons()
            return
        info, st = r['info'], r['state']
        self.lb_remote.setText("Publicada:  pack %s%s" % (info.get('pack'), ("  \u00b7  " + str(info.get('version'))) if info.get('version') else ""))
        try:
            self.notes.setMarkdown(str(info.get('notes') or "(sin novedades indicadas)"))
        except Exception:
            self.notes.setPlainText(str(info.get('notes') or ""))
        if getattr(sys, 'frozen', False) and st in ('newer', 'diverged'):
            self.status.setText("Hay una versi\u00f3n m\u00e1s nueva, pero esta instalaci\u00f3n es un ejecutable: descarga el instalador nuevo desde la p\u00e1gina del programa.")
        else:
            self.status.setText({
                'newer': "Hay una versi\u00f3n nueva (pack %s). Se guardar\u00e1 una copia de la actual y el programa se reiniciar\u00e1; tus notas y ajustes no se tocan." % info.get('pack'),
                'same': "Ya tienes la \u00faltima versi\u00f3n.",
                'older': "Tu copia (pack %d) es m\u00e1s nueva que la publicada (pack %s): no hay nada que actualizar." % (r['local']['pack'], info.get('pack')),
                'diverged': "Tienes el mismo pack que la web, pero tu archivo es distinto (cambios tuyos sin publicar). Puedes sustituirlo por el publicado: se guarda una copia.",
            }[st])

        self._buttons()

    def apply_result(self, r):
        """Desde el aviso del arranque: ya se sabe que hay una version nueva y el usuario dijo que si."""
        self._on_checked(r)
        self._apply(confirm=False)

    def _apply(self, confirm=True):
        r = self.res or {}
        if not r.get('ok') or r.get('state') not in ('newer', 'diverged'):
            return
        if confirm:
            warn = "\n\nTu archivo tiene cambios que no est\u00e1n publicados; se guardar\u00e1 una copia por si quieres volver." if r['state'] == 'diverged' else ""
            if QMessageBox.question(self, "Actualizar", "Se descargar\u00e1 la versi\u00f3n publicada (pack %s), se guardar\u00e1 una copia de la actual y el programa se reiniciar\u00e1.%s\n\n\u00bfContinuar?" % (r['info'].get('pack'), warn)) != QMessageBox.Yes:
                return
        self.busy = True
        self.status.setText("Descargando e instalando...")
        self._buttons()
        self.w.apply(r['info'])

    def _rollback(self):
        if QMessageBox.question(self, "Volver a la versi\u00f3n anterior", "Se restaurar\u00e1 la copia guardada en la \u00faltima actualizaci\u00f3n y el programa se reiniciar\u00e1. La versi\u00f3n actual queda guardada.\n\n\u00bfContinuar?") != QMessageBox.Yes:
            return
        self.busy = True
        self.status.setText("Restaurando...")
        self._buttons()
        self.w.apply(None, True)

    def _on_applied(self, r):
        self.busy = False
        if not r.get('ok'):
            self.status.setText("No se pudo completar: %s\nNo se ha cambiado nada." % r.get('error', ''))
            self._buttons()
            QMessageBox.warning(self, "Actualizar", "No se pudo completar:\n%s\n\nNo se ha cambiado nada." % r.get('error', ''))
            return
        self.status.setText("Listo. El programa se reinicia en unos segundos...")
        self._buttons()
        self.b_go.setEnabled(False)
        QTimer.singleShot(900, self.m.update_restart_app)


class PackExportDialog(QDialog):
    """[PACK112] Exportar como pack: elige que estilos, perfiles y widgets van dentro, y quien lo hace; las imagenes se meten solas."""
    LICENSES = ("Uso personal; no redistribuir", "CC BY 4.0 (con atribuci\u00f3n)", "CC BY-NC 4.0 (con atribuci\u00f3n, no comercial)",
                "CC0 (dominio p\u00fablico)", "MIT")

    def __init__(self, manager):
        super().__init__(None)
        from PySide6.QtWidgets import QListWidget, QListWidgetItem, QComboBox, QTextEdit, QLineEdit
        self.m = manager
        self.fonts = []
        self.setWindowTitle("Exportar como pack de widgets")
        self.setAttribute(Qt.WA_QuitOnClose, False)
        self.resize(760, 700)
        root = QVBoxLayout(self)
        intro = QLabel("Crea un archivo .wapack con lo que elijas. Las im\u00e1genes que usan tus widgets guardados y sets se incluyen solas; "
                       "la imagen de las formas de papel no hace falta (se vuelve a dibujar y se pueden seguir editando).")
        intro.setWordWrap(True)
        intro.setStyleSheet("color:#9aa0aa;")
        root.addWidget(intro)
        form = QFormLayout()
        self.f_name = QLineEdit("Mis widgets guardados")
        self.f_author = QLineEdit(os.environ.get('USERNAME') or os.environ.get('USER') or "")
        self.f_ver = QLineEdit("1.0.0")

        self.f_lic = QComboBox()
        self.f_lic.setEditable(True)
        self.f_lic.addItems(self.LICENSES)
        self.f_desc = QTextEdit()
        self.f_desc.setFixedHeight(64)
        self.f_desc.setPlaceholderText("Qu\u00e9 contiene y para qu\u00e9 sirve (opcional)")
        for lab, w in (("Nombre del pack", self.f_name), ("Autor", self.f_author), ("Versi\u00f3n", self.f_ver), ("Licencia", self.f_lic),
                       ("Descripci\u00f3n", self.f_desc)):
            form.addRow(lab, w)
        root.addLayout(form)
        root.addWidget(QLabel("Widgets guardados"))
        self.l_styles = QListWidget()
        root.addWidget(self.l_styles, 2)
        dflt = os.path.basename(DEFAULT_TEMPLATE_FILE)
        for n in self.m.template_files():
            if n == dflt:
                continue
            try:
                d = self.m.load_template_by_name(n)
            except Exception:
                continue
            it = QListWidgetItem(n[:-5] + ("   (forma de papel editable)" if isinstance(d.get('base_note'), dict) else ""))
            it.setFlags(it.flags() | Qt.ItemIsUserCheckable)
            it.setCheckState(Qt.Checked)
            it.setData(Qt.UserRole, n)
            self.l_styles.addItem(it)

        root.addWidget(QLabel("Sets de widgets (con sus enlaces)"))
        self.l_sets = QListWidget()
        root.addWidget(self.l_sets, 2)
        cur = self.m.current_profile_name
        it = QListWidgetItem("Los widgets que tengo ahora en pantalla" + (" (set \u00ab%s\u00bb)" % cur if cur else ""))
        it.setFlags(it.flags() | Qt.ItemIsUserCheckable)
        it.setCheckState(Qt.Checked)
        it.setData(Qt.UserRole, ('now', cur or "Mis widgets"))
        self.l_sets.addItem(it)
        for p in self.m._list_profiles():
            nm = os.path.splitext(os.path.basename(p))[0]
            if nm == cur:
                continue
            it = QListWidgetItem("Set \u00ab%s\u00bb" % nm)
            it.setFlags(it.flags() | Qt.ItemIsUserCheckable)
            it.setCheckState(Qt.Unchecked)
            it.setData(Qt.UserRole, ('profile', nm))
            self.l_sets.addItem(it)

        frow = QHBoxLayout()
        bf = QPushButton("Agregar otras fuentes (.ttf / .otf)...")
        bf.setToolTip("Las fuentes que usan tus widgets guardados se te preguntan al exportar; esto es para agregar alguna m\u00e1s. Solo si su licencia permite redistribuirlas.")
        bf.clicked.connect(self._add_fonts)
        self.l_fonts = QLabel("Al exportar se te preguntar\u00e1 por las fuentes que usan tus widgets guardados.")
        self.l_fonts.setStyleSheet("color:#9aa0aa;")
        frow.addWidget(bf)
        frow.addWidget(self.l_fonts, 1)
        root.addLayout(frow)
        btns = QHBoxLayout()
        for text, state in (("Marcar todo", Qt.Checked), ("Desmarcar todo", Qt.Unchecked)):
            b = QPushButton(text)
            b.clicked.connect(lambda _c=False, s=state: self._mark(s))
            btns.addWidget(b)
        btns.addStretch(1)
        ok = QPushButton("Exportar...")
        ok.setStyleSheet("QPushButton{font-weight:bold;padding:8px 18px;}")
        ok.clicked.connect(self._export)

        cancel = QPushButton("Cancelar")
        cancel.clicked.connect(self.reject)
        btns.addWidget(cancel)
        btns.addWidget(ok)
        root.addLayout(btns)

    def _mark(self, state):
        for lst in (self.l_styles, self.l_sets):
            for i in range(lst.count()):
                lst.item(i).setCheckState(state)

    def _add_fonts(self):
        paths, _ = QFileDialog.getOpenFileNames(self, "Fuentes para incluir", os.path.expanduser("~"), "Fuentes (*.ttf *.otf)")
        if paths:
            self.fonts = sorted(set(self.fonts) | set(paths))
            self.l_fonts.setText("%d fuentes: %s" % (len(self.fonts), ", ".join(os.path.basename(f) for f in self.fonts[:4]) + ("..." if len(self.fonts) > 4 else "")))

    def _export(self):
        styles, sets = [], []
        for i in range(self.l_styles.count()):
            it = self.l_styles.item(i)
            if it.checkState() == Qt.Checked:
                n = it.data(Qt.UserRole)
                styles.append((n[:-5], self.m.load_template_by_name(n)))
        for i in range(self.l_sets.count()):
            it = self.l_sets.item(i)
            if it.checkState() != Qt.Checked:
                continue
            kind, nm = it.data(Qt.UserRole)
            try:
                if kind == 'now':
                    self.m._sync_windows_to_state()
                    raw = self.m.global_state
                else:
                    raw = self.m._read_profile(nm)
            except Exception as e:
                QMessageBox.warning(self, "Exportar pack", "No se pudo leer \u00ab%s\u00bb:\n%s" % (nm, e))
                return
            notes = {k: v for k, v in raw.items() if isinstance(v, dict) and (isinstance(v.get('template_data'), dict) or str(k).startswith('hierarchy_settings'))}
            if any(isinstance(v.get('template_data'), dict) for v in notes.values()):
                sets.append((nm, notes))

        if not styles and not sets:
            QMessageBox.information(self, "Exportar pack", "Marca al menos un widget guardado o un set.")
            return
        used = set()
        for _n, _td in styles:
            used |= _pack_fonts_of(_td)
        for _n, _notes in sets:
            for _v in _notes.values():
                if isinstance(_v, dict) and isinstance(_v.get('template_data'), dict):
                    used |= _pack_fonts_of(_v['template_data'])
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            frows = font_export_rows(used)
        finally:
            QApplication.restoreOverrideCursor()
        for _fp in self.fonts:                                 # [PACK113] las que a\u00f1adiste a mano tambien pasan por la pregunta
            _mt = _font_meta(_fp) or {}
            _lic = font_license_label(_mt)
            frows.append({'family': _mt.get('family') or os.path.basename(_fp), 'path': _fp, 'enabled': True, 'checked': bool(_lic),
                          'status': "Agregada a mano" + ((" \u00b7 licencia libre (%s)" % _lic) if _lic else " \u00b7 licencia sin identificar"),
                          'where': "Windows, macOS y Linux (va dentro del pack)", 'license': _lic})
        font_files, fscope = [], 'personal'
        if frows:
            fdlg = FontExportDialog(self, frows)
            if fdlg.exec() != QDialog.Accepted:
                return
            font_files, fscope = fdlg.paths(), fdlg.scope()
        name = self.f_name.text().strip() or "Mis widgets guardados"
        path, _ = QFileDialog.getSaveFileName(self, "Guardar el pack", os.path.join(os.path.expanduser("~"), _pack_slug(name) + PACK_EXT),
                                              "Pack de widgets (*%s)" % PACK_EXT)
        if not path:
            return
        if not path.lower().endswith(PACK_EXT):
            path += PACK_EXT
        meta = {'name': name, 'author': self.f_author.text().strip(), 'version': self.f_ver.text().strip() or "1.0.0",
                'license': self.f_lic.currentText().strip(), 'description': self.f_desc.toPlainText().strip(), 'fonts_scope': fscope}
        try:
            r = pack_build(path, meta, styles, sets, font_files)
        except Exception as e:
            log_error("Packs", "No se pudo exportar el pack: %s" % e)
            QMessageBox.warning(self, "Exportar pack", "No se pudo crear el pack:\n%s" % e)
            return

        txt = "Pack guardado:\n%s\n\n%d widgets guardados, %d sets, %d im\u00e1genes (%.1f MB)." % (path, r['styles'], r['sets'], r['assets'], r['bytes'] / 1048576.0)
        if r['missing']:
            txt += "\n\nNo se encontraron estas im\u00e1genes y quedaron sin ellas: " + ", ".join(r['missing'][:8]) + ("..." if len(r['missing']) > 8 else "")
        free = [f for f in r['fonts_used'] if f not in r['font_families']]
        if free:
            txt += "\n\nUsan estas fuentes, que no van dentro: " + ", ".join(free[:6]) + ". Quien no las tenga ver\u00e1 otra letra."
        QMessageBox.information(self, "Exportar pack", txt)
        self.accept()


class DataHubWindow(QDialog):
    """[PACK72] Centro de guardar y cargar: un mapa de TODO lo que se guarda (sets, templates, configuracion, archivos,
    copias, deshacer): que es, donde vive y como guardarlo, cargarlo o recuperarlo. Acepta archivos arrastrados."""

    def __init__(self, manager):
        super().__init__(None)
        from PySide6.QtWidgets import QListWidget
        self.m = manager
        self.setWindowTitle("Guardar y cargar")
        self.setAttribute(Qt.WA_QuitOnClose, False)
        self.setAcceptDrops(True)
        self.resize(1060, 700)
        root = QVBoxLayout(self)
        head = QHBoxLayout()
        tl = QVBoxLayout()
        t1 = QLabel("Guardar y cargar")
        t1.setStyleSheet("font-size:18px;font-weight:bold;")
        t2 = QLabel("Todo lo que la aplicaci\u00f3n guarda, y d\u00f3nde vive cada cosa. Elige a la izquierda lo que buscas.\n"
                    "Tambi\u00e9n puedes arrastrar aqu\u00ed cualquier archivo (set, widget guardado, configuraci\u00f3n, pack .wapack o copia .zip) y se detecta solo.")
        t2.setWordWrap(True)
        t2.setStyleSheet("color:#9aa0aa;")
        tl.addWidget(t1)

        tl.addWidget(t2)
        head.addLayout(tl, 1)
        for text, fn, tip in (("Guardar todo ahora", self._save_all, "Guarda el set activo, la configuraci\u00f3n, el historial y hace una copia completa"),
                              ("Cargar un archivo...", lambda: self.m.load_anything_dialog(), "Elige un archivo: se detecta si es un set, un widget guardado, una configuraci\u00f3n o una copia")):
            b = QPushButton(text)
            b.setToolTip(tip)
            b.setStyleSheet("QPushButton{font-weight:bold;padding:8px 14px;}")
            b.clicked.connect(lambda _c=False, f=fn: (f(), self.refresh()))
            head.addWidget(b)
        root.addLayout(head)
        body = QHBoxLayout()
        root.addLayout(body, 1)
        self.nav = QListWidget()
        self.nav.setFixedWidth(270)
        self.nav.setSpacing(2)
        body.addWidget(self.nav)
        self.panel = QWidget()
        self.pl = QVBoxLayout(self.panel)

        body.addWidget(self.panel, 1)
        self.status = QLabel("")
        self.status.setStyleSheet("color:#9aa0aa;")
        root.addWidget(self.status)
        self._sections = [
            ("sets", "Mis sets", "Sets de widgets que alternas (Alt+1\u2026)", self._sec_sets),
            ("templates", "Widgets guardados y formas de papel", "Aspectos guardados y formas de papel editables", self._sec_templates),
            ("config", "Configuraci\u00f3n y atajos", "Ajustes, cables, tonos y teclas", self._sec_config),
            ("files", "Archivos (exportar / importar)", "Para llevar o compartir widgets", self._sec_files),
            ("packs", "Packs de widgets", "Widgets guardados y sets para compartir o estrenar", self._sec_packs),
            ("backups", "Copias de seguridad", "Se hacen solas; aqu\u00ed se recuperan", self._sec_backups),
            ("undo", "Deshacer (historial)", "Ctrl+Alt+Z / Ctrl+Alt+Y, tambi\u00e9n entre sesiones", self._sec_undo),
        ]
        from PySide6.QtWidgets import QListWidgetItem
        for key, title, sub, _f in self._sections:
            it = QListWidgetItem(title + "\n" + sub)
            it.setData(Qt.UserRole, key)
            it.setSizeHint(QSize(240, 48))
            self.nav.addItem(it)

        self.nav.currentRowChanged.connect(lambda _r: self.refresh())
        self.nav.setCurrentRow(0)

    # ---- utilidades
    @staticmethod
    def _count(d, suffix='.json', skip_underscore=True):
        try:
            return len([f for f in os.listdir(d) if f.lower().endswith(suffix) and not (skip_underscore and f.startswith('_'))])
        except OSError:
            return 0

    def select(self, key):
        for i, s in enumerate(self._sections):
            if s[0] == key:
                self.nav.setCurrentRow(i)

    def _save_all(self):
        self.status.setText(self.m.save_everything_now())

    def _clear(self):
        while self.pl.count():
            it = self.pl.takeAt(0)
            if it.widget() is not None:
                it.widget().deleteLater()

    def refresh(self):
        i = self.nav.currentRow()
        if not (0 <= i < len(self._sections)):
            return
        key, title, sub, fn = self._sections[i]
        desc, where, info, actions = fn()
        self._clear()
        t = QLabel(title)
        t.setStyleSheet("font-size:16px;font-weight:bold;")
        self.pl.addWidget(t)
        d = QLabel(desc)
        d.setWordWrap(True)
        self.pl.addWidget(d)
        if where:
            w = QLabel("D\u00f3nde est\u00e1:  " + where)
            w.setWordWrap(True)
            w.setTextInteractionFlags(Qt.TextSelectableByMouse)
            w.setStyleSheet("color:#8fb8ff;")
            self.pl.addWidget(w)

        if info:
            il = QLabel("\n".join(info))
            il.setWordWrap(True)
            il.setStyleSheet("background:#2b2b2f;border-radius:6px;padding:8px;")
            self.pl.addWidget(il)
        last_group = None
        for a in actions:
            label, target, tip = a[0], a[1], a[2]
            group = a[3] if len(a) > 3 else None
            detail = a[4] if len(a) > 4 else None                        # [PACK128] que hace, en que formato se guarda y donde acaba
            if group and group != last_group:
                gl = QLabel(group.upper())
                gl.setStyleSheet("color:#8fb8ff;font-weight:bold;margin-top:8px;")
                self.pl.addWidget(gl)
                last_group = group
            row = QWidget()
            hl = QHBoxLayout(row)
            hl.setContentsMargins(0, 0, 0, 0)
            b = QPushButton(label)
            b.setFixedWidth(300)
            b.setStyleSheet("QPushButton{text-align:left;padding:7px 10px;}")
            b.setToolTip(tip or "")
            hl.addWidget(b, 0, Qt.AlignTop)
            if detail:
                dl = QLabel(detail)
                dl.setWordWrap(True)
                dl.setStyleSheet("color:#9aa0aa;")
                hl.addWidget(dl, 1)
            else:
                hl.addStretch(1)
            if isinstance(target, list):
                mn = QMenu(b)
                for nm, cb in target:
                    act = mn.addAction(nm)
                    act.triggered.connect(lambda _c=False, f=cb: (f(), self.refresh()))
                if not target:
                    b.setEnabled(False)
                b.setMenu(mn)
            else:
                b.clicked.connect(lambda _c=False, f=target: (f(), self.refresh()))
            self.pl.addWidget(row)

        self.pl.addStretch(1)

    def _folder(self, path):
        return ("Abrir la carpeta", lambda: self.m.open_folder(path), path, "Carpeta", "Abre en el explorador de archivos la carpeta donde vive esto.")

    # ---- secciones: (descripcion, ubicacion, lineas de informacion, acciones)
    #      cada accion: (texto, funcion o lista de (nombre, funcion), ayuda, grupo, explicacion de que hace y en que formato queda) [PACK128]
    def _sec_sets(self):
        m = self.m
        names = [os.path.splitext(os.path.basename(p))[0] for p in m._list_profiles()]
        cur = m.current_profile_name
        info = ["Set activo: " + (("\u00ab%s\u00bb" % cur) if cur else "(sin guardar como set todav\u00eda)"),
                "%d sets guardados%s" % (len(names), (": " + ", ".join(names[:8]) + ("\u2026" if len(names) > 8 else "")) if names else "")]
        return ("Un set de widgets es una foto completa de lo que tienes en pantalla (posiciones, enlaces, contenido). Puedes tener varios y cambiar de uno a otro al instante "
                "(Ctrl / Alt + 1\u2026 0). El set activo se guarda solo al cambiar o al salir.",
                PROFILES_DIR, info,
                [("Guardar el set activo...", m._save_profile_dialog, "Si el nombre existe, lo actualiza", "Guardar",
                  "Guarda lo que ves ahora con un nombre, como un set en la carpeta de sets (un archivo .json por set, solo en este equipo; las im\u00e1genes se quedan en la carpeta de datos). "
                  "Si el nombre ya existe, lo actualiza."),
                 ("Duplicar el set activo como set nuevo...", lambda: m.clone_current_set(), "Nunca sobrescribe otro set", "Guardar",
                  "Crea otro set con una copia de lo que ves ahora y, si quieres, le asigna una tecla Alt + N. Nunca sobrescribe otro set."),
                 ("Cargar un set  \u25be", [(n, (lambda n=n: m._load_profile_dialog(n))) for n in names], "El set activo se aparta y se guarda", "Cargar",
                  "Cambia a otro set guardado. El set que tienes ahora se aparta en memoria y se guarda."),
                 ("Exportar los widgets del set activo...", m.export_state, "Archivo .waset con las im\u00e1genes dentro", "Llevar a otro equipo",
                  "Crea un archivo .waset (comprimido) con los widgets que ves ahora y sus im\u00e1genes dentro, para abrirlo en otro equipo o compartirlo. No es un set guardado: "
                  "en el otro equipo se carga con \u00abCargar un archivo\u00bb."),
                 ("Recuperar sets de una copia de seguridad...", lambda: m.show_backup_restore(), "Los sets eliminados vuelven sin pisar los existentes", "Recuperar",
                  "Abre una copia (completa .zip o autom\u00e1tica) y trae sets borrados o versiones anteriores, sin pisar los que ya existen."),
                 self._folder(PROFILES_DIR)])

    def _sec_templates(self):
        m = self.m
        n_all = self._count(TEMPLATES_DIR)
        n_base = len(m.base_note_templates())
        return ("Un widget guardado es el aspecto de un widget (capas, fondo, tama\u00f1o). Las formas de papel creadas con el editor se guardan tambi\u00e9n como widgets guardados "
                "editables, en su propia lista.",
                TEMPLATES_DIR, ["%d widgets guardados, %d de ellos son formas de papel editables" % (n_all, n_base)],
                [("Ver, elegir, crear y editar widgets guardados...", lambda: m.show_template_chooser(), "Primero salen los aspectos en uso y las formas de papel", "Ver y editar",
                  "Abre la lista de widgets guardados (primero los aspectos en uso y las formas de papel) para crear widgets nuevos a partir de ellos, editarlos o duplicarlos."),
                 ("Nueva nota && forma de papel...", lambda: m.show_base_note_dialog(), "Puedes guardar el resultado como forma de papel", "Ver y editar",
                  "Dibuja una nota con el editor de formas de papel; el resultado se puede guardar como forma de papel (un widget guardado editable)."),
                 ("Guardar un widget existente como widget guardado...", lambda: (m.show_template_chooser(), m.browser.templates._from_widget()), None, "Guardar",
                  "Guarda el aspecto de uno de los widgets que ves (capas, fondo, tama\u00f1o) como un archivo .json en la carpeta de widgets guardados."),
                 ("Importar un widget guardado desde un archivo...", lambda: (m.show_template_chooser(), m.browser.templates._import()), None, "Meter en la aplicaci\u00f3n",
                  "Copia un archivo .json de widget guardado a tu carpeta de widgets guardados (si trae im\u00e1genes dentro, las deja en la carpeta de datos sin pisar nada)."),
                 self._folder(TEMPLATES_DIR)])

    def _sec_config(self):
        m = self.m
        cd = os.path.join(ROOT_DATA_DIR, "config_backups")
        n = self._count(cd, skip_underscore=False)
        return ("La configuraci\u00f3n son los ajustes generales (cables, jerarqu\u00eda, tonos, men\u00fas\u2026) y los atajos de teclado. No incluye los widgets.",
                cd, ["%d copias de la configuraci\u00f3n guardadas (se hace una antes de cada cambio grande)" % n,
                     "Los esquemas de atajos viven en: " + HOTKEY_PROFILES_DIR],
                [("Guardar una copia de la configuraci\u00f3n ahora", lambda: m._osd("Configuraci\u00f3n guardada" if m._backup_config() else "No se pudo guardar"), None, "Guardar",
                  "Guarda los ajustes y los atajos (sin los widgets) como un archivo .json en la carpeta de copias de configuraci\u00f3n."),
                 ("Restaurar una configuraci\u00f3n previa...", m.restore_config_backup, None, "Recuperar",
                  "Elige una de esas copias y vuelve a ella; antes se guarda la configuraci\u00f3n actual."),
                 ("Abrir el editor de atajos de teclado", m.show_hotkeys, None, "Editar",
                  "Teclas, gestos del icono de la bandeja y esquemas de atajos (hotkeys.json y la carpeta de esquemas)."),
                 ("Guardar mi configuraci\u00f3n como la de las instalaciones nuevas...", m.save_install_defaults, "Crea defaults/config.json", "Instalaciones nuevas",
                  "Para quien reparte el programa: ajusta cables (grosor, peso, tama\u00f1o, curvatura...), jerarqu\u00eda, tonos y atajos a tu gusto, pulsa esto y deja el archivo "
                  "config.json en la carpeta defaults. Se aplica solo en el primer arranque de una instalaci\u00f3n nueva."),
                 self._folder(cd)])

    def _sec_files(self):
        m = self.m
        return ("Para llevar tus widgets a otro PC o compartirlos: se exportan a un archivo .waset (comprimido, con sus im\u00e1genes dentro) y se importan agreg\u00e1ndolos o reemplazando todo. "
                "Los widgets guardados van en .wawidget, las formas de papel en .wapaper, los marcos en .waframe y varios a la vez en un pack .wapack. Los .json de antes tambi\u00e9n se leen.",
                DATA_DIR, ["Archivo de trabajo actual: " + GLOBAL_STATE_FILE],
                [("Exportar todos los widgets a un archivo...", m.export_state, "Puede incluir la configuraci\u00f3n", "Sacar de la aplicaci\u00f3n",
                  "Crea un archivo .waset con los widgets del set activo y sus im\u00e1genes dentro; puede incluir tambi\u00e9n la configuraci\u00f3n."),
                 ("Agregar widgets desde un archivo...", lambda: m.import_state(replace=False), None, "Meter en la aplicaci\u00f3n",
                  "Suma los widgets del archivo a los que ya tienes en el set activo."),
                 ("Reemplazar todos los widgets desde un archivo...", lambda: m.import_state(replace=True), None, "Meter en la aplicaci\u00f3n",
                  "Elimina los widgets del set activo y pone los del archivo (se puede deshacer)."),
                 ("Cargar un archivo (se detecta solo)...", lambda: m.load_anything_dialog(), "Set, widget guardado, configuraci\u00f3n o copia .zip", "Meter en la aplicaci\u00f3n",
                  "Elige cualquier archivo (.json de widgets, widget guardado o configuraci\u00f3n; .zip de copia; .wapack) y el programa averigua qu\u00e9 es y c\u00f3mo cargarlo."),
                 ("Importar datos de otra instalaci\u00f3n (carpeta o .zip)...", m.show_import_data, "Widgets, sets, widgets guardados, im\u00e1genes y ajustes de una versi\u00f3n anterior", "Meter en la aplicaci\u00f3n",
                  "Trae widgets, sets, widgets guardados, im\u00e1genes y ajustes desde la carpeta widget_arena_data de otra versi\u00f3n o desde una copia completa .zip."),
                 ("Buscar las im\u00e1genes que faltan (en otra carpeta)...", m.recover_images_dialog, "Si al cargar una copia vieja alguna nota se queda sin su base o su imagen", "Meter en la aplicaci\u00f3n",
                  "Si tras cargar una copia vieja alguna nota se queda sin su imagen, las busca en la carpeta de datos de otra instalaci\u00f3n."),
                 self._folder(DATA_DIR)])

    def _sec_packs(self):
        m = self.m
        n = len(pack_list())
        return ("Un pack es un archivo .wapack (un .zip) con widgets guardados y sets de widgets, con las im\u00e1genes que usan, para compartir o para estrenar. "
                "Aqu\u00ed instalas uno, ves sus widgets guardados con vista previa y los agregas a los tuyos. Tambi\u00e9n puedes crear el tuyo con lo que ya tienes.",
                PACKS_DIR, [("%d pack instalado" if n == 1 else "%d packs instalados") % n, "Tambi\u00e9n puedes arrastrar un .wapack a esta ventana para instalarlo."],
                [("Abrir los packs de widgets...", lambda: m.show_packs(), "Cat\u00e1logo con vista previa", "Usar",
                  "Cat\u00e1logo de los packs instalados, con vista previa de sus widgets guardados y sets, para agregarlos a los tuyos."),
                 ("Instalar un pack desde un archivo...", m.pack_install_dialog, None, "Usar",
                  "A\u00f1ade un archivo .wapack al cat\u00e1logo. No toca tus widgets hasta que uses algo del pack."),
                 ("Exportar mis widgets y sets como pack...", m.pack_export_dialog, "Incluye las im\u00e1genes; la de las formas de papel no hace falta", "Crear",
                  "Crea un archivo .wapack (un .zip) con los widgets guardados y los sets que elijas, con sus im\u00e1genes (las formas de papel se redibujan solas)."),
                 self._folder(PACKS_DIR)])

    def _sec_backups(self):
        m = self.m
        bl = m.list_backups()
        full = [b for b in bl if b['kind'] == 'Completa']
        auto = [b for b in bl if b['kind'] != 'Completa']
        info = ["%d copias completas (todos los sets y widgets guardados)%s" % (len(full), ("; la \u00faltima: " + full[0]['label'].split('\u00b7')[1].strip()) if full else ""),
                "%d copias autom\u00e1ticas del set activo%s" % (len(auto), ("; la \u00faltima: " + auto[0]['label'].split('\u00b7')[1].strip()) if auto else "")]
        return ("Las copias se hacen solas mientras trabajas. Desde aqu\u00ed recuperas el set activo, sets eliminados o widgets guardados. "
                "Antes de restaurar el set activo se guarda una copia de lo actual y se puede deshacer.",
                FULL_BACKUP_DIR + "   (y " + BACKUP_DIR + ")", info,
                [("Restaurar una copia de seguridad...", lambda: m.show_backup_restore(), None, "Recuperar",
                  "Elige una copia (completa .zip o autom\u00e1tica del set activo) y qu\u00e9 traer de ella: el set activo, sets, widgets guardados e im\u00e1genes. No pisa nada sin avisar."),
                 ("Hacer una copia completa ahora", m._full_backup_now, None, "Guardar",
                  "Crea un .zip en la carpeta de copias completas con el set activo, todos los sets, los widgets guardados, los atajos y las im\u00e1genes que usan."),
                 self._folder(FULL_BACKUP_DIR)])

    def _sec_undo(self):
        m = self.m
        h = getattr(m, '_global_history', [])
        return ("Ctrl+Alt+Z deshace y Ctrl+Alt+Y rehace los cambios en los widgets (crear, eliminar, editar, mover\u2026). Ctrl+Z deshace primero los del widget enfocado. "
                "El historial de cada set se guarda en disco y sigue ah\u00ed al reiniciar.",
                m._undo_file(), ["Este set: %d pasos (est\u00e1s en el %d)" % (len(h), getattr(m, '_global_history_idx', 0) + 1)],
                [("Deshacer", m.undo_global, None, "Deshacer y rehacer", "Vuelve un paso atr\u00e1s en los cambios de este set (Ctrl+Alt+Z)."),
                 ("Rehacer", m.redo_global, None, "Deshacer y rehacer", "Repite el paso que acabas de deshacer (Ctrl+Alt+Y)."),
                 ("Olvidar el historial guardado de este set", m.clear_saved_history, "Libera espacio; los widgets no cambian", "Limpiar",
                  "Borra del disco el historial de este set (libera espacio); los widgets no cambian.")])

    # ---- arrastrar y soltar
    def dragEnterEvent(self, e):
        if e.mimeData().hasUrls():
            e.acceptProposedAction()

    def dropEvent(self, e):
        paths = [u.toLocalFile() for u in e.mimeData().urls() if u.isLocalFile()]
        e.acceptProposedAction()
        QTimer.singleShot(0, lambda: ([self.m.load_anything(p) for p in paths], self.refresh()))

HOTKEY_GROUPS = {
    "open_browser": "Aplicaci\u00f3n", "open_hotkeys": "Aplicaci\u00f3n", "toggle_console": "Aplicaci\u00f3n",
    "toggle_all": "Visibilidad y plegado", "show_all": "Visibilidad y plegado", "hide_all": "Visibilidad y plegado",
    "toggle_collapse_all": "Visibilidad y plegado", "collapse_all": "Visibilidad y plegado",
    "expand_all": "Visibilidad y plegado", "add_widget": "Crear y ordenar", "new_default": "Crear y ordenar",
    "cycle_sort": "Crear y ordenar", "reload_all": "Edici\u00f3n y recarga", "undo_global": "Edici\u00f3n y recarga",
    "redo_global": "Edici\u00f3n y recarga", "undo_widget": "Con un widget enfocado",
    "redo_widget": "Con un widget enfocado", "reload_widget": "Con un widget enfocado", "open_gestures": "Aplicaci\u00f3n",
    **{f"set_{_k}_{_n}": "Sets y ranuras" for _k in ("load", "save", "loadc") for _n in range(1, 11)},
    "profile_next": "Sets y ranuras", "profile_prev": "Sets y ranuras", "set_rotation": "Sets y ranuras", "clone_set": "Sets y ranuras",
}


class HotkeyEditor(QWidget):
    """Editor jerarquico de atajos: comandos por categorias, menu del tray, menu de cada widget y gestos
    del icono de bandeja. Con busqueda, aviso de conflictos y perfiles (templates) de atajos."""
    COLS = ("Funci\u00f3n", "Atajo", "Global", "Tecla de men\u00fa", "")

    def __init__(self, manager, say=None):
        super().__init__()
        from PySide6.QtWidgets import QTreeWidget
        self.m, self.say, self._building, self._rows = manager, say or (lambda s: None), False, {}
        self.timer = QTimer(self)
        self.timer.setSingleShot(True)
        self.timer.setInterval(400)
        self.timer.timeout.connect(self.commit)
        v = QVBoxLayout(self)
        self.info = QLabel("Cada funci\u00f3n puede tener un atajo. <b>Global</b>: funciona aunque otra aplicaci\u00f3n tenga el "
                           "foco; si no, solo con un widget enfocado. La <b>tecla de men\u00fa</b> es la letra que activa la "
                           "opci\u00f3n con el men\u00fa abierto. Se guarda solo en <b>hotkeys.json</b>.")
        self.info.setWordWrap(True)
        v.addWidget(self.info)
        prow = QHBoxLayout()
        prow.addWidget(QLabel("Esquema:"))
        self.profiles = QComboBox()
        self.profiles.setMinimumWidth(150)
        prow.addWidget(self.profiles)
        for text, fn in (("Cargar", self._p_load), ("Guardar como...", self._p_save), ("Eliminar", self._p_delete),
                         ("Importar...", self._p_import), ("Exportar...", self._p_export),
                         ("Restaurar valores por defecto", self._p_reset)):
            b = QPushButton(text)
            b.clicked.connect(lambda _c=False, f=fn: f())
            prow.addWidget(b)
        prow.addStretch(1)
        v.addLayout(prow)
        srow = QHBoxLayout()
        self.search = QLineEdit()
        self.search.setPlaceholderText("Buscar funci\u00f3n o atajo...")
        self.search.setClearButtonEnabled(True)
        srow.addWidget(self.search, 1)
        for text, fn in (("Expandir todo", lambda: self.tree.expandAll()), ("Contraer todo", lambda: self.tree.collapseAll())):
            b = QPushButton(text)
            b.clicked.connect(lambda _c=False, f=fn: f())
            srow.addWidget(b)
        v.addLayout(srow)
        self.tree = QTreeWidget()
        self.tree.setColumnCount(5)
        self.tree.setHeaderLabels(list(self.COLS))
        self.tree.setIndentation(18)
        hd = self.tree.header()
        hd.setStretchLastSection(False)
        for c, w in ((0, 330), (1, 200), (2, 55), (3, 100), (4, 34)):
            self.tree.setColumnWidth(c, w)
        v.addWidget(self.tree, 1)
        self.conf = QLabel("")
        v.addWidget(self.conf)
        self.search.textChanged.connect(self._filter)
        self.rebuild()
    # ---- construccion del arbol ------------------------------------------
    def _group(self, parent, text):
        from PySide6.QtWidgets import QTreeWidgetItem
        it = QTreeWidgetItem(parent if parent is not None else self.tree)
        it.setText(0, text)
        f = it.font(0)
        f.setBold(True)
        it.setFont(0, f)
        it.setExpanded(True)
        return it

    def _leaf(self, parent, label, cid, keys_ok, path=None, letter="", local_only=False, gesture=None):
        from PySide6.QtWidgets import QTreeWidgetItem, QKeySequenceEdit
        hk, t = self.m.hotkeys, self.tree
        it = QTreeWidgetItem(parent if parent is not None else t)
        it.setText(0, label)
        if gesture is not None:
            cb = QComboBox()
            cb.addItem("(nada)", "")
            for c in HOTKEY_COMMANDS:
                if not c[4]:
                    cb.addItem(c[1], c[0])
            cb.setCurrentIndex(max(cb.findData(hk.tray_command(gesture)), 0))
            cb.view().setMinimumWidth(380)
            cb.currentIndexChanged.connect(lambda _i, g=gesture, w=cb: self._on_gesture(g, w.currentData()))
            t.setItemWidget(it, 1, cb)
            return it
        if cid:
            it.setData(0, Qt.UserRole, cid)
        ke = cbg = le = None
        if keys_ok and cid:
            key, glob = hk.binding(cid)
            ke = QKeySequenceEdit(QKeySequence(key))
            ke.setMaximumSequenceLength(1)
            cbg = QCheckBox()
            needs = local_only                      # [PACK105] las teclas de widget tambien pueden ser globales
            cbg.setChecked(glob and not needs)
            cbg.setEnabled(not needs)
            cbg.setStyleSheet("margin-left:18px;")
            t.setItemWidget(it, 1, ke)
            t.setItemWidget(it, 2, cbg)
            ke.keySequenceChanged.connect(lambda *_a, c=cid: self._on_key(c))
            cbg.toggled.connect(lambda *_a, c=cid: self._on_key(c))
            clr = QToolButton()
            clr.setText("\u2715")
            clr.setToolTip("Quitar el atajo")
            clr.clicked.connect(lambda _c=False, k=ke: k.clear())
            t.setItemWidget(it, 4, clr)
            self._rows[cid] = (it, ke, cbg)
        if path is not None:
            le = QLineEdit(letter)
            le.setMaxLength(1)
            le.setAlignment(Qt.AlignCenter)
            le.editingFinished.connect(lambda p=path, e=le: self._on_letter(p, e.text()))
            t.setItemWidget(it, 3, le)
        return it

    def _menu_tree(self, root, menu, prefix, widget_menu):
        hk = self.m.hotkeys
        stack = [(-1, root)]
        for path, label, depth, leaf, letter in hk.menu_rows(menu, prefix):
            if path.startswith(("tray/Widgets", "tray/Nuevo desde un tipo")):
                continue
            while stack and stack[-1][0] >= depth:
                stack.pop()
            parent = stack[-1][1]
            if not leaf:
                it = self._leaf(parent, label, None, False, path=path, letter=letter)
                f = it.font(0)
                f.setBold(True)
                it.setFont(0, f)
                it.setExpanded(False)
                stack.append((depth, it))
            elif widget_menu:
                self._leaf(parent, label, "wmenu:" + path, True, path=path, letter=letter)
            else:
                cid = MENU_PATH_TO_CMD.get(path) or ("menu:" + path)
                self._leaf(parent, label, cid, path not in MENU_PATH_TO_CMD, path=path, letter=letter)

    def rebuild(self):
        m = self.m
        self._building = True
        self.tree.blockSignals(True)
        self.tree.clear()
        self._rows = {}
        g_cmd = self._group(None, "Comandos")
        cats = {}
        for cid, label, _k, _g, _n in HOTKEY_COMMANDS:
            cat = HOTKEY_GROUPS.get(cid, "General")
            if cat not in cats:
                cats[cat] = self._group(g_cmd, cat)
            self._leaf(cats[cat], label, cid, True)
        g_tray = self._group(None, "Men\u00fa del icono de bandeja (tray)")
        menu = m.tray_icon.contextMenu()
        if menu is not None:
            self._menu_tree(g_tray, menu, "tray", False)
        g_w = self._group(None, "Men\u00fa de cada widget (clic derecho): con tecla local act\u00faan sobre el widget enfocado; con tecla global, sobre el que est\u00e9 bajo el cursor o el \u00faltimo usado")
        wid = next((w for w, s in m.global_state.items() if isinstance(s, dict)), None)
        if wid:
            self._menu_tree(g_w, m.build_widget_context_menu(wid, full=True), "widget", True)
        else:
            self._leaf(g_w, "(crea un widget para ver su men\u00fa)", None, False)
        g_g = self._group(None, "Gestos del icono de bandeja (se leen Ctrl / Alt / May\u00fas al hacer clic)")
        for g, glabel in TRAY_GESTURES:
            self._leaf(g_g, glabel, None, False, gesture=g)
        it_rot = self._leaf(g_g, "Sets de la rotaci\u00f3n (gestos Ctrl / Alt + doble clic y Ctrl+May\u00fas+\u2191/\u2193)", None, False)      # [PACK122]
        self._rot_btn = QPushButton(self._rotation_text())
        self._rot_btn.setToolTip("Elige y ordena los sets por los que se rota")
        self._rot_btn.clicked.connect(self._edit_rotation)
        self.tree.setItemWidget(it_rot, 1, self._rot_btn)
        self.tree.blockSignals(False)
        self._building = False
        self._refresh_profiles()
        self._mark_conflicts()
        self._filter(self.search.text())

    def _rotation_text(self):
        rot = self.m._rotation_explicit()
        return ("%d sets elegidos..." % len(rot)) if rot else "Todos (alfab\u00e9tico)..."

    def _edit_rotation(self, _c=False):
        self.m.edit_set_rotation(self)
        try:
            self._rot_btn.setText(self._rotation_text())
        except RuntimeError:
            pass

    def _refresh_profiles(self, select=None):
        cur = select or self.profiles.currentText()
        self.profiles.blockSignals(True)
        self.profiles.clear()
        self.profiles.addItems(self.m.hotkeys.profile_names())
        i = self.profiles.findText(cur)
        if i >= 0:
            self.profiles.setCurrentIndex(i)
        self.profiles.blockSignals(False)

    def _filter(self, text):
        text = (text or "").strip().lower()

        def walk(it):
            n = it.childCount()
            own = (not text) or text in it.text(0).lower() or any(
                text in (self.m.hotkeys.binding(cid)[0] or "").lower()
                for cid in [it.data(0, Qt.UserRole)] if cid)
            any_child = False
            for i in range(n):
                any_child = walk(it.child(i)) or any_child
            show = own or any_child
            it.setHidden(not show)
            if text and any_child:
                it.setExpanded(True)
            return show
        for i in range(self.tree.topLevelItemCount()):
            walk(self.tree.topLevelItem(i))
    # ---- cambios ----------------------------------------------------------
    def _on_key(self, cid):
        if self._building or cid not in self._rows:
            return
        _it, ke, cbg = self._rows[cid]
        hk = self.m.hotkeys
        key = ke.keySequence().toString(QKeySequence.PortableText)
        if cid.startswith(("menu:", "wmenu:")) and not key:
            hk.cfg["hotkeys"].pop(cid, None)
        else:
            hk.set_binding(cid, key, cbg.isChecked())
        self._mark_conflicts()
        self.timer.start()

    def _on_letter(self, path, text):
        text = text.strip().lower()[:1]
        if text and text not in path.rsplit("/", 1)[1].lower():
            self.say(f"La tecla '{text}' debe aparecer en el texto de la opci\u00f3n.")
            self.rebuild()
            return
        self.m.hotkeys.set_menu_key(path, text)
        self.timer.start()

    def _on_gesture(self, gesture, cmd):
        if not self._building:
            self.m.hotkeys.set_tray_command(gesture, cmd or "")
            self.timer.start()

    def commit(self):
        hk = self.m.hotkeys
        hk.save()
        hk.apply()
        self.m.build_tray_menu()
        self._mark_conflicts()
        self.say("Atajos guardados.")

    def hideEvent(self, event):
        # Un cambio de atajo se confirma 400 ms despues; si se cierra antes, no se perdia.
        if self.timer.isActive():
            self.timer.stop()
            self.commit()
        super().hideEvent(event)

    def _mark_conflicts(self):
        bad = self.m.hotkeys.conflicts()
        for cid, (it, _ke, _cb) in self._rows.items():
            if cid in bad:
                it.setForeground(0, QBrush(QColor("#e05555")))
            else:
                it.setData(0, Qt.ForegroundRole, None)
        self.conf.setText(f"<span style='color:#e05555'>Conflicto: {len(bad)} funciones comparten atajo (en rojo).</span>"
                          if bad else "Sin conflictos.")

    # ---- perfiles ---------------------------------------------------------
    def _p_load(self):
        name = self.profiles.currentText()
        if not name:
            return
        try:
            self.m.hotkeys.load_profile(name)
        except Exception as e:
            self.say(f"No se pudo cargar el esquema: {e}")
            return
        self.m.build_tray_menu()
        self.rebuild()
        self.say(f"Esquema '{name}' cargado.")

    def _p_save(self):
        name, ok = QInputDialog.getText(self, "Guardar esquema de atajos", "Nombre del esquema:", text=self.profiles.currentText())
        if not ok:
            return
        n = self.m.hotkeys.safe_profile_name(name)
        if not n:
            self.say("Nombre no v\u00e1lido.")
            return
        if n in self.m.hotkeys.profile_names() and QMessageBox.question(
                self, "Sobrescribir", f"El esquema '{n}' ya existe. \u00bfSobrescribirlo?",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No) != QMessageBox.Yes:
            return
        self.m.hotkeys.save_profile(n)
        self._refresh_profiles(n)
        self.say(f"Esquema '{n}' guardado.")

    def _p_delete(self):
        name = self.profiles.currentText()
        if name and QMessageBox.question(self, "Eliminar esquema", f"\u00bfEliminar el esquema '{name}'?",
                                         QMessageBox.Yes | QMessageBox.No, QMessageBox.No) == QMessageBox.Yes:
            try:
                self.m.hotkeys.delete_profile(name)
            except OSError as e:
                self.say(f"No se pudo eliminar: {e}")
            self._refresh_profiles()

    def _p_import(self):
        path, _ = QFileDialog.getOpenFileName(self, "Importar esquema de atajos", DATA_DIR, "JSON (*.json)")
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError("no es un esquema de atajos")
            n = self.m.hotkeys.safe_profile_name(os.path.splitext(os.path.basename(path))[0]) or "importado"
            os.makedirs(HOTKEY_PROFILES_DIR, exist_ok=True)
            with open(os.path.join(HOTKEY_PROFILES_DIR, n + ".json"), "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
        except Exception as e:
            self.say(f"No se pudo importar: {e}")
            return
        self._refresh_profiles(n)
        self.say(f"Esquema '{n}' importado (usa Cargar para aplicarlo).")

    def _p_export(self):
        path, _ = QFileDialog.getSaveFileName(self, "Exportar atajos actuales", os.path.join(DATA_DIR, "mis_atajos.json"), "JSON (*.json)")
        if path:
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump(self.m.hotkeys.cfg_snapshot(), f, indent=2, ensure_ascii=False)
            except OSError as e:
                self.say(f"No se pudo exportar: {e}")

    def _p_reset(self):
        if QMessageBox.question(self, "Restaurar", "\u00bfRestaurar todos los atajos, teclas de men\u00fa y gestos a sus valores por defecto?",
                                QMessageBox.Yes | QMessageBox.No, QMessageBox.No) != QMessageBox.Yes:
            return
        self.m.hotkeys.reset_defaults()
        self.m.build_tray_menu()
        self.rebuild()
        self.say("Valores por defecto restaurados.")

# --- Clase del Gestor Principal de Widgets ---

def _paint_cable_sample(p, m, vlen, p0, p1, col_a, col_b, fx=None, rpath=None):
    """Cable de muestra (miniaturas del dialogo de cables) con los ajustes ACTUALES: misma logica que
    ConnectorOverlay.draw_edge pero para una longitud virtual 'vlen'. Si cambia draw_edge, cambiar aqui tambien."""
    from PySide6.QtCore import QPointF
    path = QPainterPath()
    path.moveTo(p0)
    path = rpath if rpath is not None else _cable_path(p0, p1, m.cable_curve(vlen), fx)
    op_mul, w_main = m.cable_length_style(vlen)
    w_end, w_ctr = m.cable_width_profile(vlen)
    ca = _cable_color(col_a, CABLE_STYLE['alpha'] * op_mul)
    cb = _cable_color(col_b, CABLE_STYLE['alpha'] * op_mul)
    blend = _cable_blend if CABLE_STYLE['blend_hsv'] else _cable_blend_rgb
    lo = max(0.0, min(0.499, m.get_cable_param('_cable_grad_start') / 100.0))
    hi = 1.0 - lo
    if hi - lo < 1e-4:
        lo, hi = max(0.0, lo - 5e-5), min(1.0, lo + 5e-5)
    om = m.cable_opacity_profile(vlen)
    os_ = max(0.0, min(0.499, m.get_cable_param('_cable_ograd_start') / 100.0))

    def stop(s):
        c = ca if s <= lo else (cb if s >= hi else blend(ca, cb, (s - lo) / (hi - lo)))
        d = min(s, 1.0 - s)
        if om < 0.999 and os_ < 0.495 and d > os_:
            u = (d - os_) / (0.5 - os_)
            c = QColor(c)
            c.setAlpha(int(round(c.alpha() * (1.0 + (om - 1.0) * (u * u * (3.0 - 2.0 * u))))))
        return c
    grad = QLinearGradient(QPointF(p0), QPointF(p1))
    for s in sorted({0.0, 1.0, lo, hi} | {i / 12.0 for i in range(13)}):
        grad.setColorAt(s, stop(s))
    brush = QBrush(grad)
    gl = m.get_cable_param('_cable_glow')
    if gl > 0:
        base = p.opacity()
        gs = m.get_cable_param('_cable_glow_size')
        p.setOpacity(base * min(1.0, gl / 100.0 * 0.2))
        for gi in (3.0, 1.5):
            if abs(w_end - w_ctr) >= 0.08:            # [PACK89] el resplandor sigue el afinado del cable
                _cable_draw_tapered(p, path, brush, max(0.3, w_end) + gs * 2.0 * gi / 3.0, max(0.3, w_ctr) + gs * 2.0 * gi / 3.0,
                                    m.get_cable_param('_cable_wgrad_start') / 100.0, False)
                continue
            pen = QPen(brush, max(0.3, w_end) + gs * 2.0 * gi / 3.0, Qt.SolidLine)
            pen.setCapStyle(Qt.RoundCap)
            p.setPen(pen)
            p.setBrush(Qt.NoBrush)
            p.drawPath(path)
        p.setOpacity(base)
    if abs(w_end - w_ctr) >= 0.08:
        _cable_draw_tapered(p, path, brush, max(0.3, w_end), max(0.3, w_ctr),
                            m.get_cable_param('_cable_wgrad_start') / 100.0, False)
    else:
        pen = QPen(brush, max(0.3, w_main), Qt.SolidLine)
        pen.setCapStyle(Qt.RoundCap)
        p.setPen(pen)
        p.setBrush(Qt.NoBrush)
        p.drawPath(path)


class CableSampleView(QWidget):
    """Miniatura en vivo (a la derecha de cada ajuste) de lo que cambia ese ajuste de los cables.
    kind: 'hover', 'short'/'long' (corto arriba, largo abajo; se marca el que cambia), 'grad', 'glow'
    o una curva 'op_near'/'op_far'/'w_near'/'w_far' (opacidad o grosor segun la longitud)."""
    COL_A, COL_B = '#ffb347', '#4dd0e1'

    def __init__(self, manager, kind, parent=None):
        super().__init__(parent)
        self.m = manager
        self.kind = kind
        self.setFixedSize(220, 84 if kind in ('fx', 'rope') else 56)         # [PACK99] la miniatura de los efectos es mas alta
        self._ropes = {}                                           # [PACK100] la miniatura de la cuerda esta viva
        self._rope_timer = None
        if kind == 'rope':
            self._rope_timer = QTimer(self)
            self._rope_timer.setInterval(33)
            self._rope_timer.timeout.connect(self.update)

    def showEvent(self, e):
        if self._rope_timer is not None:
            self._rope_timer.start()
        super().showEvent(e)

    def hideEvent(self, e):
        if self._rope_timer is not None:
            self._rope_timer.stop()
        super().hideEvent(e)

    def paintEvent(self, _e):
        from PySide6.QtCore import QPointF
        m, k, w, h = self.m, self.kind, self.width(), self.height()
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        p.setBrush(QColor('#11141c'))
        p.setPen(QColor('#2a3042'))
        p.drawRoundedRect(0, 0, w - 1, h - 1, 5, 5)
        if k in ('op_near', 'op_far', 'w_near', 'w_far', 'c_near', 'c_far'):
            self._plot(p, w, h)
            p.end()
            return
        if k == 'fx':
            self._fx_sample(p, w, h)
            p.end()
            return
        if k == 'rope':
            self._rope_sample(p, w, h)
            p.end()
            return
        far = max(m.get_cable_param('_cable_op_far'), m.get_cable_param('_cable_w_far')) * 1.5
        hf = m.get_cable_hover_opacity() if getattr(m, '_cable_sample_hover', True) else 1.0   # contexto de la muestra
        if k in ('short', 'long'):
            for vlen, name, cy in ((0.0, 'short', 16), (far, 'long', h - 16)):
                p.setOpacity((1.0 if name == k else 0.35) * hf)
                self._cable(p, vlen, QPointF(18, cy + 5), QPointF(w - 18, cy - 5))
                if name == k:
                    p.fillRect(3, cy - 7, 3, 14, QColor('#ffb347'))
            p.setOpacity(1.0)
        else:
            if k == 'hover':
                p.setOpacity(m.get_cable_hover_opacity())
            if k != 'hover':
                p.setOpacity(hf)
            _a, _b = (0.86, 0.14) if k == 'curve' else (0.68, 0.32)
            if k == 'crown':
                self._crown_sample(p)
            elif k == 'dash':
                self._dash_sample(p, QPointF(18, h * _a), QPointF(w - 18, h * _b))
            else:
                self._cable(p, 0.0, QPointF(18, h * _a), QPointF(w - 18, h * _b))
            p.setOpacity(1.0)
            if k == 'glow' and m.get_cable_param('_cable_glow') <= 0:
                p.setPen(QColor('#8b93a8'))
                p.drawText(self.rect(), Qt.AlignHCenter | Qt.AlignBottom, "sin resplandor")
        p.end()

    def _cable(self, p, vlen, a, b, fx=None, rpath=None):
        _paint_cable_sample(p, self.m, vlen, a, b, self.COL_A, self.COL_B, fx, rpath)
        for pt, col in ((a, self.COL_A), (b, self.COL_B)):
            p.setPen(Qt.NoPen)
            p.setBrush(QColor(col))
            p.drawEllipse(pt, 3.5, 3.5)


    def _rope_sample(self, p, w, h):
        """[PACK100] Un cable cercano (izquierda) y uno lejano (derecha), cada uno a escala de su distancia real, con su fisica."""
        from PySide6.QtCore import QPointF
        m = self.m
        near = max(m.get_cable_param('_rope_near'), 60.0)
        far = max(m.get_cable_param('_rope_far'), near + 50.0)
        hf = m.get_cable_hover_opacity() if getattr(m, '_cable_sample_hover', True) else 1.0
        p.setOpacity(hf)
        chord = 92.0
        f = p.font()
        f.setPixelSize(9)
        p.setFont(f)
        now = time.monotonic()
        for idx, (x0, vlen, name) in enumerate(((10.0, near, "cercano"), (118.0, far, "lejano"))):
            sc = chord / vlen
            a, b = QPointF(x0, 14.0), QPointF(x0 + chord, 14.0)
            P = m.cable_rope_params(vlen)
            rp = None
            if P is not None:
                rope = self._ropes.get(idx)
                if rope is None:
                    rope = self._ropes[idx] = _CableRope(idx + 11)
                rope.step(now, a.x(), a.y(), b.x(), b.y(), (P[0] * sc, P[1], P[2], P[3], P[4], sc, 14, P[7], P[8]))
                rp = rope.path()
            self._cable(p, vlen, a, b, None, rp)
            p.setOpacity(1.0)
            p.setPen(QColor('#8b93a8'))
            p.drawText(QRect(int(x0), h - 12, int(chord), 11), Qt.AlignHCenter, "%s (%d px)" % (name, int(vlen)))
            p.setOpacity(hf)
        p.setOpacity(1.0)
        if m.cable_rope_params(0.0) is None:
            p.setPen(QColor('#8b93a8'))
            p.drawText(QRect(0, 34, w, 20), Qt.AlignHCenter, "cuerda apagada (cantidad 0 %)")

    def _fx_sample(self, p, w, h):
        """[PACK99] Un cable cercano (izquierda) y uno lejano (derecha), cada uno a escala de su distancia real."""
        from PySide6.QtCore import QPointF
        m = self.m
        near = max(m.get_cable_param('_cable_fx_near'), 60.0)
        far = max(m.get_cable_param('_cable_fx_far'), near + 50.0)
        hf = m.get_cable_hover_opacity() if getattr(m, '_cable_sample_hover', True) else 1.0
        p.setOpacity(hf)
        chord = 92.0
        f = p.font()
        f.setPixelSize(9)
        p.setFont(f)
        for x0, vlen, name in ((10.0, near, "cercano"), (118.0, far, "lejano")):
            fx = m.cable_fx(vlen, chord / vlen)
            a, b = QPointF(x0, 26.0), QPointF(x0 + chord, 18.0)
            self._cable(p, vlen, a, b, fx)
            p.setOpacity(1.0)
            p.setPen(QColor('#8b93a8'))
            p.drawText(QRect(int(x0), h - 12, int(chord), 11), Qt.AlignHCenter, "%s (%d px)" % (name, int(vlen)))
            p.setOpacity(hf)
        p.setOpacity(1.0)
        if m.cable_fx(0.0) is None:
            p.setPen(QColor('#8b93a8'))
            p.drawText(QRect(0, 34, w, 20), Qt.AlignHCenter, "efectos apagados (cantidad 0 %)")

    def _crown_sample(self, p):
        from PySide6.QtCore import QPointF
        m, w, h = self.m, self.width(), self.height()
        hf = m.get_cable_hover_opacity() if getattr(m, '_cable_sample_hover', True) else 1.0
        mode = int(m.get_cable_param('_crown_opacity_mode'))
        p.setOpacity(1.0)
        p.setPen(QPen(QColor('#394056'), 1.5))
        p.drawLine(QPointF(12, h - 10), QPointF(w - 12, h - 10))      # borde superior del papel (muestra)
        p.setOpacity(hf if mode == 0 else (m.get_cable_hover_opacity() if mode == 1
                                           else (1.0 if mode == 2 else m.get_cable_param('_crown_opacity') / 100.0)))
        _crown_paint(p, m, _cable_color(self.COL_A, CABLE_STYLE['alpha'] * m.cable_length_style(0.0)[0]), w / 2.0, h - 10, 0.0)
        p.setOpacity(1.0)

    def _dash_sample(self, p, a, b):
        from PySide6.QtCore import QPointF
        m = self.m
        path = _cable_path(a, b, m.cable_curve(0.0))
        grad = QLinearGradient(QPointF(a), QPointF(b))
        grad.setColorAt(0.0, _cable_color(self.COL_A, CABLE_STYLE['alpha']))
        grad.setColorAt(1.0, _cable_color(self.COL_B, CABLE_STYLE['alpha']))
        wd = max(0.3, m.get_cable_param('_cable_width_max') * CABLE_STYLE['dim_width'] / CABLE_STYLE['width'])
        p.setPen(_cable_dotted_pen(QBrush(grad), wd, m.get_cable_param('_cable_dash_len'), m.get_cable_param('_cable_dash_gap')))
        p.setBrush(Qt.NoBrush)
        p.drawPath(path)
        for pt, col in ((a, self.COL_A), (b, self.COL_B)):
            p.setPen(Qt.NoPen)
            p.setBrush(QColor(col))
            p.drawEllipse(pt, 3.5, 3.5)

    def _plot(self, p, w, h):
        from PySide6.QtCore import QPointF
        from PySide6.QtGui import QPolygonF
        m, op = self.m, self.kind.startswith('op')
        pre = self.kind.split('_')[0]               # 'op' opacidad, 'w' grosor, 'c' curvatura
        near = m.get_cable_param('_cable_%s_near' % pre)
        far = max(m.get_cable_param('_cable_%s_far' % pre), near + 50.0)
        xmax = max(far * 1.3, 600.0)
        L, R, T, B = 8, w - 8, 7, h - 13
        top = 1.0 if op else (max(1.0, m.get_cable_param('_cable_cfar_pct') / 100.0) if pre == 'c' else m.get_cable_param('_cable_width_max') * 1.1)
        pts = [QPointF(L + (R - L) * i / 48.0,
                       B - (B - T) * min(1.0, (m.cable_curve_factor(xmax * i / 48.0) if pre == 'c'
                                               else m.cable_length_style(xmax * i / 48.0)[0 if op else 1]) / top))
               for i in range(49)]
        active = near if self.kind.endswith('near') else far
        for val in (near, far):
            x = L + (R - L) * val / xmax
            p.setPen(QPen(QColor('#ffb347') if val == active else QColor('#394056'), 1.5 if val == active else 1, Qt.DashLine))
            p.drawLine(QPointF(x, T), QPointF(x, B))
        p.setPen(QPen(QColor('#4dd0e1'), 2))
        p.setBrush(Qt.NoBrush)
        p.drawPolyline(QPolygonF(pts))
        p.setPen(QColor('#8b93a8'))
        f = p.font()
        f.setPixelSize(9)
        p.setFont(f)
        p.drawText(QRect(L, B + 1, R - L, 11), Qt.AlignLeft, "0")
        p.drawText(QRect(L, B + 1, R - L, 11), Qt.AlignRight, f"{int(xmax)} px")
        p.drawText(QRect(L, B + 1, R - L, 11), Qt.AlignHCenter, f"{int(active)} px")


class _CableCombo(QComboBox):
    """Desplegable con la interfaz minima de un spinbox (setValue / value / valueChanged) para el dialogo de cables."""
    valueChanged = Signal(int)

    def __init__(self, items, parent=None):
        super().__init__(parent)
        self.addItems(list(items))
        self.currentIndexChanged.connect(self.valueChanged)

    def setValue(self, v):
        self.setCurrentIndex(int(v))

    def value(self):
        return self.currentIndex()

    def setSuffix(self, _s):
        pass


