def _fold_color(p):
    """Color del reverso del papel doblado: el del papel, mas oscuro y anaranjado (o el elegido)."""
    if not p.get('fold_auto', True):
        return QColor(p.get('fold_color', '#e0a800'))
    c = QColor(p['color'])
    if p.get('grad'):
        c2 = QColor(p.get('color2', p['color']))
        c = QColor((c.red() + c2.red()) // 2, (c.green() + c2.green()) // 2, (c.blue() + c2.blue()) // 2)
    h, s, v, _a = c.getHsv()
    return QColor.fromHsv(max(0, h - 6) if h >= 0 else 0, min(255, int(s * 1.2 + 30)), int(v * 0.84))


def _fold_shapes(p, w, h, pad):
    """Pico doblado de una esquina. Devuelve (shape_fn, solapa, centro_del_doblez, punta, direccion).
    Estilo 0 (doblez completo): 3 curvas independientes (dos del pico + la del doblez); la solapa es el reverso visible.
    Estilo 1 (esquina levantada): 2 curvas que se juntan en la punta, sin solapa. Curvas con signo: + = convexa, - = concava.
    Coordenadas locales (u, v) desde la esquina hacia dentro."""
    from PySide6.QtCore import QPointF
    import math
    corner = int(p.get('fold_corner', 2)) % 4
    s = float(max(8, min(int(p.get('fold_size', 60)), int(min(w, h) * 0.9))))
    style = 1 if int(p.get('fold_style', 0)) == 1 else 0
    cv = lambda k, d: max(-100, min(100, int(p.get(k, d)))) / 100.0
    c1, c2, c3 = cv('fold_c1', 40), cv('fold_c2', 40), cv('fold_c3', -60)
    tipf = max(0, min(100, int(p.get('fold_tip', 100 if style == 0 else 0)))) / 100.0
    if 'fold_rlen' in p:                              # [PACK84] longitud del redondeo (0..100) y curva (-100..100, negativo = hacia dentro) por separado
        rl = max(0, min(100, int(p['fold_rlen'])))
        dep = max(-100, min(100, int(p.get('fold_round', 100)))) / 100.0
    else:                                             # llamadas antiguas: un solo valor con signo
        rnd = max(-100, min(100, int(p.get('fold_round', 45))))
        rl, dep = abs(rnd), (1.0 if rnd >= 0 else -1.0)
    rho = rl / 100.0 * 0.45
    jn1 = max(20, min(80, int(p.get('fold_j1', 50)))) / 100.0
    jn2 = max(20, min(80, int(p.get('fold_j2', 50)))) / 100.0
    X = pad if corner in (0, 3) else pad + w
    Y = pad if corner in (0, 1) else pad + h
    sx = 1.0 if corner in (0, 3) else -1.0
    sy = 1.0 if corner in (0, 1) else -1.0

    def P(u, v):
        return QPointF(X + sx * u, Y + sy * v)

    def lerp(a, b, t):
        return QPointF(a.x() + (b.x() - a.x()) * t, a.y() + (b.y() - a.y()) * t)

    def qpt(p0, c, p1, t):
        return lerp(lerp(p0, c, t), lerp(c, p1, t), t)

    def bow(p0, p1, amount, away, pos=0.5):
        """Punto de control de una curva: el medio de la cuerda desplazado por su normal (+ = alejandose de 'away').
        pos (0..1) es donde, a lo largo de la cuerda, la curva se separa mas de ella (0.5 = en el medio)."""
        a = 2.0 * pos - 0.5
        mx, my = (p0.x() + p1.x()) / 2.0, (p0.y() + p1.y()) / 2.0
        dx, dy = p1.x() - p0.x(), p1.y() - p0.y()
        L = math.hypot(dx, dy) or 1.0
        nx, ny = -dy / L, dx / L
        if (mx - away.x()) * nx + (my - away.y()) * ny < 0:
            nx, ny = -nx, -ny
        return QPointF(p0.x() + dx * a + nx * amount * L * 0.5, p0.y() + dy * a + ny * amount * L * 0.5)

    pp = lambda k: max(0.25, min(0.75, int(p.get(k, 50)) / 100.0))
    A, B, T, FAR = P(0, s), P(s, 0), P(s * tipf, s * tipf), P(s, s)
    G = QPointF((A.x() + B.x() + T.x()) / 3.0, (A.y() + B.y() + T.y()) / 3.0)
    mid = lerp(A, B, 0.5)
    cut = QPainterPath()                        # lo que se quita del papel: la esquina, hasta las curvas elegidas
    if style == 1:
        q1, q2 = bow(A, T, c1, G, pp('fold_p1')), bow(T, B, c2, G, pp('fold_p2'))
        cut.moveTo(A)
        cut.quadTo(q1, T)
        cut.quadTo(q2, B)

        cut.lineTo(P(s, -6))
        cut.lineTo(P(-6, -6))
        cut.lineTo(P(-6, s))
        cut.closeSubpath()
        return (lambda body: body.subtracted(cut)), None, mid, T, (sx, sy)
    q1, q2, q3 = bow(A, T, c1, G, pp('fold_p1')), bow(T, B, c2, G, pp('fold_p2')), bow(B, A, c3, FAR, pp('fold_p3'))
    cut.moveTo(P(-6, -6))
    cut.lineTo(P(s, -6))
    cut.lineTo(B)
    cut.quadTo(q3, A)
    cut.lineTo(P(-6, s))
    cut.closeSubpath()
    flap = QPainterPath()
    flap.moveTo(A)
    ks = [max(-100, min(100, int(p.get(k, 0)))) / 100.0 for k in ('fold_k1', 'fold_k2', 'fold_k3', 'fold_k4')]
    TC = T                                      # control de la curva que termina la punta
    Pa = qpt(A, q1, T, 1.0 - rho)             # puntos donde empieza y termina el redondeo de la punta
    Pb = qpt(T, q2, B, rho)
    t1 = max(0.1, min(0.9 - rho, (1.0 - rho) * jn1))        # [PACK84] donde se unen las curvas 1 y 2 (a lo largo del lado 1)
    t2 = max(rho + 0.1, min(0.9, rho + (1.0 - rho) * jn2))  # y las curvas 3 y 4 (a lo largo del lado 2)

    def sub(p0, c, p1, t0, t1_, k):             # tramo t0..t1_ de una curva, con ajuste extra k de curvatura
        S, E = qpt(p0, c, p1, t0), qpt(p0, c, p1, t1_)
        w0, w1, w2 = (1 - t0) * (1 - t1_), t0 * (1 - t1_) + t1_ * (1 - t0), t0 * t1_
        ctrl = QPointF(w0 * p0.x() + w1 * c.x() + w2 * p1.x(), w0 * p0.y() + w1 * c.y() + w2 * p1.y())
        if k:
            ex, ey = E.x() - S.x(), E.y() - S.y()
            Lc = math.hypot(ex, ey) or 1.0
            nx, ny = -ey / Lc, ex / Lc
            if ((S.x() + E.x()) / 2.0 - G.x()) * nx + ((S.y() + E.y()) / 2.0 - G.y()) * ny < 0:
                nx, ny = -nx, -ny
            ctrl = QPointF(ctrl.x() + nx * k * Lc * 0.5, ctrl.y() + ny * k * Lc * 0.5)
        return ctrl, E

    def frac(J, ca, cb):                        # donde cae J entre los controles ca y cb (sin ajustes: J esta en ese segmento)
        dx, dy = cb.x() - ca.x(), cb.y() - ca.y()
        L2 = dx * dx + dy * dy
        if L2 < 1e-9:
            return 0.5
        return max(0.05, min(0.95, ((J.x() - ca.x()) * dx + (J.y() - ca.y()) * dy) / L2))
    ra, Ja0 = sub(A, q1, T, 0.0, t1, 0.0)       # [PACK84] la union depende de LAS DOS curvas: queda entre sus controles, con la proporcion de la curva base
    rb, _e = sub(A, q1, T, t1, 1.0 - rho, 0.0)
    fa = frac(Ja0, ra, rb)
    ca0, _e = sub(A, q1, T, 0.0, t1, ks[0])
    ca1, Pa = sub(A, q1, T, t1, 1.0 - rho, ks[1])
    Ja = QPointF(ca0.x() + (ca1.x() - ca0.x()) * fa, ca0.y() + (ca1.y() - ca0.y()) * fa)
    rc, Jb0 = sub(T, q2, B, rho, t2, 0.0)
    rd_, _e = sub(T, q2, B, t2, 1.0, 0.0)
    fb = frac(Jb0, rc, rd_)
    cb0, _e = sub(T, q2, B, rho, t2, ks[2])
    cb1, _e = sub(T, q2, B, t2, 1.0, ks[3])
    Jb = QPointF(cb0.x() + (cb1.x() - cb0.x()) * fb, cb0.y() + (cb1.y() - cb0.y()) * fb)
    Mc = lerp(Pa, Pb, 0.5)
    if dep < 0:                                 # hacia dentro: se refleja la punta respecto a la cuerda; la profundidad lo escala
        Tref = QPointF(1.5 * (Pa.x() + Pb.x()) - 2.0 * T.x(), 1.5 * (Pa.y() + Pb.y()) - 2.0 * T.y())
        TC = lerp(Mc, Tref, -dep)
    else:                                       # hacia fuera: sigue las tangentes de las dos curvas (continuidad); 0 = recta
        Ttan = T
        if rho > 0:
            dA, dB = (Pa.x() - ca1.x(), Pa.y() - ca1.y()), (cb0.x() - Pb.x(), cb0.y() - Pb.y())
            det = dA[0] * dB[1] - dA[1] * dB[0]
            nA, nB = math.hypot(*dA), math.hypot(*dB)
            if nA > 1e-6 and nB > 1e-6 and abs(det) > 1e-3 * nA * nB:
                rx, ry = Pb.x() - Pa.x(), Pb.y() - Pa.y()
                a, b = (rx * dB[1] - ry * dB[0]) / det, (dA[0] * ry - dA[1] * rx) / det
                if 0.0 < a < 10.0 and 0.0 < b < 10.0:
                    Ttan = QPointF(Pa.x() + a * dA[0], Pa.y() + a * dA[1])
        TC = lerp(Mc, Ttan, dep)
    flap.quadTo(ca0, Ja)
    flap.quadTo(ca1, Pa)
    flap.quadTo(TC, Pb)
    flap.quadTo(cb0, Jb)
    flap.quadTo(cb1, B)
    flap.quadTo(q3, A)

    flap.closeSubpath()
    return (lambda body: body.subtracted(cut)), flap, mid, T, (sx, sy)


def _soft_shadow(size, path, blur, color, op):
    """Sombra difuminada de una forma: mascara -> desenfoque (3 pasadas de caja ~ gaussiana) -> color con opacidad."""
    W, H = size.width(), size.height()
    m = QImage(W, H, QImage.Format_ARGB32_Premultiplied)
    m.fill(Qt.transparent)
    mp = QPainter(m)
    mp.setRenderHint(QPainter.Antialiasing)
    mp.setPen(Qt.NoPen)
    mp.setBrush(QColor(255, 255, 255, 255))
    mp.drawPath(path)
    mp.end()
    arr = np.frombuffer(m.constBits(), dtype=np.uint8).reshape((H, m.bytesPerLine() // 4, 4))[:, :W, 3].astype(np.float32)
    r = max(1, int(round(blur * 0.33)))
    k = 2 * r + 1
    for _ in range(3):
        for ax in (0, 1):
            c = np.cumsum(np.pad(arr, [(r + 1, r) if i == ax else (0, 0) for i in (0, 1)], mode='constant'), axis=ax)
            arr = (c[k:] - c[:-k]) / k if ax == 0 else (c[:, k:] - c[:, :-k]) / k

    a = np.clip(arr * op, 0, 255)
    out = np.zeros((H, W, 4), dtype=np.uint8)
    out[:, :, 0] = (color.blue() * a / 255.0).astype(np.uint8)
    out[:, :, 1] = (color.green() * a / 255.0).astype(np.uint8)
    out[:, :, 2] = (color.red() * a / 255.0).astype(np.uint8)
    out[:, :, 3] = a.astype(np.uint8)
    res = QImage(out.data, W, H, W * 4, QImage.Format_ARGB32_Premultiplied).copy()
    return res


def _shade_layer(size, path, blur, white, strength):
    """[PACK73] Sombra (negra) o brillo (blanco) difuminado de una forma; strength 0..300 (por encima de 100 se refuerza)."""
    return _soft_shadow(size, path, max(1, int(blur)), QColor(255, 255, 255) if white else QColor(0, 0, 0),
                        max(0.0, min(3.0, strength / 100.0)))


def _tip_blob(p, flap, ftip, fdir, size_px, shift):
    """Mancha circular en la punta (redondeada) de la solapa, algo desplazada hacia dentro del papel."""
    from PySide6.QtCore import QPointF
    rr = abs(max(-100, min(100, int(p.get('fold_round', 45))))) / 100.0 * 0.45
    c = flap.boundingRect().center()
    cx = ftip.x() + (c.x() - ftip.x()) * rr * 0.9 + fdir[0] * shift + int(p.get('tip_dx', 0))
    cy = ftip.y() + (c.y() - ftip.y()) * rr * 0.9 + fdir[1] * shift + int(p.get('tip_dy', 0))
    r = max(3.0, size_px * 0.6)
    path = QPainterPath()
    path.addEllipse(QPointF(cx, cy), r, r)
    return path


# [PACK80] esquinas levantadas (hasta 4, cada una con sus ajustes) y degradados con forma
LIFT_DEFAULTS = {'on': False, 'size': 90, 'tip': 0, 'c1': -45, 'p1': 50, 'c2': -45, 'p2': 50,
                 'sh': 40, 'sh_size': 16, 'sh_dx': 0, 'sh_dy': 0,          # sombra (negra) del borde levantado
                 'hi': 0, 'hi_size': 16, 'hi_dx': 0, 'hi_dy': 0,           # brillo (blanco) del borde levantado
                 'front': True, 'cast': 0}                                 # capa de las luces / separacion de la sombra de la nota


def _norm_lifts(p):
    """Lista de 4 ajustes de esquina levantada (0 sup.izq., 1 sup.der., 2 inf.der., 3 inf.izq.).
    Si la nota es antigua (una sola esquina: fold_* y lift_*), se convierte a esta forma."""
    def clean(src):
        d = dict(LIFT_DEFAULTS)
        for k, dv in LIFT_DEFAULTS.items():
            if k in src:
                try:
                    d[k] = bool(src[k]) if isinstance(dv, bool) else int(src[k])
                except (ValueError, TypeError):
                    pass
        return d
    src = p.get('lifts')
    if isinstance(src, list) and len(src) == 4 and all(isinstance(x, dict) for x in src):
        return [clean(x) for x in src]
    out = [dict(LIFT_DEFAULTS) for _ in range(4)]
    if p.get('fold') and int(p.get('fold_style', 0)) == 1:
        white = bool(p.get('lift_white', False))

        k = int(p.get('lift_shade', 0))
        out[int(p.get('fold_corner', 2)) % 4] = clean({
            'on': True, 'size': p.get('fold_size', 60), 'tip': p.get('fold_tip', 0),
            'c1': p.get('fold_c1', 40), 'p1': p.get('fold_p1', 50), 'c2': p.get('fold_c2', 40), 'p2': p.get('fold_p2', 50),
            'sh': 0 if white else k, 'hi': k if white else 0,
            'sh_size': p.get('lift_size', 14), 'hi_size': p.get('lift_size', 14),
            'sh_dx': p.get('lift_dx', 0), 'sh_dy': p.get('lift_dy', 0), 'hi_dx': p.get('lift_dx', 0), 'hi_dy': p.get('lift_dy', 0),
            'front': p.get('lift_front', True), 'cast': 0})
    return out


def _lifts_with(spec):
    """Lista de 4 ajustes con los de 'spec' ({esquina: {clave: valor}}) activados; el resto, apagados."""
    out = [dict(LIFT_DEFAULTS) for _ in range(4)]
    for i, d in spec.items():
        out[i].update(d)
        out[i]['on'] = True
    return out


# [PACK81] cada esquina decide que hace: 0 nada, 1 doblez completo (con solapa), 2 esquina levantada
CX_DEFAULTS = {
    'mode': 0, 'size': 60, 'tip': 100,
    'c1': 40, 'p1': 50, 'c2': 40, 'p2': 50, 'c3': -60, 'p3': 50, 'rlen': 45, 'round': 100,      # curvas del pico (lados 1 y 2) y del doblez; punta: longitud del redondeo y curva (-100..100)
    'k1': 0, 'k2': 0, 'k3': 0, 'k4': 0, 'j1': 50, 'j2': 50,                         # ajuste extra de cada uno de los 4 tramos del pico y donde se unen (curvas 1-2 y 3-4)
    'rev_auto': True, 'rev_color': '#e0a800',
    'fa_k': 0, 'fa_a': 45, 'fa_s': 10, 'fa_dx': 0, 'fa_dy': 0,                       # doblez: luz que la solapa proyecta sobre el papel
    'fb_k': 1, 'fb_a': 0, 'fb_s': 14, 'fb_dx': 0, 'fb_dy': 0, 'fb_over': True,       # doblez: luz de la punta redondeada
    'la_k': 0, 'la_a': 40, 'la_s': 16, 'la_dx': 0, 'la_dy': 0,                       # levantada: luz 1 del borde (k: 0 sombra, 1 brillo)
    'lb_k': 1, 'lb_a': 0, 'lb_s': 16, 'lb_dx': 0, 'lb_dy': 0,                        # levantada: luz 2 del borde
    'front': True, 'cast': 0,                                                        # capa de las luces / separacion de la sombra de la nota
}


def _cx_new(corner, mode=0):
    """Ajustes por defecto de una esquina. La luz viene de arriba a la izquierda: en la esquina inferior derecha
    las luces empiezan al reves (brillo y sombra en vez de sombra y brillo)."""
    d = dict(CX_DEFAULTS)
    d['mode'] = int(mode)
    if int(mode) == 2:
        d.update(size=90, tip=0, c1=-45, c2=-45)
    if int(corner) == 2:
        d['fa_k'], d['fb_k'], d['la_k'], d['lb_k'] = 1, 0, 1, 0
    return d


def _cx_clean(i, x):
    try:
        m = max(0, min(2, int(x.get('mode', 0))))
    except (ValueError, TypeError):
        m = 0
    d = _cx_new(i, m)
    if 'rlen' not in x and 'round' in x:             # [PACK84] antes un solo valor con signo: longitud = su valor absoluto, curva = su signo
        try:
            r0 = int(x['round'])
            x = dict(x, rlen=abs(r0), round=100 if r0 >= 0 else -100)
        except (ValueError, TypeError):
            pass
    for k, dv in CX_DEFAULTS.items():
        if k in x and k != 'mode':
            try:
                d[k] = bool(x[k]) if isinstance(dv, bool) else (str(x[k]) if isinstance(dv, str) else int(x[k]))
            except (ValueError, TypeError):
                pass
    return d


def _cx_with(spec):
    """Lista de 4 esquinas con los ajustes de 'spec' ({esquina: {clave: valor}}); el resto, sin efecto."""
    out = [_cx_new(i, 0) for i in range(4)]
    for i, d in spec.items():
        out[i] = _cx_clean(i, d)
    return out


def _norm_cx(p):
    """Lista de 4 ajustes de esquina (0 sup.izq., 1 sup.der., 2 inf.der., 3 inf.izq.). Las notas anteriores
    (una sola esquina doblada, o esquinas levantadas del pack 80) se convierten a esta forma."""
    src = p.get('cx')
    if isinstance(src, list) and len(src) == 4 and all(isinstance(x, dict) for x in src):
        return [_cx_clean(i, x) for i, x in enumerate(src)]
    out = [_cx_new(i, 0) for i in range(4)]
    if not p.get('fold'):
        return out
    if int(p.get('fold_style', 0)) == 1:
        for i, L in enumerate(_norm_lifts(p)):
            if L['on']:
                out[i] = _cx_clean(i, {'mode': 2, 'size': L['size'], 'tip': L['tip'], 'c1': L['c1'], 'p1': L['p1'], 'c2': L['c2'], 'p2': L['p2'],
                                       'la_k': 0, 'la_a': L['sh'], 'la_s': L['sh_size'], 'la_dx': L['sh_dx'], 'la_dy': L['sh_dy'],
                                       'lb_k': 1, 'lb_a': L['hi'], 'lb_s': L['hi_size'], 'lb_dx': L['hi_dx'], 'lb_dy': L['hi_dy'],
                                       'front': L['front'], 'cast': L['cast']})
        return out
    i = int(p.get('fold_corner', 2)) % 4

    out[i] = _cx_clean(i, {'mode': 1, 'size': p.get('fold_size', 60), 'tip': p.get('fold_tip', 100),
                           'c1': p.get('fold_c1', 40), 'p1': p.get('fold_p1', 50), 'c2': p.get('fold_c2', 40), 'p2': p.get('fold_p2', 50),
                           'c3': p.get('fold_c3', -60), 'p3': p.get('fold_p3', 50), 'round': p.get('fold_round', 45),
                           'rev_auto': p.get('fold_auto', True), 'rev_color': p.get('fold_color', '#e0a800'),
                           'fa_k': 0, 'fa_a': p.get('fold_shadow', 45), 'fa_s': p.get('fold_shadow_size', 10),
                           'fa_dx': p.get('fold_shadow_dx', 0), 'fa_dy': p.get('fold_shadow_dy', 0),
                           'fb_k': 1 if p.get('tip_white', True) else 0, 'fb_a': p.get('tip_shade', 0), 'fb_s': p.get('tip_size', 14),
                           'fb_dx': p.get('tip_dx', 0), 'fb_dy': p.get('tip_dy', 0), 'fb_over': p.get('tip_over', True)})
    return out


def _cx_shape(i, c):
    """Parametros de forma de una esquina, con los nombres que entiende _fold_shapes."""
    return {'fold_corner': i, 'fold_style': 1 if c['mode'] == 2 else 0, 'fold_size': c['size'], 'fold_tip': c['tip'],
            'fold_c1': c['c1'], 'fold_c2': c['c2'], 'fold_c3': c['c3'], 'fold_p1': c['p1'], 'fold_p2': c['p2'], 'fold_p3': c['p3'],
            'fold_round': c['round'], 'fold_rlen': c['rlen'], 'fold_j1': c['j1'], 'fold_j2': c['j2'],
            'fold_k1': c['k1'], 'fold_k2': c['k2'], 'fold_k3': c['k3'], 'fold_k4': c['k4']}

def _pct(v, d=100):
    """[PACK132] Porcentaje 0-100 como fraccion 0-1 (valores raros -> el de por defecto)."""
    try:
        return max(0, min(100, int(v))) / 100.0
    except (TypeError, ValueError):
        return d / 100.0


def _paper_colors(p):
    """[PACK132] Los dos colores del fondo, cada uno con su opacidad."""
    c1 = QColor(p['color'])
    c2 = QColor(p.get('color2', p['color']))
    c1.setAlphaF(_pct(p.get('color_a', 100)))
    c2.setAlphaF(_pct(p.get('color2_a', 100)))
    return c1, c2


EDGE_BORDER = ('border_color', 'border_color2', 'border_a', 'border_a2', 'border_grad', 'border_grad_angle', 'border_grad_bias')
EDGE_FOLD = ('fold_bcolor', 'fold_bcolor2', 'fold_ba', 'fold_ba2', 'fold_bgrad', 'fold_bangle', 'fold_bbias')


def _edge_brush(p, keys, rect):
    """[PACK132] Pincel de un borde: color liso o degradado lineal entre dos colores, cada uno con su opacidad,
    con direccion (90 = hacia abajo) y balance, sobre el rectangulo dado."""
    import math
    kc, kc2, ka, ka2, kg, kang, kbias = keys
    c1 = QColor(p[kc])
    c1.setAlphaF(_pct(p.get(ka, 100)))
    if not p.get(kg):
        return QBrush(c1)
    c2 = QColor(p.get(kc2, p[kc]))
    c2.setAlphaF(_pct(p.get(ka2, 100)))
    ang = math.radians(float(p.get(kang, 90)))
    ux, uy = math.cos(ang), math.sin(ang)
    half = max(1.0, (abs(ux) * rect.width() + abs(uy) * rect.height()) / 2.0)
    cx, cy = rect.center().x(), rect.center().y()
    g = QLinearGradient(cx - ux * half, cy - uy * half, cx + ux * half, cy + uy * half)
    bias = max(5, min(95, int(p.get(kbias, 50)))) / 100.0
    g.setColorAt(0.0, c1)
    if bias != 0.5:
        g.setColorAt(bias, QColor.fromRgbF((c1.redF() + c2.redF()) / 2.0, (c1.greenF() + c2.greenF()) / 2.0,
                                           (c1.blueF() + c2.blueF()) / 2.0, (c1.alphaF() + c2.alphaF()) / 2.0))
    g.setColorAt(1.0, c2)
    return QBrush(g)


def _edge_translucent(p, keys):
    kc, kc2, ka, ka2, kg, kang, kbias = keys
    return _pct(p.get(ka, 100)) < 1.0 or (bool(p.get(kg)) and _pct(p.get(ka2, 100)) < 1.0)


def _paint_ring(q, ring, brush, translucent):
    """[PACK132] Pinta un borde (una corona). Si es translucido primero vacia lo que hay debajo: la opacidad es la del borde
    y deja ver lo que hay detras del widget, en vez de mezclarse con el color del papel."""
    q.save()
    q.setPen(Qt.NoPen)
    if translucent:
        q.setCompositionMode(QPainter.CompositionMode_Clear)
        q.setBrush(Qt.black)
        q.drawPath(ring)
        q.setCompositionMode(QPainter.CompositionMode_SourceOver)
    q.setBrush(brush)
    q.drawPath(ring)
    q.restore()


def _grad_brush(p, w, h, pad):
    """Pincel del fondo: color liso o degradado (0 lineal, 1 radial, 2 conico, 3 espejo) con direccion, tamano,
    centro, balance entre los dos colores y comportamiento fuera de su tamano (rellenar, reflejar, repetir)."""
    import math
    from PySide6.QtGui import QConicalGradient, QRadialGradient, QGradient
    c1, c2 = _paper_colors(p)
    if not p.get('grad'):
        return QBrush(c1)
    kind = max(0, min(3, int(p.get('grad_kind', 0))))
    ang_deg = float(p.get('grad_angle', 90))
    ang = math.radians(ang_deg)
    ux, uy = math.cos(ang), math.sin(ang)
    size = max(5, min(400, int(p.get('grad_size', 100)))) / 100.0
    cx = pad + w / 2.0 + max(-100, min(100, int(p.get('grad_cx', 0)))) / 100.0 * w / 2.0
    cy = pad + h / 2.0 + max(-100, min(100, int(p.get('grad_cy', 0)))) / 100.0 * h / 2.0
    bias = max(5, min(95, int(p.get('grad_bias', 50)))) / 100.0
    spread = {1: QGradient.ReflectSpread, 2: QGradient.RepeatSpread}.get(int(p.get('grad_spread', 0)), QGradient.PadSpread)
    half = max(1.0, (abs(ux) * w + abs(uy) * h) / 2.0 * size)

    if kind == 2:
        g = QConicalGradient(cx, cy, -ang_deg)
        g.setColorAt(0.0, c1)
        g.setColorAt(bias, c2)
        g.setColorAt(1.0, c1)
        return QBrush(g)
    if kind == 1:
        g = QRadialGradient(cx, cy, max(1.0, math.hypot(w, h) / 2.0 * size))
    elif kind == 3:
        g = QLinearGradient(cx, cy, cx + ux * half, cy + uy * half)
        spread = QGradient.ReflectSpread
    else:
        g = QLinearGradient(cx - ux * half, cy - uy * half, cx + ux * half, cy + uy * half)
    g.setSpread(spread)
    g.setColorAt(0.0, c1)
    if bias != 0.5:
        g.setColorAt(bias, QColor.fromRgbF((c1.redF() + c2.redF()) / 2.0, (c1.greenF() + c2.greenF()) / 2.0,
                                           (c1.blueF() + c2.blueF()) / 2.0, (c1.alphaF() + c2.alphaF()) / 2.0))

    g.setColorAt(1.0, c2)
    return QBrush(g)


# ---------------------------------------------------------------- [PACK135] estudio de rendimiento del equipo
PERF_CFG = os.path.join(DATA_DIR, "rendimiento.json")      # solo de este equipo: no entra en copias de seguridad ni en los sets
PERF_LEVEL_NAMES = {1: "M\u00e1xima", 0: "Autom\u00e1tica", 2: "Ligera", 3: "M\u00ednima"}
_PERF_N = 12                                               # cables del cuadro de prueba (una escena normal)


def perf_cfg_load():
    try:
        with open(PERF_CFG, 'r', encoding='utf-8') as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def perf_cfg_save(d):
    try:
        tmp = PERF_CFG + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(d, f, indent=2, ensure_ascii=False)
        os.replace(tmp, PERF_CFG)
    except OSError as e:
        log_warn("Rendimiento", "No se pudo guardar rendimiento.json: %s" % e)


def _perf_curves(n, w, h):
    """Camino y puntos de n cables curvos de ~110 puntos, parecidos a las cuerdas del programa."""
    out = []
    for i in range(n):
        x0, y0 = 80 + (i * 97) % (w - 160), 60 + (i * 53) % (h - 120)
        x1, y1 = w - 80 - (i * 71) % (w - 160), h - 60 - (i * 89) % (h - 120)
        sag = 60 + (i % 5) * 18
        pts = []
        for k in range(110):
            t = k / 109.0
            pts.append(QPointF(x0 + (x1 - x0) * t, y0 + (y1 - y0) * t + sag * math.sin(math.pi * t) + 6 * math.sin(14 * t + i)))
        path = QPainterPath(pts[0])
        for q in pts[1:]:
            path.lineTo(q)
        out.append((path, pts))
    return out


def _perf_paint(img, curves, lod):
    """Un fotograma de cables de prueba con el mismo tipo de trabajo que cada nivel de detalle: 0 resplandor, degradado y grosor
    variable; 1 sin resplandor; 2 ademas grosor fijo y punteado; 3 ademas sin suavizado de bordes."""
    p = QPainter(img)
    p.setCompositionMode(QPainter.CompositionMode_Source)
    p.fillRect(img.rect(), Qt.transparent)
    p.setCompositionMode(QPainter.CompositionMode_SourceOver)
    if lod < 3:
        p.setRenderHint(QPainter.Antialiasing)
    for i, (path, pts) in enumerate(curves):
        col = QColor.fromHsv((i * 29) % 360, 160, 230)
        if lod == 0:
            for wd, al in ((6, 30),):
                g = QColor(col)
                g.setAlpha(al)
                pen = QPen(g, wd)
                pen.setCapStyle(Qt.RoundCap)
                p.setPen(pen)
                p.drawPath(path)

        if lod <= 1:
            grad = QLinearGradient(pts[0], pts[-1])
            grad.setColorAt(0.0, col)
            grad.setColorAt(1.0, col.lighter(135))
            pen = QPen(QBrush(grad), 3.5)
        else:
            pen = QPen(col, 3.0)
        if i % 2:
            pen.setDashPattern([6.0, 5.0])
        if lod == 0:
            for k in range(0, len(pts) - 1, 37):
                pen.setWidthF(2.2 + 2.0 * abs(math.sin(0.5 * k + i)))
                p.setPen(pen)
                p.drawPolyline(pts[k:k + 38])
        else:
            p.setPen(pen)
            p.drawPath(path)
    p.end()


def _perf_median_ms(fn, min_runs=5, max_s=0.35):
    ts = []
    t_end = time.perf_counter() + max_s
    while len(ts) < min_runs or (time.perf_counter() < t_end and len(ts) < 40):
        t0 = time.perf_counter()
        fn()
        ts.append((time.perf_counter() - t0) * 1000.0)
    ts.sort()
    return ts[len(ts) // 2]


def _perf_rope_ms(n=_PERF_N):
    """Coste por fotograma de integrar n cuerdas (mismo tipo de operaciones con arrays que _ropes_integrate)."""
    NM = 40
    U = np.random.rand(2, n, NM)
    V = np.zeros_like(U)

    def frame():
        for _k in range(16):
            F = -4.0 * U - 0.5 * V
            F[:, :, 1:-1] += (U[:, :, :-2] + U[:, :, 2:] - 2.0 * U[:, :, 1:-1]) * 3.0
            V.__iadd__(F * 0.01)
            U.__iadd__(V * 0.01)
    return _perf_median_ms(frame, 4, 0.2)


def perf_steps():
    """Banco de pruebas en pasos cortos (generador): cada paso da (fraccion, texto) y el resultado final es el valor del generador.
    Dura unos 2-3 segundos; no toca los widgets del usuario: dibuja en imagenes aparte."""
    m = {'ver': 1, 'n': _PERF_N, 'cores': int(os.cpu_count() or 1)}
    yield 0.03, "Midiendo la pantalla y el procesador..."
    try:
        scr = QGuiApplication.primaryScreen()
        g = scr.geometry()
        dpr = float(scr.devicePixelRatio() or 1.0)
        sw, sh = int(g.width() * dpr), int(g.height() * dpr)
        for s_ in QGuiApplication.screens():
            if s_ is not scr:
                m.setdefault('extra_screens', 0)
                m['extra_screens'] += 1
    except Exception:
        sw, sh = 1920, 1080
    sw, sh = max(640, min(sw, 7680)), max(360, min(sh, 4320))
    m['screen'] = [sw, sh]

    def py_loop():
        s = 0
        for i in range(120000):
            s += i & 7
        return s
    m['py_ms'] = round(_perf_median_ms(py_loop, 3, 0.15), 2)
    curves = _perf_curves(_PERF_N, 1280, 720)
    img = QImage(1280, 720, QImage.Format_ARGB32_Premultiplied)
    paint = {}
    for lod, label in ((0, "calidad m\u00e1xima"), (1, "sin resplandor"), (2, "calidad ligera"), (3, "calidad m\u00ednima")):
        yield 0.12 + 0.16 * lod, "Dibujando cables de prueba: %s..." % label
        _perf_paint(img, curves, lod)                       # calentamiento
        paint[lod] = round(_perf_median_ms(lambda lod=lod: _perf_paint(img, curves, lod)), 2)
    m['paint_ms'] = paint
    yield 0.78, "Midiendo el cuadro completo de pantalla..."
    big = QImage(sw, sh, QImage.Format_ARGB32_Premultiplied)

    def fill():
        big.fill(Qt.transparent)
        q = QPainter(big)
        q.drawImage(0, 0, img)
        q.end()
    fill()
    m['fill_ms'] = round(_perf_median_ms(fill, 4, 0.2), 2)
    yield 0.86, "Midiendo la animaci\u00f3n de las cuerdas..."
    m['rope_ms'] = round(_perf_rope_ms(), 2)
    yield 0.94, "Midiendo el difuminado..."
    bl = QImage(200, 150, QImage.Format_ARGB32_Premultiplied)
    bl.fill(Qt.transparent)
    q = QPainter(bl)
    q.setPen(QPen(QColor(255, 0, 0, 160), 2))
    q.drawLine(10, 70, 190, 90)
    q.end()
    m['blur_ms'] = round(_perf_median_ms(lambda: _blur_image(bl, 6, 0.55), 4, 0.2), 2)
    yield 1.0, "Listo"

    return m


def perf_measure(on_step=None):
    """Ejecuta todo el banco de pruebas de una vez y devuelve las medidas (para pruebas y para uso sin ventana)."""
    g = perf_steps()
    try:
        while True:
            fr, lb = next(g)
            if on_step:
                on_step(fr, lb)
    except StopIteration as e:
        return e.value


def perf_estimate(m, lod, n=_PERF_N):
    """Milisegundos estimados por fotograma con n cables y el nivel de detalle lod (0 maxima, 2 ligera, 3 minima)."""
    k = float(n) / float(m.get('n') or _PERF_N)
    ms = m['paint_ms'][lod] * k + m['fill_ms']
    if lod <= 1:
        ms += m['rope_ms'] * k                                # solo con 'maxima' las cuerdas se mueven siempre
    return ms


def perf_recommend(m):
    """Del resultado del banco de pruebas: calidad de dibujo, fotogramas de las cuerdas y tope de difuminado recomendados."""
    e = lambda lod, n: perf_estimate(m, lod, n)
    if e(0, 30) <= 10.0:
        q = 1
    elif e(0, 30) <= 22.0:
        q = 0
    elif e(2, 30) <= 22.0:
        q = 2
    else:
        q = 3
    lod = 0 if q in (0, 1) else q
    e12 = e(lod, 12)
    fps = 60 if e12 <= 8.0 else 45 if e12 <= 14.0 else 30 if e12 <= 22.0 else 24 if e12 <= 33.0 else 15
    fps = min(fps, 30 if q == 2 else 20 if q == 3 else 60)
    bl = 24.0 * m['blur_ms']
    blur_max = 0 if q in (2, 3) else (30 if bl <= 12.0 else 8 if bl <= 24.0 else 0)
    rec = {'quality': q, 'fps': int(fps), 'blur_max': int(blur_max),
           'est': {str(l): [round(e(l, 12), 1), round(e(l, 30), 1)] for l in (0, 2, 3)}}

    rec['why'] = ("Con 12 cables, un fotograma cuesta unos %.0f ms en m\u00e1xima calidad y unos %.0f ms con 30 cables; en ligera, %.0f y %.0f ms."
                  % (e(0, 12), e(0, 30), e(2, 12), e(2, 30)))
    return rec


def perf_apply(mgr, rec):
    """Aplica una recomendacion a los ajustes del programa (el difuminado solo se baja, nunca se sube)."""
    G = mgr.global_state
    G['_cable_quality'] = int(rec['quality'])
    G['_rope_fps'] = int(rec['fps'])
    G['_cable_inside_blur'] = min(int(mgr.get_cable_param('_cable_inside_blur')), int(rec['blur_max']))
    mgr.save_global_state(record_history=False)
    try:
        if mgr.connector_overlay.isVisible():
            mgr.connector_overlay.update()
    except Exception:
        pass


class PerfStudyDialog(QDialog):
    """[PACK135] Estudio breve del equipo: dibuja cables de prueba y recomienda calidad, fotogramas y difuminado."""

    def __init__(self, manager, parent=None, first_run=False, apply_cb=None):
        super().__init__(parent)
        from PySide6.QtWidgets import QProgressBar
        self._mgr, self._apply_cb, self.first_run = manager, apply_cb, bool(first_run)
        self.metrics = self.rec = self._gen = None
        self.setWindowTitle("Medir el rendimiento de este equipo")
        lay = QVBoxLayout(self)
        self.info = QLabel(("Opcional. " if first_run else "") +
                           "En unos 3 segundos el programa dibuja cables de prueba en cada nivel de calidad, mide la pantalla y la "
                           "animaci\u00f3n de las cuerdas, y recomienda la calidad de dibujo, los fotogramas por segundo y el difuminado "
                           "que van fluidos en este equipo. No toca tus widgets y no cambia nada hasta que aceptes la recomendaci\u00f3n.")
        self.info.setWordWrap(True)
        lay.addWidget(self.info)
        self.bar = QProgressBar()
        self.bar.setRange(0, 100)
        self.bar.setVisible(False)
        lay.addWidget(self.bar)
        self.lbl = QLabel("")

        lay.addWidget(self.lbl)
        self.out = QLabel("")
        self.out.setWordWrap(True)
        self.out.setTextFormat(Qt.RichText)
        self.out.setVisible(False)
        lay.addWidget(self.out)
        row = QHBoxLayout()
        row.addStretch(1)
        self.b_run = QPushButton("Medir ahora")
        self.b_apply = QPushButton("Aplicar la recomendaci\u00f3n")
        self.b_close = QPushButton("Ahora no" if first_run else "Cerrar")
        self.b_apply.setEnabled(False)
        self.b_run.clicked.connect(self.start)
        self.b_apply.clicked.connect(self._apply)
        self.b_close.clicked.connect(self.reject)
        for b in (self.b_run, self.b_apply, self.b_close):
            row.addWidget(b)
        lay.addLayout(row)

        self._timer = QTimer(self)
        self._timer.setSingleShot(True)
        self._timer.timeout.connect(self._tick)
        self.setMinimumWidth(520)

    def start(self):
        if self._gen is not None:
            return
        self.b_run.setEnabled(False)
        self.b_apply.setEnabled(False)
        self.out.setVisible(False)
        self.lbl.setVisible(True)
        self.bar.setValue(0)
        self.bar.setVisible(True)
        self._gen = perf_steps()
        self._timer.start(30)

    def _tick(self):
        try:
            fr, lb = next(self._gen)
        except StopIteration as e:
            self._gen = None
            self._finish(e.value)
            return
        except Exception as e_ps:
            self._gen = None
            log_warn("Rendimiento", "El estudio fall\u00f3: %s" % e_ps)
            self.lbl.setText("No se pudo medir este equipo (%s)." % e_ps)
            self.bar.setVisible(False)
            self.b_run.setEnabled(True)
            return
        self.bar.setValue(int(fr * 100))
        self.lbl.setText(lb)
        self._timer.start(15)

    def _finish(self, m):
        self.metrics, self.rec = m, perf_recommend(m)
        r = self.rec
        self.bar.setVisible(False)
        self.lbl.setVisible(False)
        self.b_close.setText("Cerrar")
        rows = ""
        for lod, nm in ((0, "M\u00e1xima"), (2, "Ligera"), (3, "M\u00ednima")):
            e12, e30 = r['est'][str(lod)]
            rows += "<tr><td>%s</td><td align='right'>&nbsp;&nbsp;%.0f ms (\u2248 %d fps)</td><td align='right'>&nbsp;&nbsp;%.0f ms (\u2248 %d fps)</td></tr>" % (
                nm, e12, min(999, 1000 / max(e12, 0.1)), e30, min(999, 1000 / max(e30, 0.1)))
        self.out.setText(
            "<p><b>Recomendado:</b> calidad <b>%s</b>, cuerdas a <b>%d fps</b> y difuminado interior de hasta <b>%d px</b>.</p>"
            "<table><tr><td></td><td>&nbsp;&nbsp;<i>con 12 cables</i></td><td>&nbsp;&nbsp;<i>con 30 cables</i></td></tr>%s</table>"
            "<p>%s Pantalla de %d\u00d7%d, %d n\u00facleos.</p>"
            "<p>La calidad \u00abAutom\u00e1tica\u00bb baja sola cuando hay muchos cables; \u00abM\u00e1xima\u00bb solo se recomienda si sobra margen "
            "incluso con 30.</p>" % (PERF_LEVEL_NAMES[r['quality']], r['fps'], r['blur_max'], rows, r['why'],
                                      m['screen'][0], m['screen'][1], m['cores']))

        self.out.setVisible(True)
        self.b_run.setText("Repetir")
        self.b_run.setEnabled(True)
        self.b_apply.setEnabled(True)
        cfg = perf_cfg_load()
        cfg.update({'asked': True, 'pendiente': False, 'fecha': datetime.datetime.now().isoformat(timespec='seconds'),
                    'metrics': m, 'rec': {k: v for k, v in r.items() if k != 'why'}, 'applied': False})
        perf_cfg_save(cfg)

    def _apply(self):
        if not self.rec:
            return
        if self._apply_cb is not None:
            self._apply_cb(self.rec)
        else:
            perf_apply(self._mgr, self.rec)
        cfg = perf_cfg_load()
        cfg['applied'] = True
        perf_cfg_save(cfg)
        self.accept()

    def done(self, r):
        self._timer.stop()
        self._gen = None
        cfg = perf_cfg_load()
        if not cfg.get('asked'):
            cfg.update({'asked': True, 'pendiente': False})       # con "Ahora no" no se vuelve a ofrecer solo
            perf_cfg_save(cfg)
        super().done(r)


# ---------------------------------------------------------------- [PACK136] papel real de las notas y velo sobre lo que queda bajo un widget transparente
def _bn_geom(bp):
    """(ancho, alto, margen) de la imagen de una nota base: el margen transparente que rodea al papel (sombra, luces de las
    esquinas). Es la misma cuenta que hace render_base_note, y asi se conoce el papel sin tener que adivinarlo por los pixeles."""
    pw, ph = max(20, int(bp['w'])), max(20, int(bp['h']))
    sdw, sdx, sdy = max(0, int(bp.get('shadow', 0))), int(bp.get('shadow_dx', 0)), int(bp.get('shadow_dy', 0))
    mg = (sdw + max(abs(sdx), abs(sdy)) + 2) if sdw > 0 else (max(abs(sdx), abs(sdy)) + 2)
    if bp.get('fold'):
        for _i, cc in enumerate(_norm_cx(bp)):
            if cc['mode'] == 2:
                for kk in ('la', 'lb'):
                    if int(cc[kk + '_a']) > 0 and not cc['front']:
                        mg = max(mg, int(cc[kk + '_s']) + 2 + max(abs(int(cc[kk + '_dx'])), abs(int(cc[kk + '_dy']))))
                if int(cc['cast']) > 0 and sdw > 0:
                    mg = max(mg, sdw + int(cc['cast']) + max(abs(sdx), abs(sdy)) + 2)
    return pw, ph, mg


def _bn_body_path(bp):
    """[PACK137] Contorno del papel de una nota base en coordenadas de su imagen, con las esquinas dobladas o levantadas ya recortadas
    (el hueco de una esquina doblada no es papel). Devuelve (contorno, ancho de la imagen, alto de la imagen, margen)."""
    pw, ph, mg = _bn_geom(bp)
    r = float(bp['radius'])
    body = _rounded_rect_path(mg, mg, pw, ph, [r if c else 0.0 for c in bp['corners']])
    if bp.get('fold'):
        whole = _rounded_rect_path(0, 0, pw + 2 * mg, ph + 2 * mg, (0, 0, 0, 0))
        for i, cc in enumerate(_norm_cx(bp)):
            if cc['mode']:
                shape_fn = _fold_shapes(_cx_shape(i, cc), pw, ph, mg)[0]
                body = shape_fn(body).intersected(whole)
    return body, pw + 2 * mg, ph + 2 * mg, mg


class _UnderVeil(QWidget):
    """Capa transparente a los clics, encima de todo lo de un widget: resta opacidad (composicion DestinationOut) a lo que hay
    debajo, solo en las zonas que cubre un widget transparente de encima. Es pintura de Qt: igual en Windows, macOS y Linux."""

    def __init__(self, parent):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        self.region = QRegion()      # en coordenadas de la capa
        self.alpha = 0
        self.hide()

    def paintEvent(self, event):
        if self.region.isEmpty() or self.alpha <= 0:
            return
        p = QPainter(self)
        p.setCompositionMode(QPainter.CompositionMode_DestinationOut)
        p.setClipRegion(self.region)
        p.fillRect(self.rect(), QColor(0, 0, 0, int(self.alpha)))
        p.end()


# ---------------------------------------------------------------- [PACK134] recorte de capas, silueta, difuminado y regiones
def _image_alpha(img):
    """Canal alfa (matriz alto x ancho de uint8, copia propia) de una QImage."""
    im = img.convertToFormat(QImage.Format_RGBA8888)
    w, h = im.width(), im.height()
    return np.array(np.frombuffer(im.bits(), dtype=np.uint8).reshape((h, w, 4))[:, :, 3], copy=True)


def _bool_to_region(m):
    """QRegion con los pixeles True de una matriz booleana (alto x ancho)."""
    h, w = m.shape
    bits = np.packbits(m.astype(np.uint8), axis=1, bitorder='little')
    return QRegion(QBitmap.fromData(QSize(w, h), bits.tobytes(), QImage.Format_MonoLSB))


def _alpha_region(pm):
    """Region que ocupa de verdad una imagen: sus pixeles con algo de opacidad (sin el halo tenue de la sombra)."""
    img = pm.toImage() if isinstance(pm, QPixmap) else pm
    a = _image_alpha(img)
    amax = int(a.max()) if a.size else 0
    if amax <= 0:
        return QRegion()
    return _bool_to_region(a >= max(8, min(48, int(amax * 0.6))))


def _clip_shape_image(mode, w, h, radius_pct=25):
    """Mascara (QImage; solo importa su alfa) de un recorte de forma: 1 = rectangulo de esquinas redondeadas, 2 = elipse."""
    w, h = max(1, int(w)), max(1, int(h))
    img = QImage(w, h, QImage.Format_ARGB32_Premultiplied)
    img.fill(Qt.transparent)
    q = QPainter(img)
    q.setRenderHint(QPainter.Antialiasing)
    q.setPen(Qt.NoPen)
    q.setBrush(Qt.black)
    if mode == 2:
        q.drawEllipse(QRectF(0, 0, w, h))
    else:
        r = max(0.0, min(100.0, float(radius_pct))) / 100.0 * min(w, h) / 2.0
        q.drawPath(_rounded_rect_path(0, 0, w, h, [r] * 4))
    q.end()
    return img


def _silhouette_image(img, thr=96):
    """Mascara (QImage del mismo tamano; solo importa su alfa) de la silueta de una imagen con huecos, por ejemplo un marco:
    lo solido mas los huecos cerrados que quedan dentro. Lo transparente que toca el borde de la imagen queda fuera, y asi
    tambien su sombra suave. El relleno se calcula a baja resolucion y se afina con el alfa de la propia imagen."""
    a = _image_alpha(img)
    h, w = a.shape
    f = max(1, -(-max(w, h) // 200))
    if f > 1:
        hh, ww = -(-h // f), -(-w // f)
        ap = np.zeros((hh * f, ww * f), np.uint8)
        ap[:h, :w] = a
        lo = ap.reshape(hh, f, ww, f).max(axis=(1, 3))
    else:
        lo = a
    free = lo < thr
    reach = np.zeros_like(free)
    reach[0, :] = free[0, :]
    reach[-1, :] |= free[-1, :]

    reach[:, 0] |= free[:, 0]
    reach[:, -1] |= free[:, -1]
    for _i in range(4000):
        n = reach.copy()
        n[1:, :] |= reach[:-1, :]
        n[:-1, :] |= reach[1:, :]
        n[:, 1:] |= reach[:, :-1]
        n[:, :-1] |= reach[:, 1:]
        n &= free
        if np.array_equal(n, reach):
            break
        reach = n
    hole = free & ~reach
    if f > 1:
        hole = np.kron(hole, np.ones((f, f), np.uint8))[:h, :w].astype(bool)
    for _i in range(f + 1):                       # un poco mas grande que el hueco: lo tapa el aro
        g = hole.copy()
        g[1:, :] |= hole[:-1, :]

        g[:-1, :] |= hole[1:, :]
        g[:, 1:] |= hole[:, :-1]
        g[:, :-1] |= hole[:, 1:]
        hole = g
    m = np.clip((a.astype(np.int32) - int(thr)) * 255 // max(1, 255 - int(thr)), 0, 255).astype(np.uint8)
    out = np.zeros((h, w, 4), np.uint8)
    out[:, :, 3] = np.maximum(m, hole.astype(np.uint8) * 255)
    return QImage(out.tobytes(), w, h, w * 4, QImage.Format_ARGB32_Premultiplied).copy()


def _apply_clip_mask(pm, mask_img):
    """Copia de un QPixmap con solo lo que cae dentro de la mascara (su alfa), del mismo tamano."""
    out = QPixmap(pm.size())
    out.fill(Qt.transparent)
    q = QPainter(out)
    q.drawPixmap(0, 0, pm)
    q.setCompositionMode(QPainter.CompositionMode_DestinationIn)
    q.drawImage(0, 0, mask_img)
    q.end()
    return out


def _blur_image(img, r, keep_peak=0.0):
    """Desenfoque (3 pasadas de caja, ~gaussiano) de una QImage ARGB premultiplicada. Con radios grandes se hace a media o
    cuarta parte de resolucion (cuesta mucho menos). Con keep_peak > 0 se compensa lo que el desenfoque diluye (una linea fina se volveria
    invisible): se multiplica para que el pico quede en esa fraccion del original (hasta 40 veces)."""
    r = int(r)
    if r <= 0:
        return img
    im = img.convertToFormat(QImage.Format_ARGB32_Premultiplied)
    W, H = im.width(), im.height()
    sc = (4 if r >= 12 else 2 if r >= 4 else 1) if (W >= 16 and H >= 16) else 1
    half = sc > 1
    if half:
        im = im.scaled(max(1, W // sc), max(1, H // sc), Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
        r = max(1, r // sc)
    w, h = im.width(), im.height()
    arr = np.frombuffer(im.bits(), dtype=np.uint8).reshape((h, w, 4)).astype(np.float32)
    k = max(1, r)
    pre_max = float(arr[:, :, 3].max()) if keep_peak > 0 else 0.0

    for _p in range(3):
        for ax in (0, 1):
            c = np.cumsum(np.pad(arr, [(k + 1, k) if i == ax else (0, 0) for i in range(3)], mode='constant'), axis=ax)
            n = arr.shape[ax]

            def sl(a_, b_, ax=ax):
                return tuple(slice(a_, b_) if i == ax else slice(None) for i in range(3))
            arr = (c[sl(2 * k + 1, 2 * k + 1 + n)] - c[sl(0, n)]) / (2 * k + 1)
    if keep_peak > 0 and pre_max > 0:
        post_max = float(arr[:, :, 3].max())
        if post_max > 0:
            arr = arr * min(40.0, max(1.0, keep_peak * pre_max / post_max))
    out = QImage(np.clip(arr, 0, 255).astype(np.uint8).tobytes(), w, h, w * 4, QImage.Format_ARGB32_Premultiplied).copy()
    if half:
        out = out.scaled(W, H, Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
    return out


