def _fr_clean(raw):
    """Parametros de un marco validados: solo claves conocidas, del tipo correcto y dentro de rango; lo que falta toma su valor por defecto."""
    q = dict(FRAME_DEFAULTS)
    for k, dv in FRAME_DEFAULTS.items():
        if not isinstance(raw, dict) or k not in raw:
            continue
        v = raw[k]
        try:
            if isinstance(dv, bool):
                q[k] = bool(v)
            elif isinstance(dv, int):
                lo, hi = FRAME_RANGES[k]
                q[k] = max(lo, min(hi, int(round(float(v)))))
            elif isinstance(dv, str):
                if QColor(str(v)).isValid():
                    q[k] = QColor(str(v)).name()
        except (TypeError, ValueError):
            pass

    for a, b in (('bl', 'br'), ('bt', 'bb')):               # el hueco no puede desaparecer
        dim = q['w'] if a == 'bl' else q['h']
        room = max(8, dim - 8)
        if q[a] + q[b] > room:
            f = room / float(q[a] + q[b])
            q[a], q[b] = max(1, int(q[a] * f)), max(1, int(q[b] * f))
    return q


def _frame_layout(p):
    """Medidas de la imagen de un marco: margen para la sombra, tamano total y rectangulo del hueco (x, y, ancho, alto) dentro de la imagen."""
    p = _fr_clean(p)
    sh, dx, dy = p['shadow'], p['shadow_dx'], p['shadow_dy']
    pad = (sh + max(abs(dx), abs(dy)) + 2) if sh > 0 else (max(abs(dx), abs(dy)) + 2)
    hw, hh = max(4, p['w'] - p['bl'] - p['br']), max(4, p['h'] - p['bt'] - p['bb'])
    return {'pad': pad, 'W': p['w'] + 2 * pad, 'H': p['h'] + 2 * pad, 'hole': (pad + p['bl'], pad + p['bt'], hw, hh)}


def _frame_paths(p, L):
    """[PACK134] Contorno exterior y hueco de un marco: rectangulo con esquinas redondeadas o elipse."""
    pad = L['pad']
    hx, hy, hw, hh = L['hole']
    if p.get('shape', 0) == 1:
        outer, hole = QPainterPath(), QPainterPath()
        outer.addEllipse(QRectF(pad, pad, p['w'], p['h']))
        hole.addEllipse(QRectF(hx, hy, hw, hh))
        return outer, hole
    return _rounded_rect_path(pad, pad, p['w'], p['h'], [p['radius']] * 4), _rounded_rect_path(hx, hy, hw, hh, [p['iradius']] * 4)


def render_frame(p):
    """Imagen (QImage ARGB) de un marco: aro con ingletes, bisel, textura, sombra exterior y sombra interior; el hueco es transparente."""
    from PySide6.QtCore import QPointF
    import math, random
    p = _fr_clean(p)
    L = _frame_layout(p)
    pad, W, H = L['pad'], L['W'], L['H']
    hx, hy, hw, hh = L['hole']
    w, h = p['w'], p['h']
    ox, oy, ow, oh = pad, pad, w, h
    img = QImage(W, H, QImage.Format_ARGB32_Premultiplied)
    img.fill(Qt.transparent)
    q = QPainter(img)
    q.setRenderHint(QPainter.Antialiasing)
    outer, hole = _frame_paths(p, L)
    ell = p.get('shape', 0) == 1
    ring = outer.subtracted(hole)
    if p['shadow'] > 0 and p['shadow_op'] > 0:
        sp = QTransform().translate(p['shadow_dx'], p['shadow_dy']).map(ring)

        q.drawImage(0, 0, _soft_shadow(img.size(), sp, p['shadow'], QColor(p['shadow_color']), p['shadow_op'] / 100.0))
    q.setCompositionMode(QPainter.CompositionMode_Clear)
    q.setPen(Qt.NoPen)
    q.setBrush(Qt.black)
    q.drawPath(ring)
    q.setCompositionMode(QPainter.CompositionMode_SourceOver)
    if p['grad']:
        a = math.radians(p['grad_angle'])
        dx_, dy_ = math.cos(a), math.sin(a)
        half = (abs(dx_) * ow + abs(dy_) * oh) / 2.0
        cx_, cy_ = ox + ow / 2.0, oy + oh / 2.0
        g = QLinearGradient(cx_ - dx_ * half, cy_ - dy_ * half, cx_ + dx_ * half, cy_ + dy_ * half)
        g.setColorAt(0.0, QColor(p['color']))
        g.setColorAt(1.0, QColor(p['color2']))
        brush = QBrush(g)
    else:
        brush = QBrush(QColor(p['color']))
    q.setBrush(brush)

    q.drawPath(ring)

    def poly(pts):
        pa = QPainterPath()
        pa.moveTo(*pts[0])
        for x_, y_ in pts[1:]:
            pa.lineTo(x_, y_)
        pa.closeSubpath()
        return pa
    sides = {'t': [(ox, oy), (ox + ow, oy), (hx + hw, hy), (hx, hy)],
             'r': [(ox + ow, oy), (ox + ow, oy + oh), (hx + hw, hy + hh), (hx + hw, hy)],
             'b': [(ox + ow, oy + oh), (ox, oy + oh), (hx, hy + hh), (hx + hw, hy + hh)],
             'l': [(ox, oy + oh), (ox, oy), (hx, hy), (hx, hy + hh)]}
    if ell:                                   # [PACK134] elipse: una sola zona (el aro) con la textura en horizontal, sin costuras
        sides = {'t': [(ox, oy), (ox + ow, oy), (ox + ow, oy + oh), (ox, oy + oh)]}
    q.save()
    q.setClipPath(ring)
    light, dark = p['bevel_light'] * 2.55, p['bevel_dark'] * 2.55
    if ell:                                   # [PACK134] luz continua desde arriba a la izquierda (en vez de cuatro ingletes)
        from PySide6.QtGui import QConicalGradient
        _cg = QConicalGradient(ox + ow / 2.0, oy + oh / 2.0, 135)
        _cg.setColorAt(0.0, QColor(255, 255, 255, int(light * 0.30)))
        _cg.setColorAt(0.5, QColor(0, 0, 0, int(dark * 0.36)))
        _cg.setColorAt(1.0, QColor(255, 255, 255, int(light * 0.30)))
        q.setPen(Qt.NoPen)
        q.setBrush(QBrush(_cg))
        q.drawPath(ring)
    for k, col in (() if ell else (('t', QColor(255, 255, 255, int(light * 0.30))), ('l', QColor(255, 255, 255, int(light * 0.16))),
                                   ('b', QColor(0, 0, 0, int(dark * 0.36))), ('r', QColor(0, 0, 0, int(dark * 0.22))))):
        q.setPen(Qt.NoPen)
        q.setBrush(col)

        q.drawPath(poly(sides[k]))
    if p['tex'] and p['tex_amt'] > 0:
        rng = random.Random(1234)
        amt = p['tex_amt'] / 100.0
        for k, pts in sides.items():
            q.save()
            q.setClipPath(poly(pts), Qt.IntersectClip)
            xs, ys = [x_ for x_, _y in pts], [y_ for _x, y_ in pts]
            x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
            horiz = k in ('t', 'b')
            if p['tex'] == 3:
                q.setPen(Qt.NoPen)
                n = int((x1 - x0) * (y1 - y0) * 0.18)
                for _i in range(min(n, 20000)):
                    q.setBrush(QColor(255, 255, 255, int(90 * amt)) if rng.random() < 0.5 else QColor(0, 0, 0, int(90 * amt)))
                    q.drawRect(QRectF(rng.uniform(x0, x1), rng.uniform(y0, y1), 1.2, 1.2))
            else:
                step = 2.0 if p['tex'] == 1 else 1.0
                pos = (y0 if horiz else x0)
                end = (y1 if horiz else x1)
                while pos < end:
                    a_ = int(255 * amt * (rng.uniform(0.1, 0.55) if p['tex'] == 1 else rng.uniform(0.04, 0.22)))
                    q.setPen(QPen(QColor(255, 255, 255, a_) if rng.random() < 0.45 else QColor(0, 0, 0, a_), 1.0 if p['tex'] == 2 else rng.uniform(0.8, 1.8)))
                    a0, a1 = (x0, x1) if horiz else (y0, y1)
                    s = a0
                    while s < a1:
                        ln = (a1 - a0) if p['tex'] == 2 else rng.uniform(25, 140)
                        if horiz:
                            q.drawLine(QPointF(s, pos), QPointF(min(a1, s + ln), pos))
                        else:
                            q.drawLine(QPointF(pos, s), QPointF(pos, min(a1, s + ln)))
                        s += ln + (0 if p['tex'] == 2 else rng.uniform(4, 40))
                    pos += step * rng.uniform(0.7, 1.5)
            q.restore()

    b = min(float(p['bevel']), min(p['bt'], p['br'], p['bb'], p['bl']) / 2.0 - 0.5)
    if ell and b >= 0.5:                      # [PACK134] bisel de la elipse: una banda a lo largo de cada borde, con luz continua
        from PySide6.QtGui import QConicalGradient
        _ox, _oy = ox + ow / 2.0, oy + oh / 2.0
        _g1 = QConicalGradient(_ox, _oy, 135)
        _g1.setColorAt(0.0, QColor(255, 255, 255, int(min(255, light * 0.75))))
        _g1.setColorAt(0.5, QColor(0, 0, 0, int(min(255, dark * 0.75))))
        _g1.setColorAt(1.0, QColor(255, 255, 255, int(min(255, light * 0.75))))
        q.setBrush(Qt.NoBrush)
        q.setPen(QPen(QBrush(_g1), 2.0 * b))
        q.drawPath(outer)
        _g2 = QConicalGradient(_ox, _oy, 135)
        _g2.setColorAt(0.0, QColor(0, 0, 0, int(min(255, dark * 0.60))))
        _g2.setColorAt(0.5, QColor(255, 255, 255, int(min(255, light * 0.45))))
        _g2.setColorAt(1.0, QColor(0, 0, 0, int(min(255, dark * 0.60))))
        q.setPen(QPen(QBrush(_g2), 2.0 * b))
        q.drawPath(hole)
    if b >= 0.5 and not ell:
        outer_s = {'t': [(ox, oy), (ox + ow, oy), (ox + ow - b, oy + b), (ox + b, oy + b)],
                   'r': [(ox + ow, oy), (ox + ow, oy + oh), (ox + ow - b, oy + oh - b), (ox + ow - b, oy + b)],
                   'b': [(ox + ow, oy + oh), (ox, oy + oh), (ox + b, oy + oh - b), (ox + ow - b, oy + oh - b)],
                   'l': [(ox, oy + oh), (ox, oy), (ox + b, oy + b), (ox + b, oy + oh - b)]}
        inner_s = {'t': [(hx - b, hy - b), (hx + hw + b, hy - b), (hx + hw, hy), (hx, hy)],
                   'r': [(hx + hw + b, hy - b), (hx + hw + b, hy + hh + b), (hx + hw, hy + hh), (hx + hw, hy)],
                   'b': [(hx + hw + b, hy + hh + b), (hx - b, hy + hh + b), (hx, hy + hh), (hx + hw, hy + hh)],
                   'l': [(hx - b, hy + hh + b), (hx - b, hy - b), (hx, hy), (hx, hy + hh)]}
        q.setPen(Qt.NoPen)
        for k in 'tl':
            q.setBrush(QColor(255, 255, 255, int(min(255, light * 0.75))))
            q.drawPath(poly(outer_s[k]))
            q.setBrush(QColor(0, 0, 0, int(min(255, dark * 0.60))))
            q.drawPath(poly(inner_s[k]))
        for k in 'br':
            q.setBrush(QColor(0, 0, 0, int(min(255, dark * 0.75))))
            q.drawPath(poly(outer_s[k]))
            q.setBrush(QColor(255, 255, 255, int(min(255, light * 0.45))))
            q.drawPath(poly(inner_s[k]))

    if p['line'] > 0 and p['line_op'] > 0:
        q.setBrush(Qt.NoBrush)
        q.setPen(QPen(QColor(0, 0, 0, int(255 * p['line_op'] / 100.0)), p['line'] * 2.0))
        q.drawPath(hole)
    q.restore()
    q.setCompositionMode(QPainter.CompositionMode_Clear)
    q.setPen(Qt.NoPen)
    q.setBrush(Qt.black)
    q.drawPath(hole)
    q.setCompositionMode(QPainter.CompositionMode_SourceOver)
    if p['ishadow'] > 0 and p['ishadow_op'] > 0:
        q.save()
        q.setClipPath(hole)
        q.drawImage(0, 0, _soft_shadow(img.size(), ring, p['ishadow'], QColor(0, 0, 0), p['ishadow_op'] / 100.0))
        q.restore()
    q.end()
    return img


def _gen_frame_image(p):
    """Ruta guardable de la imagen de un marco con los parametros p (la dibuja si hace falta; el nombre sale de los parametros)."""
    p = _fr_clean(p)
    tag = hashlib.md5(json.dumps({k: v for k, v in p.items() if not (k == 'shape' and not v)}, sort_keys=True).encode('utf-8')).hexdigest()[:16]
    path = os.path.join(FRAMES_DIR, "marco_%s.png" % tag)
    if not os.path.exists(path):
        os.makedirs(FRAMES_DIR, exist_ok=True)
        render_frame(p).save(path, 'PNG')
    return _store_path(path)


def _ensure_frame_layer(td):
    """Si la capa 1 es la imagen de un marco editable y su archivo ya no esta, se dibuja de nuevo desde frame_shape. True si cambio algo."""
    try:
        fs = td.get('frame_shape') if isinstance(td, dict) else None
        l1 = td.get('layer1') if isinstance(td, dict) else None
        if not isinstance(fs, dict) or not isinstance(l1, dict) or l1.get('type') != 'png':
            return False
        c = str(l1.get('content') or '')
        if not os.path.basename(c.replace('\\', '/')).startswith('marco_') or _find_stored_file(c, 1):
            return False
        l1['content'] = _gen_frame_image(fs)
        return True
    except Exception as e:
        log_warn("Marcos", "No se pudo dibujar de nuevo el marco: %s" % e)
        return False


def _frame_sample_picture(w, h):
    """Paisaje de ejemplo para ver el marco con algo dentro."""
    from PySide6.QtCore import QPointF
    im = QImage(max(1, w), max(1, h), QImage.Format_ARGB32_Premultiplied)
    im.fill(QColor('#9fd3e6'))
    q = QPainter(im)
    q.setRenderHint(QPainter.Antialiasing)
    q.setPen(Qt.NoPen)
    q.setBrush(QColor('#fde68a'))
    q.drawEllipse(QPointF(w * 0.76, h * 0.26), min(w, h) * 0.10, min(w, h) * 0.10)
    for col, pts in (('#4f8f6a', [(0, 1.0), (0, 0.62), (0.25, 0.42), (0.5, 0.62), (0.7, 0.5), (1.0, 0.72), (1.0, 1.0)]),
                     ('#356b52', [(0, 1.0), (0, 0.78), (0.3, 0.64), (0.6, 0.78), (1.0, 0.68), (1.0, 1.0)])):
        pa = QPainterPath()
        pa.moveTo(pts[0][0] * w, pts[0][1] * h)
        for x_, y_ in pts[1:]:
            pa.lineTo(x_ * w, y_ * h)
        pa.closeSubpath()
        q.setBrush(QColor(col))

        q.drawPath(pa)
    q.end()
    return im


# ---------------------------------------------------------------- [PACK137] .waframe y "Mis marcos"
MARCOS_DIR = os.path.join(ROOT_DATA_DIR, "marcos")          # [PACK137] biblioteca "Mis marcos": un .waframe por marco


def frame_clean_name(s):
    """Nombre de marco apto para archivo ('' si no queda nada)."""
    return re.sub(r'[\\/:*?"<>|\x00-\x1f]', '', str(s or '')).strip(' .')[:60]


def frame_thumb_png(p, side=160):
    """PNG pequeno (bytes) de un marco sobre fondo transparente, para ver el marco sin abrir el editor."""
    from PySide6.QtCore import QBuffer, QByteArray, QIODevice
    img = render_frame(p)
    if max(img.width(), img.height()) > side:
        img = img.scaled(side, side, Qt.KeepAspectRatio, Qt.SmoothTransformation)
    ba = QByteArray()
    buf = QBuffer(ba)
    buf.open(QIODevice.WriteOnly)
    img.save(buf, 'PNG')
    return bytes(ba)


def frame_file_write(path, p, name=''):
    """Guarda un marco en un .waframe: sus parametros (el marco se dibuja de nuevo al abrirlo) y una miniatura."""
    p = _fr_clean(p)
    imgs = {}
    try:
        imgs['preview.png'] = frame_thumb_png(p)
    except Exception as e:
        log_warn('marco', "Sin miniatura en el .waframe: %s" % e)
    wa_file_write(path, 'frame', {'name': str(name or '')[:80], 'frame_shape': p}, imgs)


def frame_read_any(path):
    """(nombre, parametros) de un .waframe o de un .json con un marco (el que copia el editor). ValueError si no es un marco."""
    import zipfile
    if zipfile.is_zipfile(path):
        if wa_file_kind(path) != 'frame':
            raise ValueError("no es un marco de Widget Arena (.waframe)")
        with zipfile.ZipFile(path) as z:
            if z.getinfo('data.json').file_size > (1 << 20):
                raise ValueError("el archivo es demasiado grande para ser un marco")
            d = json.loads(z.read('data.json').decode('utf-8'))
    else:
        if os.path.getsize(path) > (1 << 20):
            raise ValueError("el archivo es demasiado grande para ser un marco")
        with open(path, 'r', encoding='utf-8') as f:
            d = json.load(f)
    fs = d.get('frame_shape') if isinstance(d, dict) else None
    if fs is None and isinstance(d, dict) and any(k in d for k in FRAME_DEFAULTS):
        fs = d

    if not isinstance(fs, dict) or not any(k in fs for k in FRAME_DEFAULTS):
        raise ValueError("el archivo no contiene un marco")
    return frame_clean_name(d.get('name') if isinstance(d, dict) else '') or wa_stem(path), _fr_clean(fs)


def frame_lib_path(name):
    return os.path.join(MARCOS_DIR, frame_clean_name(name) + '.waframe')


def frame_lib_list():
    """[(nombre, ruta)] de los marcos de Mis marcos, por orden alfabetico."""
    try:
        names = os.listdir(MARCOS_DIR)
    except OSError:
        return []
    return sorted([(f[:-8], os.path.join(MARCOS_DIR, f)) for f in names if f.lower().endswith('.waframe')], key=lambda t: t[0].lower())


def frame_lib_get(name):
    """Parametros del marco 'name' de Mis marcos (ValueError si no esta o no se lee)."""
    path = frame_lib_path(name)
    if not os.path.isfile(path):
        raise ValueError("no hay ning\u00fan marco llamado \u00ab%s\u00bb" % name)
    return frame_read_any(path)[1]


def frame_lib_find(p):
    """Nombre del marco de Mis marcos que tiene exactamente estos parametros (sin contar el tamano), o None."""
    key = {k: v for k, v in _fr_clean(p).items() if k not in ('w', 'h')}
    for n, path in frame_lib_list():
        try:
            q = frame_read_any(path)[1]
        except Exception:
            continue
        if {k: v for k, v in q.items() if k not in ('w', 'h')} == key:
            return n
    return None


def frame_lib_save(name, p, overwrite=False):
    """Guarda p en Mis marcos y devuelve el nombre con el que quedo (si ya hay uno con ese nombre y no se pide reemplazar, 'nombre 2', 'nombre 3'...)."""
    base = frame_clean_name(name) or "Marco"
    os.makedirs(MARCOS_DIR, exist_ok=True)
    cand, i = base, 2
    while not overwrite and os.path.exists(frame_lib_path(cand)):
        cand = "%s %d" % (base, i)
        i += 1
    frame_file_write(frame_lib_path(cand), p, cand)
    return cand


def frame_lib_delete(name):
    try:
        os.remove(frame_lib_path(name))
        return True
    except OSError:
        return False


class FrameDialog(QDialog):
    """[PACK131] Editor de marcos: grosor de cada lado, color o degradado, bisel, textura y sombras, con una vista previa sobre un paisaje de ejemplo."""

    def __init__(self, manager, parent=None, start=None, editing=False, live=None):
        super().__init__(parent)
        from PySide6.QtWidgets import QSpinBox as _SB, QTabWidget, QScrollArea
        self.setWindowTitle("Editar marco" if editing else "Generar marco")
        self._mgr = manager
        self._live = live                   # [PACK133] funcion(parametros | None, ajustar) que pinta los cambios en el widget real; None = volver a como estaba
        self.p = _fr_clean(start)
        self._building = True
        self._sync = []
        root = QHBoxLayout(self)
        left = QVBoxLayout()
        root.addLayout(left, 1)
        prow = QHBoxLayout()
        prow.addWidget(QLabel("Punto de partida:"))
        for name, d in FRAME_PRESETS:
            b = QPushButton(name)
            b.clicked.connect(lambda _c=False, d=d: self._apply(d))
            prow.addWidget(b)
        prow.addStretch(1)

        left.addLayout(prow)
        xrow = QHBoxLayout()
        xrow.addWidget(QLabel("JSON:"))
        for txt, fn, tip in (("Copiar marco", self._copy, "Copia los par\u00e1metros de este marco al portapapeles (JSON)"),
                             ("Pegar marco", self._paste, "Aplica aqu\u00ed unos par\u00e1metros de marco copiados")):
            b = QPushButton(txt)
            b.setToolTip(tip)
            b.clicked.connect(lambda _c=False, f=fn: f())
            xrow.addWidget(b)
        xrow.addStretch(1)
        left.addLayout(xrow)
        lrow = QHBoxLayout()                                    # [PACK137] Mis marcos
        lrow.addWidget(QLabel("Mis marcos:"))
        self.cb_lib = QComboBox()
        self.cb_lib.setMinimumWidth(150)
        self.cb_lib.setToolTip("Marcos que guardaste. Al elegir uno se aplica aqu\u00ed (conserva el tama\u00f1o actual).")
        lrow.addWidget(self.cb_lib)
        self.btn_lib_del = QPushButton("Borrar")
        for txt, fn, tip, attr in (("Guardar aqu\u00ed...", self._lib_save, "Guarda este marco en Mis marcos con un nombre", None),
                                   ("Exportar...", self._lib_export, "Guarda este marco en un archivo .waframe para compartirlo", None),
                                   ("Importar...", self._lib_import, "Trae un marco de un archivo .waframe (o .json), lo guarda en Mis marcos y lo aplica", None),
                                   ("Borrar", self._lib_delete, "Quita de Mis marcos el marco elegido", 'btn_lib_del')):
            b = self.btn_lib_del if attr else QPushButton(txt)
            b.setToolTip(tip)
            b.clicked.connect(lambda _c=False, f=fn: f())
            lrow.addWidget(b)
        lrow.addStretch(1)
        left.addLayout(lrow)
        self.cb_lib.activated.connect(self._lib_pick)
        self._lib_fill()
        tabs = QTabWidget()
        left.addWidget(tabs, 1)

        def page(title):
            w_ = QWidget()
            f_ = QFormLayout(w_)
            f_.setRowWrapPolicy(QFormLayout.WrapLongRows)
            sa = QScrollArea()
            sa.setWidgetResizable(True)
            sa.setFrameShape(QFrame.NoFrame)
            sa.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            sa.setWidget(w_)
            tabs.addTab(sa, title)
            return f_

        def spin(key, suffix=" px"):
            s = _SB()
            lo, hi = FRAME_RANGES[key]
            s.setRange(lo, hi)
            s.setSuffix(suffix)
            s.setValue(int(self.p[key]))
            s.valueChanged.connect(lambda v, k=key: self._set(k, int(v)))
            self._sync.append(lambda s=s, k=key: s.setValue(int(self.p[k])))
            return s

        def color_btn(key):
            b = QPushButton()
            b.setFixedWidth(70)

            def paint():
                b.setStyleSheet("background:%s;border:1px solid #666;min-height:18px;" % self.p[key])

            def pick():
                c = QColorDialog.getColor(QColor(self.p[key]), self, "Color")
                if c.isValid():
                    self._set(key, c.name())
                    paint()
            b.clicked.connect(pick)
            self._sync.append(paint)
            paint()
            return b

        f1 = page("Tama\u00f1o y grosor")
        row = QHBoxLayout()
        self.sp_w, self.sp_h = spin('w'), spin('h')
        row.addWidget(self.sp_w)
        row.addWidget(QLabel("\u00d7"))
        row.addWidget(self.sp_h)
        f1.addRow("Tama\u00f1o exterior (ancho \u00d7 alto)", row)
        self.cb_shape = QComboBox()                # [PACK134]
        self.cb_shape.addItems(["Rect\u00e1ngulo (con esquinas redondeables)", "Elipse (\u00f3valo o c\u00edrculo)"])
        self.cb_shape.setCurrentIndex(int(self.p['shape']))
        self.cb_shape.currentIndexChanged.connect(lambda i: self._set('shape', int(i)))
        self._sync.append(lambda: self.cb_shape.setCurrentIndex(int(self.p['shape'])))
        f1.addRow("Forma", self.cb_shape)
        self.chk_same = QCheckBox("El mismo grosor en los cuatro lados")
        self.chk_same.setChecked(len({self.p['bt'], self.p['br'], self.p['bb'], self.p['bl']}) == 1)
        f1.addRow(self.chk_same)
        self.sp_b = {k: spin(k) for k in ('bt', 'br', 'bb', 'bl')}
        for k, lab in (('bt', "Grosor arriba"), ('br', "Grosor a la derecha"), ('bb', "Grosor abajo"), ('bl', "Grosor a la izquierda")):
            f1.addRow(lab, self.sp_b[k])
        self.sp_rad, self.sp_irad = spin('radius'), spin('iradius')
        f1.addRow("Esquina exterior", self.sp_rad)
        f1.addRow("Esquina del hueco", self.sp_irad)
        f2 = page("Color y relieve")
        f2.addRow("Color", color_btn('color'))
        self.chk_grad = QCheckBox("Degradado hacia otro color")

        self.chk_grad.setChecked(bool(self.p['grad']))
        self.chk_grad.toggled.connect(lambda on: self._set('grad', bool(on)))
        self._sync.append(lambda: self.chk_grad.setChecked(bool(self.p['grad'])))
        f2.addRow(self.chk_grad)
        f2.addRow("Segundo color", color_btn('color2'))
        f2.addRow("Direcci\u00f3n del degradado", spin('grad_angle', " \u00b0"))
        f2.addRow("Bisel (ancho)", spin('bevel'))
        f2.addRow("Luz del bisel", spin('bevel_light', " %"))
        f2.addRow("Sombra del bisel", spin('bevel_dark', " %"))
        self.cb_tex = QComboBox()
        self.cb_tex.addItems(FRAME_TEXTURES)
        self.cb_tex.setCurrentIndex(int(self.p['tex']))
        self.cb_tex.currentIndexChanged.connect(lambda i: self._set('tex', int(i)))
        self._sync.append(lambda: self.cb_tex.setCurrentIndex(int(self.p['tex'])))
        f2.addRow("Textura", self.cb_tex)
        f2.addRow("Intensidad de la textura", spin('tex_amt', " %"))
        f3 = page("Sombras y filo")
        f3.addRow("Sombra sobre la imagen (tama\u00f1o)", spin('ishadow'))

        f3.addRow("Sombra sobre la imagen (opacidad)", spin('ishadow_op', " %"))
        f3.addRow("Filo oscuro del hueco (grosor)", spin('line'))
        f3.addRow("Filo oscuro del hueco (opacidad)", spin('line_op', " %"))
        f3.addRow("Sombra exterior (tama\u00f1o)", spin('shadow'))
        f3.addRow("Sombra exterior (opacidad)", spin('shadow_op', " %"))
        f3.addRow("Sombra exterior: desplazamiento horizontal", spin('shadow_dx'))
        f3.addRow("Sombra exterior: desplazamiento vertical", spin('shadow_dy'))
        f3.addRow("Color de la sombra exterior", color_btn('shadow_color'))
        right = QVBoxLayout()
        root.addLayout(right, 1)
        self.preview = QLabel()
        self.preview.setAlignment(Qt.AlignCenter)
        self.preview.setMinimumSize(340, 340)
        right.addWidget(self.preview, 1)
        right.addWidget(QLabel("La vista previa muestra el marco sobre un paisaje de ejemplo."))
        self.chk_fit = QCheckBox("Ajustar la imagen o la p\u00e1gina de la capa 2 al hueco del marco")
        self.chk_fit.setChecked(True)
        right.addWidget(self.chk_fit)
        self.chk_live = QCheckBox("Ver los cambios en el widget real mientras edito")      # [PACK133]
        self.chk_live.setChecked(True)
        self.chk_live.setVisible(live is not None)
        self.chk_live.toggled.connect(self._live_toggled)
        self.chk_fit.toggled.connect(lambda _on: self._live_schedule())
        right.addWidget(self.chk_live)
        self._live_timer = QTimer(self)
        self._live_timer.setSingleShot(True)
        self._live_timer.setInterval(140)
        self._live_timer.timeout.connect(self._live_fire)

        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        bb.button(QDialogButtonBox.Ok).setText("Aplicar" if editing else "Generar")
        bb.button(QDialogButtonBox.Cancel).setText("Cancelar")
        bb.accepted.connect(self.accept)
        bb.rejected.connect(self.reject)
        right.addWidget(bb)
        self.chk_same.toggled.connect(self._same_toggled)
        self._building = False
        self.resize(900, 560)
        self._refresh(live=False)

    # ---- [PACK137] Mis marcos y .waframe
    def _lib_fill(self, select=None):
        self.cb_lib.blockSignals(True)
        self.cb_lib.clear()
        self.cb_lib.addItem("(elige uno)" if frame_lib_list() else "(vac\u00edo: guarda uno)", None)
        for n, _p in frame_lib_list():
            self.cb_lib.addItem(n, n)
        i = self.cb_lib.findData(select) if select else 0
        self.cb_lib.setCurrentIndex(max(0, i))
        self.cb_lib.blockSignals(False)
        self.btn_lib_del.setEnabled(bool(self.cb_lib.currentData()))

    def _lib_pick(self, i):
        n = self.cb_lib.itemData(i)
        self.btn_lib_del.setEnabled(bool(n))
        if not n:
            return
        try:
            p = frame_lib_get(n)
        except Exception as e:
            QMessageBox.warning(self, "Mis marcos", "No se pudo leer el marco:\n%s" % e)
            return
        self._apply(p)

    def _lib_save(self):
        name, ok = QInputDialog.getText(self, "Guardar en Mis marcos", "Nombre del marco:", text=self.cb_lib.currentData() or "")
        name = frame_clean_name(name)
        if not ok or not name:
            return None
        same = os.path.exists(frame_lib_path(name))
        if same and QMessageBox.question(self, "Mis marcos", "Ya hay un marco llamado \u00ab%s\u00bb. \u00bfReemplazarlo?" % name,
                                         QMessageBox.Yes | QMessageBox.No, QMessageBox.No) != QMessageBox.Yes:
            return None
        saved = frame_lib_save(name, self.p, overwrite=same)
        self._lib_fill(saved)
        return saved

    def _lib_export(self):
        base = self.cb_lib.currentData() or "marco"
        path, flt = QFileDialog.getSaveFileName(self, "Exportar marco", os.path.join(DATA_DIR, base + ".waframe"), WA_FILTER['frame'])
        if not path:
            return None
        path, as_json = wa_out_path(path, 'frame', flt)
        try:
            if as_json:
                with open(path, 'w', encoding='utf-8') as f:
                    json.dump({"frame_shape": self.p}, f, indent=2, ensure_ascii=False)
            else:
                frame_file_write(path, self.p, wa_stem(path))
        except OSError as e:
            QMessageBox.warning(self, "Exportar marco", "No se pudo guardar el archivo:\n%s" % e)
            return None
        return path

    def _lib_import(self):
        path, _f = QFileDialog.getOpenFileName(self, "Importar marco", DATA_DIR, "Marcos (*.waframe *.json);;Todos (*)")
        if not path:
            return None
        try:
            name, p = frame_read_any(path)
        except Exception as e:
            QMessageBox.warning(self, "Importar marco", "No se pudo leer el marco:\n%s" % e)
            return None
        saved = frame_lib_find(p) or frame_lib_save(name, p)
        self._lib_fill(saved)
        self._apply(p)
        return saved

    def _lib_delete(self):
        n = self.cb_lib.currentData()
        if not n:
            return
        if QMessageBox.question(self, "Mis marcos", "\u00bfQuitar \u00ab%s\u00bb de Mis marcos?" % n, QMessageBox.Yes | QMessageBox.No, QMessageBox.No) != QMessageBox.Yes:
            return
        frame_lib_delete(n)
        self._lib_fill()

    def _same_toggled(self, on):
        if on:
            v = self.p['bt']
            self._set_many({'bt': v, 'br': v, 'bb': v, 'bl': v})

    def _set(self, key, value):
        if self._building:
            return
        if key in ('bt', 'br', 'bb', 'bl') and self.chk_same.isChecked():
            self._set_many({'bt': value, 'br': value, 'bb': value, 'bl': value})
            return
        self.p[key] = value
        self.p = _fr_clean(self.p)
        self._refresh()

    def _set_many(self, d):
        self.p.update(d)
        self.p = _fr_clean(self.p)
        self._building = True
        for f in self._sync:
            f()
        self._building = False
        self._refresh()

    def _apply(self, d):
        q = dict(FRAME_DEFAULTS)
        q.update(d)
        q['w'], q['h'] = self.p['w'], self.p['h']
        self.p = _fr_clean(q)
        self._building = True
        self.chk_same.setChecked(len({self.p['bt'], self.p['br'], self.p['bb'], self.p['bl']}) == 1)
        for f in self._sync:
            f()
        self._building = False
        self._refresh()

    def _refresh(self, live=True):
        if hasattr(self, 'sp_rad'):                # [PACK134] con la elipse las esquinas no cuentan
            self.sp_rad.setEnabled(int(self.p['shape']) == 0)
            self.sp_irad.setEnabled(int(self.p['shape']) == 0)
        L = _frame_layout(self.p)
        fr = render_frame(self.p)
        bg = QImage(fr.size(), QImage.Format_ARGB32_Premultiplied)
        bg.fill(QColor('#e9ecef'))
        q = QPainter(bg)
        q.setPen(Qt.NoPen)
        q.setBrush(QColor('#dde1e6'))
        cell = 12
        for yy in range(0, bg.height(), cell):
            for xx in range(0, bg.width(), cell):
                if ((xx // cell) + (yy // cell)) % 2:
                    q.drawRect(xx, yy, cell, cell)
        hx, hy, hw, hh = L['hole']
        t = 3
        q.save()
        q.setClipPath(_frame_paths(self.p, L)[0])   # [PACK134] la imagen se recorta por la silueta del marco, como en el widget
        q.drawImage(hx - t, hy - t, _frame_sample_picture(hw + 2 * t, hh + 2 * t))
        q.restore()
        q.drawImage(0, 0, fr)
        q.end()

        pm = QPixmap.fromImage(bg)
        box = self.preview.size() - QSize(8, 8) if self.preview.width() > 60 else QSize(340, 340)
        self.preview.setPixmap(pm.scaled(max(100, box.width()), max(100, box.height()), Qt.KeepAspectRatio, Qt.SmoothTransformation))
        if live:
            self._live_schedule()

    def resizeEvent(self, e):
        super().resizeEvent(e)
        if hasattr(self, 'preview') and not self._building:
            self._refresh(live=False)

    def _live_schedule(self):
        if self._live is not None and not self._building and self.chk_live.isChecked():
            self._live_timer.start()

    def _live_fire(self):
        if self._live is not None and self.chk_live.isChecked():
            self._live(copy.deepcopy(self.p), self.chk_fit.isChecked())

    def _live_toggled(self, on):
        if self._live is None:
            return
        if on:
            self._live_fire()
        else:
            self._live(None)                            # deja el widget real como estaba

    def done(self, r):
        self._live_timer.stop()
        super().done(r)

    def _copy(self):
        QApplication.clipboard().setText(json.dumps({"frame_shape": self.p}, indent=2, ensure_ascii=False))

    def _paste(self):
        try:
            obj = json.loads(QApplication.clipboard().text())
        except ValueError:
            QMessageBox.information(self, "Pegar marco", "El portapapeles no tiene un marco copiado (JSON).")
            return
        if isinstance(obj, dict) and isinstance(obj.get('frame_shape'), dict):
            obj = obj['frame_shape']
        if not isinstance(obj, dict) or not any(k in obj for k in FRAME_DEFAULTS):
            QMessageBox.information(self, "Pegar marco", "El portapapeles no tiene un marco copiado (JSON).")
            return
        q = dict(self.p)
        q.update({k: v for k, v in obj.items() if k in FRAME_DEFAULTS})
        self.p = _fr_clean(q)
        self._building = True
        for f in self._sync:
            f()
        self._building = False

        self._refresh()

    def get_params(self):
        return _fr_clean(self.p)


def render_base_note(p, with_text=False):
    """Imagen (QImage ARGB) de una nota base: esquinas, borde, degradado, franja adhesiva, esquinas dobladas o
    levantadas (cada esquina con su modo, su forma y sus luces) y sombra. Tiene un margen transparente para la sombra;
    la mascara de la ventana sigue la forma real."""
    from PySide6.QtCore import QRectF
    import math
    w, h = max(20, int(p['w'])), max(20, int(p['h']))
    sh, dx, dy = max(0, int(p.get('shadow', 0))), int(p.get('shadow_dx', 0)), int(p.get('shadow_dy', 0))
    pad = (sh + max(abs(dx), abs(dy)) + 2) if sh > 0 else (max(abs(dx), abs(dy)) + 2)
    cxs = [(i, c) for i, c in enumerate(_norm_cx(p)) if c['mode']] if p.get('fold') else []
    for _i, c in cxs:
        if c['mode'] == 2:               # margen: luces detras de la nota y sombra proyectada por la esquina
            for k in ('la', 'lb'):
                if int(c[k + '_a']) > 0 and not c['front']:
                    pad = max(pad, int(c[k + '_s']) + 2 + max(abs(int(c[k + '_dx'])), abs(int(c[k + '_dy']))))
            if int(c['cast']) > 0 and sh > 0:
                pad = max(pad, sh + int(c['cast']) + max(abs(dx), abs(dy)) + 2)
    img = QImage(w + 2 * pad, h + 2 * pad, QImage.Format_ARGB32_Premultiplied)
    img.fill(Qt.transparent)
    q = QPainter(img)
    q.setRenderHint(QPainter.Antialiasing)
    r = float(p['radius'])
    radii = [r if c else 0.0 for c in p['corners']]
    body = _rounded_rect_path(pad, pad, w, h, radii)
    whole = _rounded_rect_path(0, 0, img.width(), img.height(), (0, 0, 0, 0))
    flaps = []                           # esquinas dobladas: (solapa, centro del doblez, punta, direccion, ajustes)
    pieces = []                          # esquinas levantadas: (trozo que se levanta, ajustes)
    for i, c in cxs:
        shape_fn, flap, fmid, ftip, fdir = _fold_shapes(_cx_shape(i, c), w, h, pad)
        before = body
        body = shape_fn(body).intersected(whole)
        if c['mode'] == 2:
            pieces.append((before.subtracted(body), c))
        else:
            flaps.append((flap, fmid, ftip, fdir, c))
    outline = body
    if sh > 0:
        op = max(0, min(100, int(p.get('shadow_op', 40)))) / 100.0
        sp = QTransform().translate(dx, dy).map(outline)
        d_len = math.hypot(dx, dy)
        ux, uy = (dx / d_len, dy / d_len) if d_len > 0.01 else (0.0, 1.0)
        for piece, c in pieces:          # la esquina levantada flota: su sombra se separa de la nota y deforma el contorno
            cs = int(c['cast'])
            if cs > 0:
                sp = sp.united(QTransform().translate(dx + ux * cs, dy + uy * cs).map(piece))
        q.drawImage(0, 0, _soft_shadow(img.size(), sp, sh, QColor(p.get('shadow_color', '#000000')), op))
    brush = _grad_brush(p, w, h, pad)

    def lights(front):
        for piece, c in pieces:
            if bool(c['front']) != front:
                continue
            for k in ('la', 'lb'):
                if int(c[k + '_a']) > 0:
                    moved = QTransform().translate(int(c[k + '_dx']), int(c[k + '_dy'])).map(piece)
                    q.drawImage(0, 0, _shade_layer(img.size(), moved, int(c[k + '_s']), int(c[k + '_k']) == 1, int(c[k + '_a'])))
    lights(False)
    q.setCompositionMode(QPainter.CompositionMode_Clear)

    q.setPen(Qt.NoPen)
    q.setBrush(Qt.black)
    q.drawPath(body)                     # la sombra no debe verse a traves de un fondo semitransparente
    q.setCompositionMode(QPainter.CompositionMode_SourceOver)
    q.setBrush(brush)
    q.drawPath(body)
    st_h = max(0, int(p.get('strip', 0)))
    if st_h > 0:                         # franja adhesiva: una banda algo mas clara arriba, con un fino filo inferior
        q.save()
        q.setClipPath(body)
        so = max(0, min(100, int(p.get('strip_op', 30)))) / 100.0
        sy0 = pad + max(0, int(p.get('strip_y', 0)))
        q.fillRect(QRectF(pad, sy0, w, st_h), QColor(255, 255, 255, int(255 * so)))
        q.fillRect(QRectF(pad, sy0 + st_h, w, 1.2), QColor(0, 0, 0, int(60 * so)))
        q.restore()
    bw = float(p.get('border', 0))
    if bw > 0:                           # [PACK132] el borde es una corona con su propio degradado y su opacidad
        if not flaps and not pieces:
            ring = body.subtracted(_rounded_rect_path(pad + bw, pad + bw, max(1.0, w - 2 * bw), max(1.0, h - 2 * bw), [max(0.0, x - bw) for x in radii]))
        else:
            _st = QPainterPathStroker()
            _st.setWidth(2 * bw)
            ring = _st.createStroke(body).intersected(body)
        _paint_ring(q, ring, _edge_brush(p, EDGE_BORDER, QRectF(pad, pad, w, h)), _edge_translucent(p, EDGE_BORDER))

    q.save()
    q.setClipPath(body)
    lights(True)
    q.restore()
    for flap, fmid, ftip, fdir, c in flaps:
        q.save()
        q.setClipPath(body)              # la solapa nunca sobresale del papel
        fs, fo = max(0, int(c['fa_s'])), max(0, int(c['fa_a'])) / 100.0
        if fs > 0 and fo > 0:            # luz que la solapa proyecta sobre el papel (sombra o brillo)
            off = fs * 0.35
            sh_path = QTransform().translate(fdir[0] * off + int(c['fa_dx']), fdir[1] * off + int(c['fa_dy'])).map(flap)
            q.drawImage(0, 0, _soft_shadow(img.size(), sh_path, fs, QColor(255, 255, 255) if int(c['fa_k']) == 1 else QColor(60, 30, 0), min(fo, 3.0)))
        tsh, ts = int(c['fb_a']), max(2, int(c['fb_s']))
        pt = {'fold_round': c['rlen'], 'tip_dx': c['fb_dx'], 'tip_dy': c['fb_dy']}
        tw = int(c['fb_k']) == 1
        if tsh > 0 and not c['fb_over']:                     # luz BAJO la punta (sobre el papel)
            q.drawImage(0, 0, _shade_layer(img.size(), _tip_blob(pt, flap, ftip, fdir, ts, ts * 0.3), ts, tw, tsh))
        fc = _fold_color({'color': p['color'], 'grad': p.get('grad'), 'color2': p.get('color2', p['color']),
                          'fold_auto': c['rev_auto'], 'fold_color': c['rev_color']})
        _pc = _paper_colors(p)                               # [PACK132] el reverso es el mismo papel: misma opacidad
        fc.setAlphaF((_pc[0].alphaF() + (_pc[1].alphaF() if p.get('grad') else _pc[0].alphaF())) / 2.0)
        fg = QLinearGradient(fmid, ftip)
        fg.setColorAt(0.0, fc.lighter(128))
        fg.setColorAt(1.0, fc.darker(112))
        q.setPen(Qt.NoPen)
        q.setBrush(QBrush(fg))
        q.drawPath(flap)
        fbw = float(p.get('fold_bw', 0))
        if fbw > 0:                                          # [PACK132] borde del doblez: grosor, color, degradado y opacidad propios
            _st = QPainterPathStroker()
            _st.setWidth(2 * fbw)
            _paint_ring(q, _st.createStroke(flap).intersected(flap), _edge_brush(p, EDGE_FOLD, flap.boundingRect()), _edge_translucent(p, EDGE_FOLD))
        else:
            q.setPen(QPen(QColor(255, 255, 255, 90), 1.0))      # brillo del filo del doblez
            q.setBrush(Qt.NoBrush)
            q.drawPath(flap)
        if tsh > 0 and c['fb_over']:                         # luz SOBRE la punta
            q.setClipPath(flap, Qt.IntersectClip)
            q.drawImage(0, 0, _shade_layer(img.size(), _tip_blob(pt, flap, ftip, fdir, ts, 0.0), ts, tw, tsh))
        q.restore()
    if with_text and str(p.get('text', '')).strip():
        q.setPen(QColor(p['text_color']))
        q.setFont(QFont('Inter', int(p.get('font_size', 22))))
        q.drawText(QRectF(pad + 10, pad + 10, w - 20, h - 20), Qt.AlignHCenter | Qt.AlignTop | Qt.TextWordWrap, str(p['text']))
    q.end()
    return img

def _dominant_color(pixmap):
    """Color dominante (lo que se ve) de una imagen: histograma de tono ponderado por saturacion*brillo sobre los pixeles
    opacos; se promedia el entorno del tono mas frecuente. Si casi no hay color (imagen gris) devuelve el color medio."""
    img = pixmap.toImage().convertToFormat(QImage.Format_RGBA8888)
    w, h = img.width(), img.height()
    if w < 2 or h < 2:
        return QColor(160, 160, 164)
    try:
        arr = np.frombuffer(img.bits(), dtype=np.uint8).reshape((h, w, 4))
    except Exception:
        arr = np.array(img.bits(), copy=True).reshape((h, w, 4))
    step = max(1, int((w * h / 40000.0) ** 0.5))
    a = arr[::step, ::step].astype(np.float32)
    vis = a[:, :, 3] > 40
    rgb = a[:, :, :3][vis] / 255.0
    if len(rgb) == 0:
        return QColor(160, 160, 164)
    r, g, b = rgb[:, 0], rgb[:, 1], rgb[:, 2]
    mx, mn = rgb.max(axis=1), rgb.min(axis=1)
    d = mx - mn
    s = np.where(mx > 1e-6, d / np.maximum(mx, 1e-6), 0.0)
    wgt = np.where(s > 0.12, s * mx, 0.0)
    if wgt.sum() < 0.02 * len(rgb):
        m_ = rgb.mean(axis=0)
        return QColor.fromRgbF(float(m_[0]), float(m_[1]), float(m_[2]))
    dd = np.maximum(d, 1e-6)
    hh = np.where(mx == r, ((g - b) / dd) % 6.0, np.where(mx == g, (b - r) / dd + 2.0, (r - g) / dd + 4.0)) * 60.0
    idx = (hh // 10.0).astype(int) % 36
    hist = np.bincount(idx, weights=wgt, minlength=36)
    b0 = int((hist + np.roll(hist, 1) + np.roll(hist, -1)).argmax())
    near = np.abs(((idx - b0 + 18) % 36) - 18) <= 1
    ww = wgt * near
    ang = np.deg2rad(hh)
    hm = float(np.degrees(np.arctan2((ww * np.sin(ang)).sum(), (ww * np.cos(ang)).sum())) % 360.0)
    sm = float((s * ww).sum() / ww.sum())
    vm = float((mx * ww).sum() / ww.sum())
    return QColor.fromHsvF(hm / 360.0, min(1.0, sm), min(1.0, vm))


